window.__CONTENT_EN__=window.__CONTENT_EN__||{};window.__CONTENT_EN__[1]={"102":{"example:102:exzh":"His name is Tanaka.","example:102:exzh2":"Please write your name.","example:102:exzh3":"When you call someone's name.","example:102:exzh4":"I don't know the name.","example:102:exzh5":"The name is difficult.","grammar:102:ex:trans":"His name is Tanaka.","grammar:102:ex:structure":"〜の名前は〜です","grammar:102:ex:explain":"This is a possessive identifying sentence. 「彼の名前」 is joined with 「の」 to show possession: \"his name\". 「は」 makes 「彼の名前」 the topic, and the predicate 「田中です」 uses 「です」 for a polite assertion. 「田中」 is a common Japanese surname. The whole sentence 「彼の名前は田中です」 = \"His name is Tanaka\". The frame 「〜の名前は〜です」 is the basic pattern for giving or asking names, and 「の」 clearly marks whose name it is.","grammar:102:ex:words:0:zh":"he","grammar:102:ex:words:0:note":"かれ","grammar:102:ex:words:0:pos":"pronoun","grammar:102:ex:words:1:zh":"'s","grammar:102:ex:words:1:pos":"particle","grammar:102:ex:words:2:zh":"name","grammar:102:ex:words:2:note":"なまえ","grammar:102:ex:words:2:pos":"noun","grammar:102:ex:words:3:zh":"(topic)","grammar:102:ex:words:3:pos":"particle","grammar:102:ex:words:4:zh":"Tanaka","grammar:102:ex:words:4:note":"たなか; personal name","grammar:102:ex:words:4:pos":"noun","grammar:102:ex:words:5:zh":"is","grammar:102:ex:words:5:pos":"copula","grammar:102:ex:points:0":"彼の名前: his name.","grammar:102:ex:points:1":"田中: a common surname.","grammar:102:ex2:trans":"Please write your name.","grammar:102:ex2:structure":"名前を書いてください","grammar:102:ex2:words:0:zh":"name","grammar:102:ex2:words:0:note":"なまえ","grammar:102:ex2:words:0:pos":"noun","grammar:102:ex2:words:1:zh":"(object marker)","grammar:102:ex2:words:1:pos":"particle","grammar:102:ex2:words:2:zh":"write","grammar:102:ex2:words:2:note":"かいて","grammar:102:ex2:words:2:pos":"verb","grammar:102:ex2:words:3:zh":"please","grammar:102:ex2:words:3:pos":"auxiliary verb","grammar:102:ex2:points:0":"書く→書いて (te-form)＋ください.","grammar:102:ex2:points:1":"を marks the object.","grammar:102:ex3:trans":"When you call someone's name.","grammar:102:ex3:structure":"〜とき","grammar:102:ex3:words:0:zh":"name","grammar:102:ex3:words:0:note":"なまえ","grammar:102:ex3:words:0:pos":"noun","grammar:102:ex3:words:1:zh":"(object marker)","grammar:102:ex3:words:1:pos":"particle","grammar:102:ex3:words:2:zh":"call","grammar:102:ex3:words:2:note":"よぶ","grammar:102:ex3:words:2:pos":"verb","grammar:102:ex3:words:3:zh":"time","grammar:102:ex3:words:3:note":"とき","grammar:102:ex3:words:3:pos":"noun","grammar:102:ex3:points:0":"〜とき: when … (dictionary form of a verb＋とき).","grammar:102:ex3:points:1":"呼ぶ: to call, to call out.","grammar:102:ex4:trans":"I don't know the name.","grammar:102:ex4:structure":"名前を知らない","grammar:102:ex4:words:0:zh":"name","grammar:102:ex4:words:0:note":"なまえ","grammar:102:ex4:words:0:pos":"noun","grammar:102:ex4:words:1:zh":"(object marker)","grammar:102:ex4:words:1:pos":"particle","grammar:102:ex4:words:2:zh":"don't know","grammar:102:ex4:words:2:note":"しらない","grammar:102:ex4:words:2:pos":"verb","grammar:102:ex4:points:0":"知る→知らない (negative plain form).","grammar:102:ex4:points:1":"知る takes を (knowing something).","grammar:102:ex5:trans":"The name is difficult.","grammar:102:ex5:structure":"〜が難しい","grammar:102:ex5:words:0:zh":"name","grammar:102:ex5:words:0:note":"なまえ","grammar:102:ex5:words:0:pos":"noun","grammar:102:ex5:words:1:zh":"(nominative)","grammar:102:ex5:words:1:pos":"particle","grammar:102:ex5:words:2:zh":"difficult","grammar:102:ex5:words:2:note":"むずかしい","grammar:102:ex5:words:2:pos":"adjective","grammar:102:ex5:points:0":"❓Why が? It describes the name itself as difficult (the subject takes が).","grammar:102:ex5:points:1":"難しい: difficult (i-adjective).","exam:102:zh":"「山田」 is not my dog's name — it's my surname.","exam:102:why":"「名前」 means name and can refer to what a dog is called. 「声」 means voice, and a name like 「山田」 can't be treated as a voice."},"104":{"example:104:exzh":"He is my child.","example:104:exzh2":"The child is playing.","example:104:exzh3":"To watch over a child's growth.","example:104:exzh4":"Cherish children.","example:104:exzh5":"Children are their parents' treasure.","grammar:104:ex:trans":"He is my son.","grammar:104:ex:structure":"〜は〜の子です","grammar:104:ex:explain":"This is the noun identifying sentence 「彼は私の子です」. 「子（こ）」 means \"child\"; it sounds more literary or abbreviated, and in everyday speech people usually say 「子供」. 「私の子」 is joined with 「の」 to show possession: \"my child\". 「は」 makes 「彼」 the topic, and adding 「です」 to the predicate gives a polite assertion. The whole sentence 「彼は私の子です」 = \"He is my child\". Here 「の」 carries the possessive sense \"my\" and is the most basic way to link nouns.","grammar:104:ex:words:0:zh":"he","grammar:104:ex:words:0:note":"かれ","grammar:104:ex:words:0:pos":"pronoun","grammar:104:ex:words:1:zh":"(topic)","grammar:104:ex:words:1:pos":"particle","grammar:104:ex:words:2:zh":"I","grammar:104:ex:words:2:note":"わたし","grammar:104:ex:words:2:pos":"pronoun","grammar:104:ex:words:3:zh":"'s","grammar:104:ex:words:3:pos":"particle","grammar:104:ex:words:4:zh":"child","grammar:104:ex:words:4:note":"こ","grammar:104:ex:words:4:pos":"noun","grammar:104:ex:words:5:zh":"is","grammar:104:ex:words:5:pos":"copula","grammar:104:ex:points:0":"子（こ）: child (more literary / shortened form).","grammar:104:ex:points:1":"私の子: my child.","grammar:104:ex2:trans":"The child is playing.","grammar:104:ex2:structure":"子が遊んでいる","grammar:104:ex2:words:0:zh":"child","grammar:104:ex2:words:0:note":"こ","grammar:104:ex2:words:0:pos":"noun","grammar:104:ex2:words:1:zh":"(nominative)","grammar:104:ex2:words:1:pos":"particle","grammar:104:ex2:words:2:zh":"playing","grammar:104:ex2:words:2:note":"あそんでいる","grammar:104:ex2:words:2:pos":"verb","grammar:104:ex2:points:0":"子: child.","grammar:104:ex2:points:1":"〜ている: ongoing action.","grammar:104:ex3:trans":"Watch over the child's growth.","grammar:104:ex3:structure":"〜の〜を見守る","grammar:104:ex3:words:0:zh":"child","grammar:104:ex3:words:0:note":"こ","grammar:104:ex3:words:0:pos":"noun","grammar:104:ex3:words:1:zh":"'s","grammar:104:ex3:words:1:pos":"particle","grammar:104:ex3:words:2:zh":"growth","grammar:104:ex3:words:2:note":"せいちょう","grammar:104:ex3:words:2:pos":"noun","grammar:104:ex3:words:3:zh":"(object marker)","grammar:104:ex3:words:3:pos":"particle","grammar:104:ex3:words:4:zh":"watch over","grammar:104:ex3:words:4:note":"みまもる","grammar:104:ex3:words:4:pos":"verb","grammar:104:ex3:points:0":"子の成長: the child's growth.","grammar:104:ex3:points:1":"見守る: to watch over, to keep an eye on.","grammar:104:ex4:trans":"Cherish children.","grammar:104:ex4:structure":"〜を大切に（する）","grammar:104:ex4:words:0:zh":"child","grammar:104:ex4:words:0:note":"こども","grammar:104:ex4:words:0:pos":"noun","grammar:104:ex4:words:1:zh":"(object marker)","grammar:104:ex4:words:1:pos":"particle","grammar:104:ex4:words:2:zh":"with care","grammar:104:ex4:words:2:note":"たいせつに","grammar:104:ex4:words:2:pos":"adverb","grammar:104:ex4:points:0":"大切に（する）: to cherish (na-adjective＋に to make it adverbial).","grammar:104:ex4:points:1":"する is omitted.","grammar:104:ex5:trans":"Children are their parents' treasure.","grammar:104:ex5:structure":"子は親の宝","grammar:104:ex5:words:0:zh":"child","grammar:104:ex5:words:0:note":"こ","grammar:104:ex5:words:0:pos":"noun","grammar:104:ex5:words:1:zh":"(topic)","grammar:104:ex5:words:1:pos":"particle","grammar:104:ex5:words:2:zh":"parents","grammar:104:ex5:words:2:note":"おや","grammar:104:ex5:words:2:pos":"noun","grammar:104:ex5:words:3:zh":"'s","grammar:104:ex5:words:3:pos":"particle","grammar:104:ex5:words:4:zh":"treasure","grammar:104:ex5:words:4:note":"たから","grammar:104:ex5:words:4:pos":"noun","grammar:104:ex5:points:0":"親（おや）: parent.","grammar:104:ex5:points:1":"宝（たから）: treasure (proverbial style)."},"105":{"example:105:exzh":"I'll use this tool.","example:105:exzh2":"I don't want to spend money.","example:105:exzh3":"He is using Japanese.","example:105:exzh4":"To use a blog to share information.","example:105:exzh5":"There's a more efficient way to use it.","grammar:105:ex:trans":"I'll use this tool.","grammar:105:ex:structure":"〜を使います","grammar:105:ex:explain":"This is a transitive sentence of the form \"object＋を＋verb in masu-form\". 「道具」 means \"tool\", and 「この」 is a pre-noun adjectival that modifies it directly. 「を」 marks the thing being used. The verb 「使う」 ends in う and is a godan (u-) verb; in the polite form the final う changes to い and ます is added, giving 「使います」, which expresses present or future. The whole sentence 「この道具を使います」 = \"I'll use this tool\", reviewing how godan verbs ending in う form the masu-form.","grammar:105:ex:words:0:zh":"this","grammar:105:ex:words:0:pos":"pre-noun adjectival","grammar:105:ex:words:1:zh":"tool","grammar:105:ex:words:1:note":"どうぐ","grammar:105:ex:words:1:pos":"noun","grammar:105:ex:words:2:zh":"(object marker)","grammar:105:ex:words:2:pos":"particle","grammar:105:ex:words:3:zh":"use","grammar:105:ex:words:3:note":"つかいます","grammar:105:ex:words:3:pos":"verb","grammar:105:ex:points:0":"道具: tool.","grammar:105:ex:points:1":"使う→使います.","grammar:105:ex2:trans":"I don't want to spend money.","grammar:105:ex2:structure":"〜を使いたくない","grammar:105:ex2:words:0:zh":"money","grammar:105:ex2:words:0:note":"おかね","grammar:105:ex2:words:0:pos":"noun","grammar:105:ex2:words:1:zh":"(object marker)","grammar:105:ex2:words:1:pos":"particle","grammar:105:ex2:words:2:zh":"don't want to use","grammar:105:ex2:words:2:note":"つかいたくない","grammar:105:ex2:words:2:pos":"verb","grammar:105:ex2:points:0":"使う→使いたい→使いたくない (the negative of 〜たい).","grammar:105:ex2:points:1":"お金を使う: to spend money.","grammar:105:ex3:trans":"He is using Japanese.","grammar:105:ex3:structure":"〜を使っています","grammar:105:ex3:words:0:zh":"he","grammar:105:ex3:words:0:note":"かれ","grammar:105:ex3:words:0:pos":"pronoun","grammar:105:ex3:words:1:zh":"(topic)","grammar:105:ex3:words:1:pos":"particle","grammar:105:ex3:words:2:zh":"Japanese","grammar:105:ex3:words:2:note":"にほんご","grammar:105:ex3:words:2:pos":"noun","grammar:105:ex3:words:3:zh":"(object marker)","grammar:105:ex3:words:3:pos":"particle","grammar:105:ex3:words:4:zh":"is using","grammar:105:ex3:words:4:note":"つかっています","grammar:105:ex3:words:4:pos":"verb","grammar:105:ex3:points:0":"〜ている: is using (in progress).","grammar:105:ex3:points:1":"使う→使って＋います.","grammar:105:ex4:trans":"Use a blog to send out information.","grammar:105:ex4:structure":"〜を使って〜する","grammar:105:ex4:words:0:zh":"blog","grammar:105:ex4:words:0:note":"loanword","grammar:105:ex4:words:0:pos":"noun","grammar:105:ex4:words:1:zh":"(object marker)","grammar:105:ex4:words:1:pos":"particle","grammar:105:ex4:words:2:zh":"use","grammar:105:ex4:words:2:note":"つかって","grammar:105:ex4:words:2:pos":"verb","grammar:105:ex4:words:3:zh":"information","grammar:105:ex4:words:3:note":"じょうほう","grammar:105:ex4:words:3:pos":"noun","grammar:105:ex4:words:4:zh":"(object marker)","grammar:105:ex4:words:4:pos":"particle","grammar:105:ex4:words:5:zh":"send out","grammar:105:ex4:words:5:note":"はっしんする","grammar:105:ex4:words:5:pos":"verb","grammar:105:ex4:points:0":"〜を使って: using … (the te-form marks the means).","grammar:105:ex4:points:1":"発信する: to send out, to transmit.","grammar:105:ex5:trans":"There is a more efficient way to use it.","grammar:105:ex5:structure":"もっと〜に使う〜があります","grammar:105:ex5:words:0:zh":"more","grammar:105:ex5:words:0:pos":"adverb","grammar:105:ex5:words:1:zh":"efficient","grammar:105:ex5:words:1:note":"こうりつてき","grammar:105:ex5:words:1:pos":"na-adjective","grammar:105:ex5:words:2:zh":"(made adverbial)","grammar:105:ex5:words:2:pos":"particle","grammar:105:ex5:words:3:zh":"use","grammar:105:ex5:words:3:note":"つかう","grammar:105:ex5:words:3:pos":"verb","grammar:105:ex5:words:4:zh":"way, method","grammar:105:ex5:words:4:note":"ほうほう","grammar:105:ex5:words:4:pos":"noun","grammar:105:ex5:words:5:zh":"(nominative)","grammar:105:ex5:words:5:pos":"particle","grammar:105:ex5:words:6:zh":"there is / are","grammar:105:ex5:words:6:pos":"verb","grammar:105:ex5:points:0":"効率的に: efficiently (に makes it adverbial).","grammar:105:ex5:points:1":"〜方法があります: there is a way to …","exam:105:zh":"In order to write a name on the paper, I decided to use this pen.","exam:105:why":"Using a pen for writing calls for 「使う」. 「返す」 means to give something back, which doesn't achieve the purpose here of writing a name with the pen."},"106":{"example:106:exzh":"Please wait a moment.","example:106:exzh2":"I'm improving little by little.","example:106:exzh3":"It's a little cold, isn't it?","example:106:exzh4":"I'm a little hungry.","example:106:exzh5":"Let's walk just a little.","grammar:106:ex:trans":"Please wait a moment.","grammar:106:ex:structure":"少し〜てください","grammar:106:ex:explain":"This sentence makes a polite request with 「少し＋〜てください」. 「少し」 means \"a little\", close to 「ちょっと」; both soften the tone, but 「少し」 is slightly more written in style. The te-form of the verb 「待つ」 is 「待って」 (with a small っ), and adding 「ください」 makes a polite request. The whole sentence 「少し待ってください」 = \"Please wait a moment\". Adverbs like this come before the action and make a request sound gentler and less forceful.","grammar:106:ex:words:0:zh":"a little","grammar:106:ex:words:0:note":"すこし","grammar:106:ex:words:0:pos":"adverb","grammar:106:ex:words:1:zh":"wait","grammar:106:ex:words:1:note":"まって","grammar:106:ex:words:1:pos":"verb","grammar:106:ex:words:2:zh":"please","grammar:106:ex:words:2:pos":"auxiliary verb","grammar:106:ex:points:0":"少し: a little, slightly.","grammar:106:ex:points:1":"待つ→待って＋ください。","grammar:106:ex2:trans":"I'm improving little by little.","grammar:106:ex2:structure":"少しずつ〜ています","grammar:106:ex2:words:0:zh":"little by little","grammar:106:ex2:words:0:note":"すこしずつ","grammar:106:ex2:words:0:pos":"adverb","grammar:106:ex2:words:1:zh":"is improving","grammar:106:ex2:words:1:note":"じょうたつしています","grammar:106:ex2:words:1:pos":"verb","grammar:106:ex2:points:0":"少しずつ: little by little, gradually.","grammar:106:ex2:points:1":"上達する: to improve (at a skill).","grammar:106:ex3:trans":"It's a little cold, isn't it?","grammar:106:ex3:structure":"少し〜ですね","grammar:106:ex3:words:0:zh":"a little","grammar:106:ex3:words:0:note":"すこし","grammar:106:ex3:words:0:pos":"adverb","grammar:106:ex3:words:1:zh":"cold","grammar:106:ex3:words:1:note":"さむい","grammar:106:ex3:words:1:pos":"adjective","grammar:106:ex3:words:2:zh":"(polite form)","grammar:106:ex3:words:2:pos":"copula","grammar:106:ex3:words:3:zh":"right?","grammar:106:ex3:words:3:pos":"particle","grammar:106:ex3:points:0":"少し: a bit (degree).","grammar:106:ex3:points:1":"寒い: cold (i-adjective).","grammar:106:ex4:trans":"I'm a little hungry.","grammar:106:ex4:structure":"お腹が空きました","grammar:106:ex4:words:0:zh":"stomach","grammar:106:ex4:words:0:note":"おなか","grammar:106:ex4:words:0:pos":"noun","grammar:106:ex4:words:1:zh":"(nominative)","grammar:106:ex4:words:1:pos":"particle","grammar:106:ex4:words:2:zh":"a little","grammar:106:ex4:words:2:note":"すこし","grammar:106:ex4:words:2:pos":"adverb","grammar:106:ex4:words:3:zh":"became empty","grammar:106:ex4:words:3:note":"すきました","grammar:106:ex4:words:3:pos":"verb","grammar:106:ex4:points:0":"お腹が空く: to get hungry (an idiomatic phrase; the subject takes が).","grammar:106:ex4:points:1":"空く→空きました (past).","grammar:106:ex5:trans":"Let's walk a little.","grammar:106:ex5:structure":"少しだけ〜 (volitional form)","grammar:106:ex5:words:0:zh":"just a little bit","grammar:106:ex5:words:0:note":"すこし","grammar:106:ex5:words:0:pos":"adverb","grammar:106:ex5:words:1:zh":"only","grammar:106:ex5:words:1:pos":"particle","grammar:106:ex5:words:2:zh":"let's go","grammar:106:ex5:words:2:note":"あるこう","grammar:106:ex5:words:2:pos":"verb","grammar:106:ex5:points:0":"少しだけ: just a little (だけ limits it).","grammar:106:ex5:points:1":"歩く→歩こう (volitional form, \"let's walk\").","exam:106:zh":"Don't add too much sugar—just a little, about half a spoonful.","exam:106:why":"「少し」 means a small amount, which fits half a spoonful. 「たくさん」 means a lot, the opposite of not adding too much."},"107":{"example:107:exzh":"He could see the distant mountains.","example:107:exzh2":"This problem is simple, but hard to see clearly.","example:107:exzh3":"On clear days, the sea looks beautiful.","example:107:exzh4":"That plan was visible right away.","example:107:exzh5":"I could see a new building.","grammar:107:ex:trans":"He could see the mountains in the distance.","grammar:107:ex:structure":"noun + が + 見えた. 「見える」 means to be visible without trying, the object takes 「が」, and the ta-form marks the past.","grammar:107:ex:explain":"The key here is the spontaneous verb 「見える」. 「見える」 means to be (naturally) visible: not looking on purpose, but something coming into your field of view and being visible, which is different from the active 「見る」. What is visible takes 「が」, so 「山が見える」 = the mountain is visible. The verb 「見える」 is an ichidan (ru-) verb; its ta-form drops る and adds た to make 「見えた」, marking the past. The whole sentence says he could see the mountains in the distance, and the crucial point is that the object pairs with 「が」.","grammar:107:ex:words:0:zh":"he","grammar:107:ex:words:0:note":"かれ","grammar:107:ex:words:0:pos":"pronoun","grammar:107:ex:words:1:zh":"(topic marker)","grammar:107:ex:words:1:pos":"particle","grammar:107:ex:words:2:zh":"in the distance","grammar:107:ex:words:2:note":"とおく; the noun use of the adjective 遠い","grammar:107:ex:words:2:pos":"noun","grammar:107:ex:words:3:zh":"'s","grammar:107:ex:words:3:pos":"particle","grammar:107:ex:words:4:zh":"mountain","grammar:107:ex:words:4:note":"やま","grammar:107:ex:words:4:pos":"noun","grammar:107:ex:words:5:zh":"(nominative)","grammar:107:ex:words:5:note":"The object of 見える takes が","grammar:107:ex:words:5:pos":"particle","grammar:107:ex:words:6:zh":"was visible (past)","grammar:107:ex:words:6:note":"みえた; 見える = to come naturally into view; ta-form past","grammar:107:ex:words:6:pos":"verb","grammar:107:ex:points:0":"見える: to be naturally visible (not looking on purpose; contrast with 見る)","grammar:107:ex:points:1":"the object takes が: 山が見える","grammar:107:ex2:trans":"This problem is simple, but it's hard to see clearly.","grammar:107:ex2:structure":"〔な形容詞だ〕＋が、〜づらい. 「が」 works as a contrastive conjunction, although…, and 「〜づらい」 attaches to a verb to mean hard to ….","grammar:107:ex2:words:0:zh":"this","grammar:107:ex2:words:0:pos":"pre-noun adjectival","grammar:107:ex2:words:1:zh":"problem","grammar:107:ex2:words:1:note":"もんだい","grammar:107:ex2:words:1:pos":"noun","grammar:107:ex2:words:2:zh":"(topic marker)","grammar:107:ex2:words:2:pos":"particle","grammar:107:ex2:words:3:zh":"easy","grammar:107:ex2:words:3:note":"かんたん; だ is the plain copula","grammar:107:ex2:words:3:pos":"na-adjective","grammar:107:ex2:words:4:zh":"but","grammar:107:ex2:words:4:note":"contrast: although … but","grammar:107:ex2:words:4:pos":"particle","grammar:107:ex2:words:5:zh":"hard to see clearly","grammar:107:ex2:words:5:note":"みえづらい; 〜づらい means hard to …","grammar:107:ex2:words:5:pos":"adjective","grammar:107:ex2:points:0":"が: contrastive, although … but …","grammar:107:ex2:points:1":"verb masu-stem + づらい: hard to do … (見え＋づらい)","grammar:107:ex3:trans":"On a clear day the sea looks especially beautiful.","grammar:107:ex3:structure":"〔verb in the た-form〕＋noun＋は、nounが＋な-adjectiveに＋見える。「晴れた日」 uses a verb to modify a noun; 「綺麗に」 uses に to form an adverb modifying 見える.","grammar:107:ex3:words:0:zh":"sunny","grammar:107:ex3:words:0:note":"はれた; the ta-form used as a noun modifier","grammar:107:ex3:words:0:pos":"verb","grammar:107:ex3:words:1:zh":"day","grammar:107:ex3:words:1:note":"ひ","grammar:107:ex3:words:1:pos":"noun","grammar:107:ex3:words:2:zh":"(topic marker)","grammar:107:ex3:words:2:pos":"particle","grammar:107:ex3:words:3:zh":"the sea","grammar:107:ex3:words:3:note":"うみ","grammar:107:ex3:words:3:pos":"noun","grammar:107:ex3:words:4:zh":"(nominative)","grammar:107:ex3:words:4:pos":"particle","grammar:107:ex3:words:5:zh":"beautifully","grammar:107:ex3:words:5:note":"きれいに; a na-adjective becomes an adverb with に","grammar:107:ex3:words:5:pos":"na-adjective","grammar:107:ex3:words:6:zh":"can see (is visible)","grammar:107:ex3:words:6:note":"みえる","grammar:107:ex3:words:6:pos":"verb","grammar:107:ex3:points:0":"the verb ta-form can modify a noun directly: 晴れた日","grammar:107:ex3:points:1":"na-adjective + に = adverb: 綺麗に見える (looks beautiful)","grammar:107:ex4:trans":"That plan became clear right away.","grammar:107:ex4:structure":"noun は + すぐに + 見えた. The adverb 「すぐに」 modifies the verb, and 「見えた」 shows a result appearing naturally.","grammar:107:ex4:words:0:zh":"that","grammar:107:ex4:words:0:pos":"pre-noun adjectival","grammar:107:ex4:words:1:zh":"plans","grammar:107:ex4:words:1:note":"けいかく","grammar:107:ex4:words:1:pos":"noun","grammar:107:ex4:words:2:zh":"(topic marker)","grammar:107:ex4:words:2:pos":"particle","grammar:107:ex4:words:3:zh":"soon","grammar:107:ex4:words:3:note":"すぐに","grammar:107:ex4:words:3:pos":"adverb","grammar:107:ex4:words:4:zh":"was apparent (past)","grammar:107:ex4:words:4:note":"みえた","grammar:107:ex4:words:4:pos":"verb","grammar:107:ex4:points:0":"すぐに: right away, immediately","grammar:107:ex4:points:1":"見える extends to mean is apparent or is obvious","grammar:107:ex5:trans":"A new building came into view.","grammar:107:ex5:structure":"i-adjective + noun + が + 見えました. The object of 「見える」 takes が, and the masu-form past marks a polite past.","grammar:107:ex5:words:0:zh":"new","grammar:107:ex5:words:0:note":"あたらしい","grammar:107:ex5:words:0:pos":"adjective","grammar:107:ex5:words:1:zh":"building","grammar:107:ex5:words:1:note":"たてもの","grammar:107:ex5:words:1:pos":"noun","grammar:107:ex5:words:2:zh":"(nominative)","grammar:107:ex5:words:2:pos":"particle","grammar:107:ex5:words:3:zh":"was visible (past polite)","grammar:107:ex5:words:3:note":"みえました","grammar:107:ex5:words:3:pos":"verb","grammar:107:ex5:points:0":"見えました: the polite past of 見える","grammar:107:ex5:points:1":"the object takes が: 建物が見える"},"108":{"example:108:exzh":"I'll go through this lively street.","example:108:exzh2":"Please be careful when you go through this street.","example:108:exzh3":"I go through this street every day.","example:108:exzh4":"When you go through this street, you can see a few shops.","example:108:exzh5":"Many people were going through this street.","grammar:108:ex:trans":"I'll go through this busy street.","grammar:108:ex:structure":"〜な通りを通ります","grammar:108:ex:explain":"「賑やか」 is a na-adjective and takes 「な」 when it modifies 「通り」. 「この賑やかな通りを」 marks the route being passed through; here 「を」 is not the usual object marker. 「通ります」 is the polite form of 「通る」 and in this sentence can mean passing through from now on.","grammar:108:ex:words:0:zh":"this","grammar:108:ex:words:0:pos":"pre-noun adjectival","grammar:108:ex:words:1:zh":"busy, lively","grammar:108:ex:words:1:note":"にぎやか","grammar:108:ex:words:1:pos":"na-adjective","grammar:108:ex:words:2:zh":"(links a na-adjective to a noun)","grammar:108:ex:words:2:pos":"auxiliary verb","grammar:108:ex:words:3:zh":"street","grammar:108:ex:words:3:note":"とおり","grammar:108:ex:words:3:pos":"noun","grammar:108:ex:words:4:zh":"(the route passed through)","grammar:108:ex:words:4:pos":"particle","grammar:108:ex:words:5:zh":"to pass through, to go through","grammar:108:ex:words:5:note":"とおり","grammar:108:ex:words:5:pos":"verb","grammar:108:ex:words:6:zh":"(polite tone)","grammar:108:ex:words:6:pos":"auxiliary verb","grammar:108:ex:points:0":"「通る」 is an intransitive verb, but the route you pass through can be marked with 「を」.","grammar:108:ex:points:1":"The first 「通り」 is the noun meaning \"street\", while the second 「通り」 is the continuative form of the verb 「通る」.","grammar:108:ex2:trans":"Please be careful when you go through this street.","grammar:108:ex2:structure":"dictionary form of a verb＋時は、〜てください","grammar:108:ex2:explain":"The whole 「この通りを通る」 modifies 「時」, forming \"when you go through this street\". 「は」 raises this time setting as the topic, explaining what you should do in that situation. 「注意してください」 combines the te-form of 「注意する」 with 「ください」, meaning \"please be careful\".","grammar:108:ex2:words:0:zh":"this","grammar:108:ex2:words:0:pos":"pre-noun adjectival","grammar:108:ex2:words:1:zh":"street","grammar:108:ex2:words:1:note":"とおり","grammar:108:ex2:words:1:pos":"noun","grammar:108:ex2:words:2:zh":"(the route passed through)","grammar:108:ex2:words:2:pos":"particle","grammar:108:ex2:words:3:zh":"pass (of time)","grammar:108:ex2:words:3:note":"とおる","grammar:108:ex2:words:3:pos":"verb","grammar:108:ex2:words:4:zh":"time","grammar:108:ex2:words:4:note":"とき","grammar:108:ex2:words:4:pos":"noun","grammar:108:ex2:words:5:zh":"(raises the time setting as the topic)","grammar:108:ex2:words:5:pos":"particle","grammar:108:ex2:words:6:zh":"to be careful, to watch out","grammar:108:ex2:words:6:note":"ちゅういし","grammar:108:ex2:words:6:pos":"verb","grammar:108:ex2:words:7:zh":"(connects to a request expression)","grammar:108:ex2:words:7:pos":"particle","grammar:108:ex2:words:8:zh":"please","grammar:108:ex2:words:8:pos":"verb","grammar:108:ex2:points:0":"「通る時」 expresses the situation at the time of passing through; the verb modifies 「時」 directly.","grammar:108:ex2:points:1":"「〜てください」 is used to ask someone to do something.","grammar:108:ex3:trans":"I go through this street every day.","grammar:108:ex3:structure":"〜を通ります","grammar:108:ex3:words:0:zh":"I","grammar:108:ex3:words:0:note":"わたし","grammar:108:ex3:words:0:pos":"pronoun","grammar:108:ex3:words:1:zh":"(topic)","grammar:108:ex3:words:1:pos":"particle","grammar:108:ex3:words:2:zh":"every day","grammar:108:ex3:words:2:note":"まいにち","grammar:108:ex3:words:2:pos":"adverb","grammar:108:ex3:words:3:zh":"this","grammar:108:ex3:words:3:pos":"pre-noun adjectival","grammar:108:ex3:words:4:zh":"street","grammar:108:ex3:words:4:note":"とおり","grammar:108:ex3:words:4:pos":"noun","grammar:108:ex3:words:5:zh":"(the path taken)","grammar:108:ex3:words:5:pos":"particle","grammar:108:ex3:words:6:zh":"pass (of time)","grammar:108:ex3:words:6:note":"とおります","grammar:108:ex3:words:6:pos":"verb","grammar:108:ex3:points:0":"を＋通る: to pass through (を marks the path of movement).","grammar:108:ex3:points:1":"通る→通ります.","grammar:108:ex4:trans":"When you go through this street, you can see a few shops.","grammar:108:ex4:structure":"〜を通ると、〜がいくつか見えます","grammar:108:ex4:explain":"「この通りを通ると」 means that as soon as you go through this street, the scene that follows comes into view. 「店が見えます」 marks the things that can be seen with 「が」; 「見える」 itself means \"to be visible\" and is not the potential form of 「見る」. 「いくつか」 adds the number of shops, meaning \"a few\".","grammar:108:ex4:words:0:zh":"this","grammar:108:ex4:words:0:pos":"pre-noun adjectival","grammar:108:ex4:words:1:zh":"street","grammar:108:ex4:words:1:note":"とおり","grammar:108:ex4:words:1:pos":"noun","grammar:108:ex4:words:2:zh":"(the route passed through)","grammar:108:ex4:words:2:pos":"particle","grammar:108:ex4:words:3:zh":"pass (of time)","grammar:108:ex4:words:3:note":"とおる","grammar:108:ex4:words:3:pos":"verb","grammar:108:ex4:words:4:zh":"(the \"once … then …\" condition)","grammar:108:ex4:words:4:pos":"particle","grammar:108:ex4:words:5:zh":"shop","grammar:108:ex4:words:5:note":"みせ","grammar:108:ex4:words:5:pos":"noun","grammar:108:ex4:words:6:zh":"(the thing that comes into view)","grammar:108:ex4:words:6:pos":"particle","grammar:108:ex4:words:7:zh":"a few","grammar:108:ex4:words:7:pos":"numeral","grammar:108:ex4:words:8:zh":"(indicates an unspecified number)","grammar:108:ex4:words:8:pos":"particle","grammar:108:ex4:words:9:zh":"to be visible","grammar:108:ex4:words:9:note":"みえ","grammar:108:ex4:words:9:pos":"verb","grammar:108:ex4:words:10:zh":"(polite tone)","grammar:108:ex4:words:10:pos":"auxiliary verb","grammar:108:ex4:points:0":"Here 「〜と」 means that once the first condition is met, the following scene appears.","grammar:108:ex4:points:1":"「見える」 means that something comes into view or is in a visible state, and the visible thing is marked with 「が」.","grammar:108:ex4:points:2":"「いくつか」 means \"a few, some\" and does not specify an exact number.","grammar:108:ex5:trans":"Many people were walking along this street at that time.","grammar:108:ex5:structure":"多くの〜が〜を通っていました","grammar:108:ex5:explain":"In 「多くの人」, 「多く」 works as a noun and is joined to 「人」 with 「の」, meaning \"many people\". 「人が」 marks who is passing through, and 「通りを」 marks the route. 「通っていました」 is the polite past form of 「通っている」, describing the scene of people passing through at that time.","grammar:108:ex5:words:0:zh":"many","grammar:108:ex5:words:0:note":"おおく","grammar:108:ex5:words:0:pos":"noun","grammar:108:ex5:words:1:zh":"(connects a modifier and a noun)","grammar:108:ex5:words:1:pos":"particle","grammar:108:ex5:words:2:zh":"person","grammar:108:ex5:words:2:note":"ひと","grammar:108:ex5:words:2:pos":"noun","grammar:108:ex5:words:3:zh":"(nominative)","grammar:108:ex5:words:3:pos":"particle","grammar:108:ex5:words:4:zh":"this","grammar:108:ex5:words:4:pos":"pre-noun adjectival","grammar:108:ex5:words:5:zh":"street","grammar:108:ex5:words:5:note":"とおり","grammar:108:ex5:words:5:pos":"noun","grammar:108:ex5:words:6:zh":"(the route passed through)","grammar:108:ex5:words:6:pos":"particle","grammar:108:ex5:words:7:zh":"pass (of time)","grammar:108:ex5:words:7:note":"とおっ","grammar:108:ex5:words:7:pos":"verb","grammar:108:ex5:words:8:zh":"(links to the progressive expression that follows)","grammar:108:ex5:words:8:pos":"particle","grammar:108:ex5:words:9:zh":"(the action is in progress)","grammar:108:ex5:words:9:pos":"verb","grammar:108:ex5:words:10:zh":"(polite tone)","grammar:108:ex5:words:10:pos":"auxiliary verb","grammar:108:ex5:words:11:zh":"(past)","grammar:108:ex5:words:11:pos":"auxiliary verb","grammar:108:ex5:points:0":"「多くの＋名詞」 expresses many of a certain person or thing, and is the correct form, unlike 「多いの人」.","grammar:108:ex5:points:1":"「〜ていました」 can describe an action that was in progress at a certain point in the past."},"109":{"example:109:exzh":"He taught me English.","example:109:exzh2":"The teacher is teaching us math.","example:109:exzh3":"It's important to be taught by a teacher.","example:109:exzh4":"She teaches students gently.","example:109:exzh5":"Teaching knowledge is a pleasure.","grammar:109:ex:trans":"He taught me English.","grammar:109:ex:structure":"〜に〜を教えてくれた","grammar:109:ex:explain":"This sentence uses the giving-and-receiving verb 「〜てくれる」 to express a benefit received. The te-form of 「教える」, 「教えて」, attaches to the past form 「くれた」 of 「くれる」, showing that the other person did something for 'me' of their own accord, with a sense of receiving a favor. The 「に」 in 「私に」 marks the person receiving the action (me), and 「英語を」 marks what was taught. The whole sentence 「彼は私に英語を教えてくれた」 = 'he taught me English' and implies 'and I'm grateful' — this 「〜てくれる」 is the core of benefit expressions.","grammar:109:ex:words:0:zh":"he","grammar:109:ex:words:0:note":"かれ","grammar:109:ex:words:0:pos":"pronoun","grammar:109:ex:words:1:zh":"(topic)","grammar:109:ex:words:1:pos":"particle","grammar:109:ex:words:2:zh":"I","grammar:109:ex:words:2:note":"わたし","grammar:109:ex:words:2:pos":"pronoun","grammar:109:ex:words:3:zh":"(object)","grammar:109:ex:words:3:pos":"particle","grammar:109:ex:words:4:zh":"English","grammar:109:ex:words:4:note":"えいご","grammar:109:ex:words:4:pos":"noun","grammar:109:ex:words:5:zh":"(object marker)","grammar:109:ex:words:5:pos":"particle","grammar:109:ex:words:6:zh":"teach","grammar:109:ex:words:6:note":"おしえて","grammar:109:ex:words:6:pos":"verb","grammar:109:ex:words:7:zh":"did (for me)","grammar:109:ex:words:7:pos":"auxiliary verb","grammar:109:ex:points:0":"❗〜に〜を教えてくれた: (someone) taught me ... (〜てくれる = a favor).","grammar:109:ex:points:1":"私に教える: to teach me.","grammar:109:ex2:trans":"The teacher is teaching us math.","grammar:109:ex2:structure":"〜に〜を教えています","grammar:109:ex2:words:0:zh":"teacher","grammar:109:ex2:words:0:note":"せんせい","grammar:109:ex2:words:0:pos":"noun","grammar:109:ex2:words:1:zh":"(nominative)","grammar:109:ex2:words:1:pos":"particle","grammar:109:ex2:words:2:zh":"we","grammar:109:ex2:words:2:note":"わたしたち","grammar:109:ex2:words:2:pos":"pronoun","grammar:109:ex2:words:3:zh":"(object)","grammar:109:ex2:words:3:pos":"particle","grammar:109:ex2:words:4:zh":"math","grammar:109:ex2:words:4:note":"すうがく","grammar:109:ex2:words:4:pos":"noun","grammar:109:ex2:words:5:zh":"(object marker)","grammar:109:ex2:words:5:pos":"particle","grammar:109:ex2:words:6:zh":"is teaching","grammar:109:ex2:words:6:note":"おしえています","grammar:109:ex2:words:6:pos":"verb","grammar:109:ex2:points:0":"❗〜に〜を教える: to teach ... (person) ... (the person is marked with に).","grammar:109:ex2:points:1":"数学を教える: to teach math.","grammar:109:ex3:trans":"Being taught by a teacher is important.","grammar:109:ex3:structure":"〜に〜てもらうことは大事です","grammar:109:ex3:explain":"「先生に教えてもらう」 is phrased from the perspective of the person receiving the teaching and means getting taught by a teacher. 「に」 marks the person providing the help, and 「教えて」 is the te-form of 「教える」. The following 「こと」 turns the whole phrase into 'the act of being taught by a teacher', which 「は」 then presents as the topic. 「大事です」 says that this is important.","grammar:109:ex3:words:0:zh":"teacher","grammar:109:ex3:words:0:note":"せんせい","grammar:109:ex3:words:0:pos":"noun","grammar:109:ex3:words:1:zh":"(the person providing the help)","grammar:109:ex3:words:1:pos":"particle","grammar:109:ex3:words:2:zh":"teachings","grammar:109:ex3:words:2:note":"おしえ","grammar:109:ex3:words:2:pos":"verb","grammar:109:ex3:words:3:zh":"(links to the verb that follows)","grammar:109:ex3:words:3:pos":"particle","grammar:109:ex3:words:4:zh":"to receive someone's help","grammar:109:ex3:words:4:pos":"verb","grammar:109:ex3:words:5:zh":"(nominalizes the preceding action)","grammar:109:ex3:words:5:pos":"noun","grammar:109:ex3:words:6:zh":"(topic)","grammar:109:ex3:words:6:pos":"particle","grammar:109:ex3:words:7:zh":"important","grammar:109:ex3:words:7:note":"だいじ","grammar:109:ex3:words:7:pos":"na-adjective","grammar:109:ex3:words:8:zh":"(polite statement)","grammar:109:ex3:words:8:pos":"auxiliary verb","grammar:109:ex3:points:0":"「人に〜てもらう」 means to have someone do something for you.","grammar:109:ex3:points:1":"「こと」 nominalizes the preceding action so the whole phrase can serve as the topic.","grammar:109:ex4:trans":"She teaches students gently.","grammar:109:ex4:structure":"〜は人に優しく教えます","grammar:109:ex4:explain":"「彼女は」 presents her as the topic, and 「学生に」 marks the people she teaches. 「優しい」 is an i-adjective; it becomes 「優しく」 and then modifies 「教えます」, describing the gentle way she teaches. 「教える」 is a transitive verb, and what is taught usually takes 「を」, but this sentence doesn't say what she teaches.","grammar:109:ex4:words:0:zh":"she","grammar:109:ex4:words:0:note":"かのじょ","grammar:109:ex4:words:0:pos":"pronoun","grammar:109:ex4:words:1:zh":"(topic)","grammar:109:ex4:words:1:pos":"particle","grammar:109:ex4:words:2:zh":"student","grammar:109:ex4:words:2:note":"がくせい","grammar:109:ex4:words:2:pos":"noun","grammar:109:ex4:words:3:zh":"(the people being taught)","grammar:109:ex4:words:3:pos":"particle","grammar:109:ex4:words:4:zh":"gently","grammar:109:ex4:words:4:note":"やさしく","grammar:109:ex4:words:4:pos":"i-adjective","grammar:109:ex4:words:5:zh":"teachings","grammar:109:ex4:words:5:note":"おしえ","grammar:109:ex4:words:5:pos":"verb","grammar:109:ex4:words:6:zh":"(polite tone)","grammar:109:ex4:words:6:pos":"auxiliary verb","grammar:109:ex4:points:0":"Turning the final 「い」 of an i-adjective into 「く」 lets it modify a verb.","grammar:109:ex4:points:1":"In 「人に教える」, 「に」 marks the person receiving the teaching.","grammar:109:ex5:trans":"Teaching knowledge is a pleasure.","grammar:109:ex5:structure":"〜のは楽しみだ","grammar:109:ex5:words:0:zh":"knowledge","grammar:109:ex5:words:0:note":"ちしき","grammar:109:ex5:words:0:pos":"noun","grammar:109:ex5:words:1:zh":"(object marker)","grammar:109:ex5:words:1:pos":"particle","grammar:109:ex5:words:2:zh":"teach","grammar:109:ex5:words:2:note":"おしえる","grammar:109:ex5:words:2:pos":"verb","grammar:109:ex5:words:3:zh":"(nominalizer)","grammar:109:ex5:words:3:pos":"particle","grammar:109:ex5:words:4:zh":"(topic)","grammar:109:ex5:words:4:pos":"particle","grammar:109:ex5:words:5:zh":"enjoyment","grammar:109:ex5:words:5:note":"たのしみ","grammar:109:ex5:words:5:pos":"noun","grammar:109:ex5:words:6:zh":"is","grammar:109:ex5:words:6:pos":"copula","grammar:109:ex5:points:0":"知識を教える: to teach knowledge.","grammar:109:ex5:points:1":"〜のは楽しみだ: doing ... is a pleasure.","exam:109:zh":"My little brother still can't read a clock, so I decided to teach him how to read one.","exam:109:why":"Handing down a way of reading something to someone who can't do it is 「教える」. 「習う」 means learning from someone else — the opposite direction from me teaching my little brother here."},"110":{"example:110:exzh":"I want to go on a trip with everyone.","example:110:exzh2":"Everyone looks happy.","example:110:exzh3":"I want to hear everyone's opinions.","example:110:exzh4":"Everyone, please join in together.","example:110:exzh5":"Everyone knows this song.","grammar:110:ex:trans":"I want to go on a trip with everyone.","grammar:110:ex:structure":"皆で〜に行きたい","grammar:110:ex:explain":"This sentence uses 「皆で」 to mean everyone together and carries a wish. The 「で」 in 「皆で」 here shows that the action is done by everyone together; 「皆で」 means everyone together. 「〜に」 marks the purpose of the movement (going on a trip). The verb 「行く」 plus the desiderative auxiliary 「たい」 becomes 「行きたい」, meaning want to go. The whole sentence 「皆で旅行に行きたい」 means I want to go on a trip with everyone. The 「で」 here marks the group as a whole, which is a different use from the 「で」 that marks a tool or a place.","grammar:110:ex:words:0:zh":"everyone","grammar:110:ex:words:0:note":"みんな","grammar:110:ex:words:0:pos":"pronoun","grammar:110:ex:words:1:zh":"(the whole group)","grammar:110:ex:words:1:pos":"particle","grammar:110:ex:words:2:zh":"travel / trip","grammar:110:ex:words:2:note":"りょこう","grammar:110:ex:words:2:pos":"noun","grammar:110:ex:words:3:zh":"(purpose)","grammar:110:ex:words:3:pos":"particle","grammar:110:ex:words:4:zh":"want to go","grammar:110:ex:words:4:note":"いきたい","grammar:110:ex:words:4:pos":"verb","grammar:110:ex:points:0":"皆で: everyone together (で marks the whole group).","grammar:110:ex:points:1":"行く→行きたい。","grammar:110:ex2:trans":"Everyone looks happy.","grammar:110:ex2:structure":"〜そうに見えます","grammar:110:ex2:words:0:zh":"everyone","grammar:110:ex2:words:0:note":"みんな","grammar:110:ex2:words:0:pos":"pronoun","grammar:110:ex2:words:1:zh":"(topic)","grammar:110:ex2:words:1:pos":"particle","grammar:110:ex2:words:2:zh":"happy","grammar:110:ex2:words:2:note":"しあわせ","grammar:110:ex2:words:2:pos":"na-adjective","grammar:110:ex2:words:3:zh":"looks (like)","grammar:110:ex2:words:3:pos":"auxiliary verb","grammar:110:ex2:words:4:zh":"(made adverbial)","grammar:110:ex2:words:4:pos":"particle","grammar:110:ex2:words:5:zh":"looks (like)","grammar:110:ex2:words:5:note":"みえます","grammar:110:ex2:words:5:pos":"verb","grammar:110:ex2:points:0":"〜そう: looks … (appearance; a na-adjective drops its ending and takes そう).","grammar:110:ex2:points:1":"見える: to be visible / to appear.","grammar:110:ex3:trans":"I want to hear everyone's opinions.","grammar:110:ex3:structure":"皆の〜を聞きたい","grammar:110:ex3:words:0:zh":"everyone","grammar:110:ex3:words:0:note":"みんな","grammar:110:ex3:words:0:pos":"pronoun","grammar:110:ex3:words:1:zh":"'s","grammar:110:ex3:words:1:pos":"particle","grammar:110:ex3:words:2:zh":"opinion","grammar:110:ex3:words:2:note":"いけん","grammar:110:ex3:words:2:pos":"noun","grammar:110:ex3:words:3:zh":"(object marker)","grammar:110:ex3:words:3:pos":"particle","grammar:110:ex3:words:4:zh":"want to hear","grammar:110:ex3:words:4:note":"ききたい","grammar:110:ex3:words:4:pos":"verb","grammar:110:ex3:points:0":"皆の意見: everyone's opinions.","grammar:110:ex3:points:1":"聞く→聞きたい。","grammar:110:ex4:trans":"Everyone, please join in together.","grammar:110:ex4:structure":"一緒に参加してください","grammar:110:ex4:words:0:zh":"everyone","grammar:110:ex4:words:0:note":"みんな","grammar:110:ex4:words:0:pos":"pronoun","grammar:110:ex4:words:1:zh":"together","grammar:110:ex4:words:1:note":"いっしょに","grammar:110:ex4:words:1:pos":"adverb","grammar:110:ex4:words:2:zh":"join","grammar:110:ex4:words:2:note":"さんかして","grammar:110:ex4:words:2:pos":"verb","grammar:110:ex4:words:3:zh":"please","grammar:110:ex4:words:3:pos":"auxiliary verb","grammar:110:ex4:points:0":"参加する→参加して＋ください。","grammar:110:ex4:points:1":"皆: calling out to everyone (= みなさん).","grammar:110:ex5:trans":"Everyone knows this song.","grammar:110:ex5:structure":"この＋noun＋は＋みんな＋が＋知っています","grammar:110:ex5:words:0:zh":"this","grammar:110:ex5:words:0:pos":"pre-noun adjectival","grammar:110:ex5:words:1:zh":"song","grammar:110:ex5:words:1:note":"うた","grammar:110:ex5:words:1:pos":"noun","grammar:110:ex5:words:2:zh":"(topic)","grammar:110:ex5:words:2:pos":"particle","grammar:110:ex5:words:3:zh":"everyone","grammar:110:ex5:words:3:pos":"pronoun","grammar:110:ex5:words:4:zh":"(nominative)","grammar:110:ex5:words:4:pos":"particle","grammar:110:ex5:words:5:zh":"know","grammar:110:ex5:words:5:note":"しって; the te-form of 知る","grammar:110:ex5:words:5:pos":"verb","grammar:110:ex5:words:6:zh":"(a state)","grammar:110:ex5:words:6:note":"ている expresses a state","grammar:110:ex5:words:6:pos":"auxiliary verb","grammar:110:ex5:points:0":"「みんなが知っています」: みんな is the subject, and が expresses that everyone knows.","grammar:110:ex5:points:1":"知っています: 知る takes the 「ている」 form to express the state of knowing; 「知ります」 is not used.","grammar:110:ex5:points:2":"は introduces the topic 「この歌」.","exam:110:zh":"All twenty people in the class came, and not a single one was absent.","exam:110:why":"「みんな」 means everyone, which matches 「一人も休まずに」. 「誰か」 only means someone, so it can't express that the whole class showed up."},"111":{"example:111:exzh":"This is for you.","example:111:exzh2":"He's making an effort for success.","example:111:exzh3":"I exercise for health.","example:111:exzh4":"This meal is for my diet.","example:111:exzh5":"Studying is good for the future.","grammar:111:ex:trans":"This is for you.","grammar:111:ex:structure":"〜のためです","grammar:111:ex:explain":"This sentence uses 「〜のため」 to express a purpose or a beneficiary. 「ため」 is a noun, and 「〜のため」 means for the sake of … (someone's benefit or a purpose); 「あなたのため」 means for you. 「これは⋯です」 is the frame of a noun-predicate sentence, with 「は」 presenting the topic. The whole sentence 「これはあなたのためです」 means this is for your sake. Note that 「ため」 can also express a cause (〜たため), but when it follows a noun plus の it usually means for the sake of; judge from the surrounding context.","grammar:111:ex:words:0:zh":"this","grammar:111:ex:words:0:pos":"pronoun","grammar:111:ex:words:1:zh":"(topic)","grammar:111:ex:words:1:pos":"particle","grammar:111:ex:words:2:zh":"you","grammar:111:ex:words:2:pos":"pronoun","grammar:111:ex:words:3:zh":"'s","grammar:111:ex:words:3:pos":"particle","grammar:111:ex:words:4:zh":"for the sake of","grammar:111:ex:words:4:pos":"noun","grammar:111:ex:words:5:zh":"is","grammar:111:ex:words:5:pos":"copula","grammar:111:ex:points:0":"〜のため: for the sake of … (benefit / purpose).","grammar:111:ex:points:1":"あなたのため: for your sake.","grammar:111:ex2:trans":"He works hard for success.","grammar:111:ex2:structure":"noun＋のために、〜ている","grammar:111:ex2:explain":"「成功のために」 states the purpose of the effort; when a noun attaches to 「ため」, 「の」 is inserted between them. The te-form of 「努力する」 is 「努力して」, and with 「いる」 it shows that the effort is ongoing. 「ため」 can also express a cause, but in this sentence, judging from the context, it expresses a purpose.","grammar:111:ex2:words:0:zh":"he","grammar:111:ex2:words:0:note":"かれ","grammar:111:ex2:words:0:pos":"pronoun","grammar:111:ex2:words:1:zh":"(topic)","grammar:111:ex2:words:1:pos":"particle","grammar:111:ex2:words:2:zh":"success","grammar:111:ex2:words:2:note":"せいこう","grammar:111:ex2:words:2:pos":"noun","grammar:111:ex2:words:3:zh":"(links a noun to 「ため」)","grammar:111:ex2:words:3:pos":"particle","grammar:111:ex2:words:4:zh":"purpose","grammar:111:ex2:words:4:pos":"noun","grammar:111:ex2:words:5:zh":"(marks a purpose)","grammar:111:ex2:words:5:pos":"particle","grammar:111:ex2:words:6:zh":"effort","grammar:111:ex2:words:6:note":"どりょくし","grammar:111:ex2:words:6:pos":"verb","grammar:111:ex2:words:7:zh":"(links to the progressive expression that follows)","grammar:111:ex2:words:7:pos":"particle","grammar:111:ex2:words:8:zh":"(ongoing)","grammar:111:ex2:words:8:pos":"verb","grammar:111:ex2:points:0":"「名詞＋のために」 can express a purpose; here it means for success.","grammar:111:ex2:points:1":"「努力している」 means someone is working hard or keeping up the effort.","grammar:111:ex3:trans":"I exercise for my health.","grammar:111:ex3:structure":"〜のために〜します","grammar:111:ex3:words:0:zh":"health","grammar:111:ex3:words:0:note":"けんこう","grammar:111:ex3:words:0:pos":"noun","grammar:111:ex3:words:1:zh":"'s","grammar:111:ex3:words:1:pos":"particle","grammar:111:ex3:words:2:zh":"for the sake of","grammar:111:ex3:words:2:pos":"particle","grammar:111:ex3:words:3:zh":"exercise","grammar:111:ex3:words:3:note":"うんどうします","grammar:111:ex3:words:3:pos":"verb","grammar:111:ex3:points:0":"〜のために: for the sake of … (purpose).","grammar:111:ex3:points:1":"健康のために: for the sake of health.","grammar:111:ex4:trans":"This meal is for the sake of dieting.","grammar:111:ex4:structure":"〜のためです","grammar:111:ex4:words:0:zh":"this","grammar:111:ex4:words:0:pos":"pre-noun adjectival","grammar:111:ex4:words:1:zh":"meal","grammar:111:ex4:words:1:note":"しょくじ","grammar:111:ex4:words:1:pos":"noun","grammar:111:ex4:words:2:zh":"(topic)","grammar:111:ex4:words:2:pos":"particle","grammar:111:ex4:words:3:zh":"dieting","grammar:111:ex4:words:3:note":"loanword","grammar:111:ex4:words:3:pos":"noun","grammar:111:ex4:words:4:zh":"'s","grammar:111:ex4:words:4:pos":"particle","grammar:111:ex4:words:5:zh":"for the sake of","grammar:111:ex4:words:5:pos":"noun","grammar:111:ex4:words:6:zh":"is","grammar:111:ex4:words:6:pos":"copula","grammar:111:ex4:points:0":"ダイエットのため: for the sake of dieting.","grammar:111:ex4:points:1":"ため: purpose.","grammar:111:ex5:trans":"Studying is good for the future.","grammar:111:ex5:structure":"〜のためになる","grammar:111:ex5:words:0:zh":"study","grammar:111:ex5:words:0:note":"べんきょう","grammar:111:ex5:words:0:pos":"noun","grammar:111:ex5:words:1:zh":"(topic)","grammar:111:ex5:words:1:pos":"particle","grammar:111:ex5:words:2:zh":"the future","grammar:111:ex5:words:2:note":"しょうらい","grammar:111:ex5:words:2:pos":"noun","grammar:111:ex5:words:3:zh":"'s","grammar:111:ex5:words:3:pos":"particle","grammar:111:ex5:words:4:zh":"benefit","grammar:111:ex5:words:4:pos":"noun","grammar:111:ex5:words:5:zh":"(result)","grammar:111:ex5:words:5:pos":"particle","grammar:111:ex5:words:6:zh":"become","grammar:111:ex5:words:6:pos":"verb","grammar:111:ex5:points:0":"〜のためになる: to be good for … / to be helpful (a set expression).","grammar:111:ex5:points:1":"将来: the future."},"112":{"example:112:exzh":"I put the book in the box.","example:112:exzh2":"Please pour the coffee into the cup.","example:112:exzh3":"I put the money in the wallet.","example:112:exzh4":"To put the camera in a bag and take it along.","example:112:exzh5":"Please don't put forgotten items in there.","grammar:112:ex:trans":"I put the book in the box.","grammar:112:ex:structure":"〜に〜を入れました","grammar:112:ex:explain":"The key point here is the transitive verb 「入れる」 used with 「に」. 「入れる」 means to put in, to place inside; it is a transitive verb, the place where something is put is marked with 「に」 (「箱に入れる」 = put it in the box), and the thing put in takes 「を」 (本を). Its intransitive counterpart is 「入る」 (to go in), whose subject takes 「が」; learn the pair together. The verb 「入れる」 is an ichidan (ru-) verb, and its past polite form is 「入れました」. The whole sentence means I put the book in the box.","grammar:112:ex:words:0:zh":"box","grammar:112:ex:words:0:note":"はこ","grammar:112:ex:words:0:pos":"noun","grammar:112:ex:words:1:zh":"(the destination point)","grammar:112:ex:words:1:pos":"particle","grammar:112:ex:words:2:zh":"book","grammar:112:ex:words:2:note":"ほん","grammar:112:ex:words:2:pos":"noun","grammar:112:ex:words:3:zh":"(object marker)","grammar:112:ex:words:3:pos":"particle","grammar:112:ex:words:4:zh":"put in","grammar:112:ex:words:4:note":"いれました","grammar:112:ex:words:4:pos":"verb","grammar:112:ex:points:0":"❓入れる takes に to mark the place where something is put in: 箱に入れる.","grammar:112:ex:points:1":"入れる: to put in (transitive verb), as opposed to the intransitive verb 入る.","grammar:112:ex2:trans":"Please pour the coffee into the cup.","grammar:112:ex2:structure":"〜を〜に入れてください","grammar:112:ex2:words:0:zh":"coffee","grammar:112:ex2:words:0:note":"loanword","grammar:112:ex2:words:0:pos":"noun","grammar:112:ex2:words:1:zh":"(object marker)","grammar:112:ex2:words:1:pos":"particle","grammar:112:ex2:words:2:zh":"cup","grammar:112:ex2:words:2:note":"loanword","grammar:112:ex2:words:2:pos":"noun","grammar:112:ex2:words:3:zh":"(the destination point)","grammar:112:ex2:words:3:pos":"particle","grammar:112:ex2:words:4:zh":"put in","grammar:112:ex2:words:4:note":"いれて","grammar:112:ex2:words:4:pos":"verb","grammar:112:ex2:words:5:zh":"please","grammar:112:ex2:words:5:pos":"auxiliary verb","grammar:112:ex2:points:0":"を marks the thing put in, and に marks the container it goes into.","grammar:112:ex2:points:1":"入れる→入れて＋ください。","grammar:112:ex3:trans":"I put the money in a wallet.","grammar:112:ex3:structure":"〜に〜を入れました","grammar:112:ex3:words:0:zh":"wallet","grammar:112:ex3:words:0:note":"さいふ","grammar:112:ex3:words:0:pos":"noun","grammar:112:ex3:words:1:zh":"(the destination point)","grammar:112:ex3:words:1:pos":"particle","grammar:112:ex3:words:2:zh":"money","grammar:112:ex3:words:2:note":"おかね","grammar:112:ex3:words:2:pos":"noun","grammar:112:ex3:words:3:zh":"(object marker)","grammar:112:ex3:words:3:pos":"particle","grammar:112:ex3:words:4:zh":"put in","grammar:112:ex3:words:4:note":"いれました","grammar:112:ex3:words:4:pos":"verb","grammar:112:ex3:points:0":"財布に入れる: to put into a wallet.","grammar:112:ex3:points:1":"を＋に＋入れる: put X into Y.","grammar:112:ex4:trans":"Put the camera in the bag and take it along.","grammar:112:ex4:structure":"〜に入れて持って行く","grammar:112:ex4:words:0:zh":"camera","grammar:112:ex4:words:0:note":"loanword","grammar:112:ex4:words:0:pos":"noun","grammar:112:ex4:words:1:zh":"(object marker)","grammar:112:ex4:words:1:pos":"particle","grammar:112:ex4:words:2:zh":"bag","grammar:112:ex4:words:2:note":"ふくろ","grammar:112:ex4:words:2:pos":"noun","grammar:112:ex4:words:3:zh":"(the destination point)","grammar:112:ex4:words:3:pos":"particle","grammar:112:ex4:words:4:zh":"put in","grammar:112:ex4:words:4:note":"いれて","grammar:112:ex4:words:4:pos":"verb","grammar:112:ex4:words:5:zh":"take along","grammar:112:ex4:words:5:note":"もっていく","grammar:112:ex4:words:5:pos":"verb","grammar:112:ex4:points:0":"入れて: the te-form links to the next action.","grammar:112:ex4:points:1":"持って行く: to take (along / away).","grammar:112:ex5:trans":"Please do not put forgotten belongings in.","grammar:112:ex5:structure":"〜ないように","grammar:112:ex5:words:0:zh":"lost property","grammar:112:ex5:words:0:note":"わすれもの","grammar:112:ex5:words:0:pos":"noun","grammar:112:ex5:words:1:zh":"(object marker)","grammar:112:ex5:words:1:pos":"particle","grammar:112:ex5:words:2:zh":"Do not put (them) in","grammar:112:ex5:words:2:note":"いれないように","grammar:112:ex5:words:2:pos":"verb","grammar:112:ex5:points:0":"〜ないように: so as not to … / do not … (purpose / a reminder).","grammar:112:ex5:points:1":"入れる→入れない＋ように。","exam:112:zh":"The bag is empty, so next I'm going to put my textbooks in it.","exam:112:why":"Putting something into a container is 「物をかばんに入れる」. 「出す」 means to take out and usually goes with 「かばんから」, the opposite direction."},"113":{"example:113:exzh":"She often reads books.","example:113:exzh2":"I have a friend I often go out and have fun with.","example:113:exzh3":"Getting enough sleep is important.","example:113:exzh4":"I don't really know about it, but I'll go check it out.","example:113:exzh5":"Let's decide after thinking it over carefully.","grammar:113:ex:trans":"She often reads books.","grammar:113:ex:structure":"よく〜ます","grammar:113:ex:explain":"This sentence practices the multi-meaning adverb 「よく」. 「よく」 has two common meanings: one is properly, carefully, and the other is often, frequently; here it expresses frequency, so 「よく本を読みます」 means often reads books. Use the context to tell which meaning is intended. The verb 「読む」 is a godan (u-) verb, its polite form is 「読みます」, and 「を」 marks what is being read. 「彼女は」 makes she the topic. The whole sentence describes her reading habits, and 「よく」 points to the frequency.","grammar:113:ex:words:0:zh":"she","grammar:113:ex:words:0:note":"かのじょ","grammar:113:ex:words:0:pos":"pronoun","grammar:113:ex:words:1:zh":"(topic)","grammar:113:ex:words:1:pos":"particle","grammar:113:ex:words:2:zh":"often","grammar:113:ex:words:2:pos":"adverb","grammar:113:ex:words:3:zh":"book","grammar:113:ex:words:3:note":"ほん","grammar:113:ex:words:3:pos":"noun","grammar:113:ex:words:4:zh":"(object marker)","grammar:113:ex:words:4:pos":"particle","grammar:113:ex:words:5:zh":"read","grammar:113:ex:words:5:note":"よみます","grammar:113:ex:words:5:pos":"verb","grammar:113:ex:points:0":"❓よく has two meanings: here it is often (frequency).","grammar:113:ex:points:1":"読む→読みます。","grammar:113:ex2:trans":"I have a friend I often go out and have fun with.","grammar:113:ex2:structure":"よく〜友達がいます","grammar:113:ex2:words:0:zh":"often","grammar:113:ex2:words:0:pos":"adverb","grammar:113:ex2:words:1:zh":"hang out","grammar:113:ex2:words:1:note":"あそび","grammar:113:ex2:words:1:pos":"noun","grammar:113:ex2:words:2:zh":"(purpose)","grammar:113:ex2:words:2:pos":"particle","grammar:113:ex2:words:3:zh":"go","grammar:113:ex2:words:3:note":"いく","grammar:113:ex2:words:3:pos":"verb","grammar:113:ex2:words:4:zh":"friend","grammar:113:ex2:words:4:note":"ともだち","grammar:113:ex2:words:4:pos":"noun","grammar:113:ex2:words:5:zh":"(nominative)","grammar:113:ex2:words:5:pos":"particle","grammar:113:ex2:words:6:zh":"there is / are","grammar:113:ex2:words:6:pos":"verb","grammar:113:ex2:points:0":"よく: often.","grammar:113:ex2:points:1":"遊びに行く: to go out and have fun.","grammar:113:ex3:trans":"Getting enough sleep is important.","grammar:113:ex3:structure":"よく〜ことが大事です","grammar:113:ex3:words:0:zh":"well","grammar:113:ex3:words:0:pos":"adverb","grammar:113:ex3:words:1:zh":"sleep","grammar:113:ex3:words:1:note":"ねる","grammar:113:ex3:words:1:pos":"verb","grammar:113:ex3:words:2:zh":"(nominalizer)","grammar:113:ex3:words:2:pos":"noun","grammar:113:ex3:words:3:zh":"(nominative)","grammar:113:ex3:words:3:pos":"particle","grammar:113:ex3:words:4:zh":"important","grammar:113:ex3:words:4:note":"だいじ","grammar:113:ex3:words:4:pos":"na-adjective","grammar:113:ex3:words:5:zh":"(polite form)","grammar:113:ex3:words:5:pos":"copula","grammar:113:ex3:points:0":"❓Here よく means properly (degree).","grammar:113:ex3:points:1":"寝ること: sleeping (the act), nominalized.","grammar:113:ex4:trans":"I do not know much about it, but I will go check it out.","grammar:113:ex4:structure":"よく知らないけど〜てみる","grammar:113:ex4:words:0:zh":"(not) much","grammar:113:ex4:words:0:pos":"adverb","grammar:113:ex4:words:1:zh":"don't know","grammar:113:ex4:words:1:note":"しらない","grammar:113:ex4:words:1:pos":"verb","grammar:113:ex4:words:2:zh":"but","grammar:113:ex4:words:2:pos":"particle","grammar:113:ex4:words:3:zh":"go","grammar:113:ex4:words:3:note":"いって","grammar:113:ex4:words:3:pos":"verb","grammar:113:ex4:words:4:zh":"try … and see","grammar:113:ex4:words:4:pos":"auxiliary verb","grammar:113:ex4:points:0":"よく知らない: not really know (よく + negative = not really …).","grammar:113:ex4:points:1":"〜てみる: try doing … (to see how it goes).","grammar:113:ex5:trans":"Let's think it over carefully before deciding.","grammar:113:ex5:structure":"よく〜てから〜ましょう","grammar:113:ex5:words:0:zh":"well","grammar:113:ex5:words:0:pos":"adverb","grammar:113:ex5:words:1:zh":"consider","grammar:113:ex5:words:1:note":"かんがえて","grammar:113:ex5:words:1:pos":"verb","grammar:113:ex5:words:2:zh":"later, afterwards","grammar:113:ex5:words:2:pos":"particle","grammar:113:ex5:words:3:zh":"let's decide","grammar:113:ex5:words:3:note":"きめましょう","grammar:113:ex5:words:3:pos":"verb","grammar:113:ex5:points:0":"〜てから: after doing … (sequence).","grammar:113:ex5:points:1":"よく考えて: think it over carefully.","exam:113:zh":"I come to this shop six days a week, so the staff say to me, 「You come here a lot, don't you?」","exam:113:why":"「よく」 can express high frequency. 「たまに」 means occasionally, which doesn't match coming six days a week."},"114":{"example:114:exzh":"I'm planning to go on a trip.","example:114:exzh2":"I'm planning to study today.","example:114:exzh3":"I'm planning to meet a friend tomorrow.","example:114:exzh4":"I'm planning to exercise, but I haven't managed to yet.","example:114:exzh5":"From now on, I'm planning to study harder.","grammar:114:ex:trans":"I intend to go on a trip.","grammar:114:ex:structure":"verb＋つもりです","grammar:114:ex:explain":"This sentence uses 「〜つもりです」 to express a plan or intention. 「つもり」 is a formal noun; it follows the dictionary form of a verb and means intend to (do) …, so 「行くつもり」 means intend to go. Adding 「です」 at the end makes the tone polite. The 「に」 in 「旅行に」 marks the purpose of the movement. The whole sentence 「旅行に行くつもりです」 means I intend to go on a trip. 「つもり」 expresses a subjective plan, a decision already made, and carries the nuance that the intention was already there, which a plain future expression lacks.","grammar:114:ex:words:0:zh":"travel / trip","grammar:114:ex:words:0:note":"りょこう","grammar:114:ex:words:0:pos":"noun","grammar:114:ex:words:1:zh":"(purpose)","grammar:114:ex:words:1:pos":"particle","grammar:114:ex:words:2:zh":"go","grammar:114:ex:words:2:note":"いく","grammar:114:ex:words:2:pos":"verb","grammar:114:ex:words:3:zh":"intend to","grammar:114:ex:words:3:pos":"noun","grammar:114:ex:words:4:zh":"(polite form)","grammar:114:ex:words:4:pos":"copula","grammar:114:ex:points:0":"〜つもりです: intend to (do) … (intention).","grammar:114:ex:points:1":"verb dictionary form＋つもり.","grammar:114:ex2:trans":"Today I intend to study.","grammar:114:ex2:structure":"verb＋つもりだ","grammar:114:ex2:words:0:zh":"today","grammar:114:ex2:words:0:note":"きょう","grammar:114:ex2:words:0:pos":"noun","grammar:114:ex2:words:1:zh":"(topic)","grammar:114:ex2:words:1:pos":"particle","grammar:114:ex2:words:2:zh":"study","grammar:114:ex2:words:2:note":"べんきょうする","grammar:114:ex2:words:2:pos":"verb","grammar:114:ex2:words:3:zh":"intend to","grammar:114:ex2:words:3:pos":"noun","grammar:114:ex2:words:4:zh":"is (plain form)","grammar:114:ex2:words:4:pos":"copula","grammar:114:ex2:points:0":"〜つもりだ: intend to … (plain form).","grammar:114:ex2:points:1":"勉強する＋つもり。","grammar:114:ex3:trans":"Tomorrow I intend to meet a friend.","grammar:114:ex3:structure":"〜と会うつもりです","grammar:114:ex3:words:0:zh":"tomorrow","grammar:114:ex3:words:0:note":"あした","grammar:114:ex3:words:0:pos":"noun","grammar:114:ex3:words:1:zh":"friend","grammar:114:ex3:words:1:note":"ともだち","grammar:114:ex3:words:1:pos":"noun","grammar:114:ex3:words:2:zh":"with","grammar:114:ex3:words:2:pos":"particle","grammar:114:ex3:words:3:zh":"meet","grammar:114:ex3:words:3:note":"あう","grammar:114:ex3:words:3:pos":"verb","grammar:114:ex3:words:4:zh":"intend to","grammar:114:ex3:words:4:pos":"noun","grammar:114:ex3:words:5:zh":"(polite form)","grammar:114:ex3:words:5:pos":"copula","grammar:114:ex3:points:0":"The person you meet takes と／に with 会う.","grammar:114:ex3:points:1":"〜つもりです: intend to ….","grammar:114:ex4:trans":"I intend to exercise, but I have not managed to yet.","grammar:114:ex4:structure":"〜つもりだけど、まだ〜ていない","grammar:114:ex4:words:0:zh":"exercise","grammar:114:ex4:words:0:note":"うんどう","grammar:114:ex4:words:0:pos":"noun","grammar:114:ex4:words:1:zh":"(object marker)","grammar:114:ex4:words:1:pos":"particle","grammar:114:ex4:words:2:zh":"do","grammar:114:ex4:words:2:pos":"verb","grammar:114:ex4:words:3:zh":"intend to","grammar:114:ex4:words:3:pos":"noun","grammar:114:ex4:words:4:zh":"is","grammar:114:ex4:words:4:pos":"copula","grammar:114:ex4:words:5:zh":"but","grammar:114:ex4:words:5:pos":"particle","grammar:114:ex4:words:6:zh":"still / yet","grammar:114:ex4:words:6:pos":"adverb","grammar:114:ex4:words:7:zh":"have not managed (to do it) yet","grammar:114:ex4:words:7:pos":"verb","grammar:114:ex4:points:0":"つもりだけど: intend to … but … (けど marks contrast).","grammar:114:ex4:points:1":"まだ〜ていない: have not (done) … yet.","grammar:114:ex5:trans":"From now on I intend to study harder.","grammar:114:ex5:structure":"これからは〜つもり","grammar:114:ex5:words:0:zh":"from now on","grammar:114:ex5:words:0:pos":"noun","grammar:114:ex5:words:1:zh":"(topic)","grammar:114:ex5:words:1:pos":"particle","grammar:114:ex5:words:2:zh":"more","grammar:114:ex5:words:2:pos":"adverb","grammar:114:ex5:words:3:zh":"study","grammar:114:ex5:words:3:note":"べんきょうする","grammar:114:ex5:words:3:pos":"verb","grammar:114:ex5:words:4:zh":"intend to","grammar:114:ex5:words:4:pos":"noun","grammar:114:ex5:points:0":"これから: from now on, starting now.","grammar:114:ex5:points:1":"つもり (with だ／です omitted): a casual sentence ending."},"116":{"example:116:exzh":"She is talking with Mama.","example:116:exzh2":"Mama makes meals for me.","example:116:exzh3":"Mama is very kind.","example:116:exzh4":"Mama wakes me up every morning.","example:116:exzh5":"I went shopping with Mama.","grammar:116:ex:trans":"She is talking with her mom.","grammar:116:ex:structure":"〜と話しています","grammar:116:ex:explain":"This sentence uses 「〜と話しています」 to show who she is talking with. Here 「と」 marks the partner in a shared action, so 「ママと話す」 means talk with mom. 「ママ」 is a casual, childlike word for mom and sounds affectionate. The verb 「話す」 in the te-form 「話して」 plus 「います」 gives the 「〜ている」 pattern, which shows an action in progress; 「話しています」 means is talking. The whole sentence 「彼女はママと話しています」 means she is talking with her mom, with 「と」 pointing to the other person in the conversation.","grammar:116:ex:words:0:zh":"she","grammar:116:ex:words:0:note":"かのじょ","grammar:116:ex:words:0:pos":"pronoun","grammar:116:ex:words:1:zh":"(topic)","grammar:116:ex:words:1:pos":"particle","grammar:116:ex:words:2:zh":"mom","grammar:116:ex:words:2:pos":"noun","grammar:116:ex:words:3:zh":"with","grammar:116:ex:words:3:pos":"particle","grammar:116:ex:words:4:zh":"talking","grammar:116:ex:words:4:note":"はなしています","grammar:116:ex:words:4:pos":"verb","grammar:116:ex:points:0":"ママ: mom (casual / childlike).","grammar:116:ex:points:1":"〜と話す: to talk with ….","grammar:116:ex2:trans":"Mom cooks for me.","grammar:116:ex2:structure":"〜てくれる","grammar:116:ex2:words:0:zh":"mom","grammar:116:ex2:words:0:pos":"noun","grammar:116:ex2:words:1:zh":"(nominative)","grammar:116:ex2:words:1:pos":"particle","grammar:116:ex2:words:2:zh":"meal","grammar:116:ex2:words:2:note":"ごはん","grammar:116:ex2:words:2:pos":"noun","grammar:116:ex2:words:3:zh":"(object marker)","grammar:116:ex2:words:3:pos":"particle","grammar:116:ex2:words:4:zh":"makes (for me)","grammar:116:ex2:words:4:note":"つくってくれる","grammar:116:ex2:words:4:pos":"verb","grammar:116:ex2:points:0":"〜てくれる: (someone else) does … for me.","grammar:116:ex2:points:1":"作る→作って＋くれる。","grammar:116:ex3:trans":"Mom is very kind.","grammar:116:ex3:structure":"〜はとても〜です","grammar:116:ex3:words:0:zh":"mom","grammar:116:ex3:words:0:pos":"noun","grammar:116:ex3:words:1:zh":"(topic)","grammar:116:ex3:words:1:pos":"particle","grammar:116:ex3:words:2:zh":"extremely","grammar:116:ex3:words:2:pos":"adverb","grammar:116:ex3:words:3:zh":"kind","grammar:116:ex3:words:3:note":"やさしい","grammar:116:ex3:words:3:pos":"adjective","grammar:116:ex3:words:4:zh":"(polite form)","grammar:116:ex3:words:4:pos":"copula","grammar:116:ex3:points:0":"優しい: kind (i-adjective).","grammar:116:ex3:points:1":"とても modifies 優しい.","grammar:116:ex4:trans":"Mom wakes me up every morning.","grammar:116:ex4:structure":"〜てくれます","grammar:116:ex4:words:0:zh":"every morning","grammar:116:ex4:words:0:note":"まいあさ","grammar:116:ex4:words:0:pos":"adverb","grammar:116:ex4:words:1:zh":"mom","grammar:116:ex4:words:1:pos":"noun","grammar:116:ex4:words:2:zh":"(nominative)","grammar:116:ex4:words:2:pos":"particle","grammar:116:ex4:words:3:zh":"wakes (me) up","grammar:116:ex4:words:3:note":"おこしてくれます","grammar:116:ex4:words:3:pos":"verb","grammar:116:ex4:points:0":"起こす: to wake (someone) up (transitive verb).","grammar:116:ex4:points:1":"〜てくれます: does … for me (polite form).","grammar:116:ex5:trans":"I went shopping with my mom.","grammar:116:ex5:structure":"〜と一緒に〜をしました","grammar:116:ex5:words:0:zh":"mom","grammar:116:ex5:words:0:pos":"noun","grammar:116:ex5:words:1:zh":"with","grammar:116:ex5:words:1:pos":"particle","grammar:116:ex5:words:2:zh":"together","grammar:116:ex5:words:2:note":"いっしょに","grammar:116:ex5:words:2:pos":"adverb","grammar:116:ex5:words:3:zh":"shopping","grammar:116:ex5:words:3:note":"かいもの","grammar:116:ex5:words:3:pos":"noun","grammar:116:ex5:words:4:zh":"(object marker)","grammar:116:ex5:words:4:pos":"particle","grammar:116:ex5:words:5:zh":"did","grammar:116:ex5:words:5:pos":"verb","grammar:116:ex5:points:0":"買い物をする: to go shopping.","grammar:116:ex5:points:1":"〜と一緒に: together with…","exam:116:zh":"A small child found their mother and said, \"Mommy, pick me up.\"","exam:116:why":"「ママ」 is how a child says mom. 「お姉さん」 means an older sister or a young woman, which doesn't match the mother the sentence clearly refers to."},"117":{"example:117:exzh":"I asked a friend for help.","example:117:exzh2":"Try asking him for help.","example:117:exzh3":"I'd like to ask you to do this job.","example:117:exzh4":"Ask everyone to lend a hand.","example:117:exzh5":"If there's a favor you want to ask, please tell me.","grammar:117:ex:trans":"I asked a friend for help.","grammar:117:ex:structure":"〜に〜を頼みました","grammar:117:ex:explain":"This sentence uses the transitive verb 「頼む」 with 「に」. 「頼む（たのむ）」 means to ask, request, or entrust. The person you ask takes 「に」, so 「友達に頼む」 means to ask a friend; what you ask for takes 「を」, so 「助けを頼む」 means to ask for help. 「頼む」 is a godan (u-) verb, past polite form 「頼みました」. The whole sentence 「友達に助けを頼みました」 means I asked a friend for help. Remember the split: 「に」 for the person, 「を」 for the content.","grammar:117:ex:words:0:zh":"friend","grammar:117:ex:words:0:note":"ともだち","grammar:117:ex:words:0:pos":"noun","grammar:117:ex:words:1:zh":"(object)","grammar:117:ex:words:1:pos":"particle","grammar:117:ex:words:2:zh":"help","grammar:117:ex:words:2:note":"たすけ","grammar:117:ex:words:2:pos":"noun","grammar:117:ex:words:3:zh":"(object marker)","grammar:117:ex:words:3:pos":"particle","grammar:117:ex:words:4:zh":"asked for","grammar:117:ex:words:4:note":"たのみました","grammar:117:ex:words:4:pos":"verb","grammar:117:ex:points:0":"❗頼む（たのむ）: to ask, request, entrust (transitive verb); 〜に頼む = ask … (the person takes に); 助けを頼む = ask for help.","grammar:117:ex:points:1":"助けを頼む: ask for help.","grammar:117:ex2:trans":"Try asking him for help.","grammar:117:ex2:structure":"〜に頼んでみてください","grammar:117:ex2:words:0:zh":"he","grammar:117:ex2:words:0:note":"かれ","grammar:117:ex2:words:0:pos":"pronoun","grammar:117:ex2:words:1:zh":"(object)","grammar:117:ex2:words:1:pos":"particle","grammar:117:ex2:words:2:zh":"please","grammar:117:ex2:words:2:note":"たのんで","grammar:117:ex2:words:2:pos":"verb","grammar:117:ex2:words:3:zh":"try … and see","grammar:117:ex2:words:3:pos":"auxiliary verb","grammar:117:ex2:words:4:zh":"please","grammar:117:ex2:words:4:pos":"auxiliary verb","grammar:117:ex2:points:0":"❗〜てみる: try doing …; 彼に頼む = ask him.","grammar:117:ex2:points:1":"頼んでみる: try asking.","grammar:117:ex3:trans":"I'd like to ask you to take on this job.","grammar:117:ex3:structure":"〜を頼むんです","grammar:117:ex3:words:0:zh":"this","grammar:117:ex3:words:0:pos":"pre-noun adjectival","grammar:117:ex3:words:1:zh":"work","grammar:117:ex3:words:1:note":"しごと","grammar:117:ex3:words:1:pos":"noun","grammar:117:ex3:words:2:zh":"(object marker)","grammar:117:ex3:words:2:pos":"particle","grammar:117:ex3:words:3:zh":"please","grammar:117:ex3:words:3:note":"たのむ","grammar:117:ex3:words:3:pos":"verb","grammar:117:ex3:words:4:zh":"(tone)","grammar:117:ex3:words:4:pos":"particle","grammar:117:ex3:words:5:zh":"(polite form)","grammar:117:ex3:words:5:pos":"copula","grammar:117:ex3:points:0":"❗仕事を頼む: to entrust someone with work; 〜んです = explanatory tone.","grammar:117:ex3:points:1":"仕事を頼む: entrust someone with work.","grammar:117:ex4:trans":"Ask everyone to help.","grammar:117:ex4:structure":"〜に頼んで手伝ってもらう","grammar:117:ex4:words:0:zh":"everyone","grammar:117:ex4:words:0:pos":"pronoun","grammar:117:ex4:words:1:zh":"(object)","grammar:117:ex4:words:1:pos":"particle","grammar:117:ex4:words:2:zh":"please","grammar:117:ex4:words:2:note":"たのんで","grammar:117:ex4:words:2:pos":"verb","grammar:117:ex4:words:3:zh":"help","grammar:117:ex4:words:3:note":"てつだって","grammar:117:ex4:words:3:pos":"verb","grammar:117:ex4:words:4:zh":"(receiving a favor)","grammar:117:ex4:words:4:pos":"auxiliary verb","grammar:117:ex4:points:0":"❗〜に頼んで〜てもらう: ask … to do … for you; 手伝ってもらう = have someone help you.","grammar:117:ex4:points:1":"頼んで手伝ってもらう: ask someone to help.","grammar:117:ex5:trans":"If there's anything you'd like to ask me, just say so.","grammar:117:ex5:structure":"頼み事があれば言ってください","grammar:117:ex5:words:0:zh":"a request","grammar:117:ex5:words:0:note":"たのみごと","grammar:117:ex5:words:0:pos":"noun","grammar:117:ex5:words:1:zh":"(nominative)","grammar:117:ex5:words:1:pos":"particle","grammar:117:ex5:words:2:zh":"if there is","grammar:117:ex5:words:2:pos":"verb","grammar:117:ex5:words:3:zh":"tell","grammar:117:ex5:words:3:note":"いって","grammar:117:ex5:words:3:pos":"verb","grammar:117:ex5:words:4:zh":"please","grammar:117:ex5:words:4:pos":"auxiliary verb","grammar:117:ex5:points:0":"❗頼み事: something you want to ask for (頼む + 事); 〜があれば = if there is …","grammar:117:ex5:points:1":"頼み事: a request."},"118":{"example:118:exzh":"She is a woman.","example:118:exzh2":"Many women are working.","example:118:exzh3":"That woman is very beautiful.","example:118:exzh4":"The girl is playing.","example:118:exzh5":"Many women live in that city.","grammar:118:ex:trans":"She is a woman.","grammar:118:ex:structure":"〜は女です","grammar:118:ex:explain":"This is the noun-predicate sentence 「彼女は女です」. 「女（おんな）」 is a noun meaning woman, female. 「は」 makes 「彼女」 the topic, and the predicate 「女です」 uses 「です」 for a polite statement. The whole sentence 「彼女は女です」 means she is a woman. Note that 「女」 on its own sounds blunt; in formal or polite situations people usually say 「女性（じょせい）」. Likewise 「男」 corresponds to 「男性」, so choose the word to fit the situation and level of speech.","grammar:118:ex:words:0:zh":"she","grammar:118:ex:words:0:note":"かのじょ","grammar:118:ex:words:0:pos":"pronoun","grammar:118:ex:words:1:zh":"(topic)","grammar:118:ex:words:1:pos":"particle","grammar:118:ex:words:2:zh":"woman","grammar:118:ex:words:2:note":"おんな","grammar:118:ex:words:2:pos":"noun","grammar:118:ex:words:3:zh":"is","grammar:118:ex:words:3:pos":"copula","grammar:118:ex:points:0":"女（おんな）: woman / female.","grammar:118:ex:points:1":"noun＋です.","grammar:118:ex2:trans":"Many women are working.","grammar:118:ex2:structure":"多くの〜が〜ています","grammar:118:ex2:words:0:zh":"a lot","grammar:118:ex2:words:0:note":"おおく","grammar:118:ex2:words:0:pos":"noun","grammar:118:ex2:words:1:zh":"'s","grammar:118:ex2:words:1:pos":"particle","grammar:118:ex2:words:2:zh":"woman","grammar:118:ex2:words:2:note":"おんな","grammar:118:ex2:words:2:pos":"noun","grammar:118:ex2:words:3:zh":"(nominative)","grammar:118:ex2:words:3:pos":"particle","grammar:118:ex2:words:4:zh":"are working","grammar:118:ex2:words:4:note":"はたらいています","grammar:118:ex2:words:4:pos":"verb","grammar:118:ex2:points:0":"多くの女: many women.","grammar:118:ex2:points:1":"働く→働いて＋います (is working).","grammar:118:ex3:trans":"That woman is very beautiful.","grammar:118:ex3:structure":"その女は〜です","grammar:118:ex3:words:0:zh":"that","grammar:118:ex3:words:0:pos":"pre-noun adjectival","grammar:118:ex3:words:1:zh":"woman","grammar:118:ex3:words:1:note":"おんな","grammar:118:ex3:words:1:pos":"noun","grammar:118:ex3:words:2:zh":"(topic)","grammar:118:ex3:words:2:pos":"particle","grammar:118:ex3:words:3:zh":"extremely","grammar:118:ex3:words:3:pos":"adverb","grammar:118:ex3:words:4:zh":"beautiful","grammar:118:ex3:words:4:note":"うつくしい","grammar:118:ex3:words:4:pos":"adjective","grammar:118:ex3:words:5:zh":"(polite form)","grammar:118:ex3:words:5:pos":"copula","grammar:118:ex3:points:0":"美しい: beautiful (i-adjective).","grammar:118:ex3:points:1":"その女: that woman.","grammar:118:ex4:trans":"The girl is playing.","grammar:118:ex4:structure":"〜は遊んでいます","grammar:118:ex4:words:0:zh":"girl","grammar:118:ex4:words:0:note":"おんなのこ","grammar:118:ex4:words:0:pos":"noun","grammar:118:ex4:words:1:zh":"(topic)","grammar:118:ex4:words:1:pos":"particle","grammar:118:ex4:words:2:zh":"playing","grammar:118:ex4:words:2:note":"あそんでいます","grammar:118:ex4:words:2:pos":"verb","grammar:118:ex4:points:0":"女の子: girl (女＋の＋子).","grammar:118:ex4:points:1":"〜ている: ongoing action.","grammar:118:ex5:trans":"Many women live in that city.","grammar:118:ex5:structure":"〜には〜が住んでいます","grammar:118:ex5:words:0:zh":"that","grammar:118:ex5:words:0:pos":"pre-noun adjectival","grammar:118:ex5:words:1:zh":"city","grammar:118:ex5:words:1:note":"まち","grammar:118:ex5:words:1:pos":"noun","grammar:118:ex5:words:2:zh":"(location of existence)","grammar:118:ex5:words:2:pos":"particle","grammar:118:ex5:words:3:zh":"(contrast)","grammar:118:ex5:words:3:pos":"particle","grammar:118:ex5:words:4:zh":"a lot","grammar:118:ex5:words:4:note":"おおく","grammar:118:ex5:words:4:pos":"noun","grammar:118:ex5:words:5:zh":"'s","grammar:118:ex5:words:5:pos":"particle","grammar:118:ex5:words:6:zh":"woman","grammar:118:ex5:words:6:note":"おんな","grammar:118:ex5:words:6:pos":"noun","grammar:118:ex5:words:7:zh":"(nominative)","grammar:118:ex5:words:7:pos":"particle","grammar:118:ex5:words:8:zh":"live (there)","grammar:118:ex5:words:8:note":"すんでいます","grammar:118:ex5:words:8:pos":"verb","grammar:118:ex5:points:0":"〜に住んでいる: to live in … (に marks the place of residence).","grammar:118:ex5:points:1":"多くの女: many women.","exam:118:zh":"When my little sister was born, my dad said, 「The baby is a girl.」","exam:118:why":"「女の子」 means girl, which matches 「妹」. 「男の子」 means boy, which doesn't fit a little sister's sex."},"119":{"example:119:exzh":"Please stop that behavior.","example:119:exzh2":"It's better to stop smoking.","example:119:exzh3":"I will quit this job.","example:119:exzh4":"I can't stop anymore.","example:119:exzh5":"If there's a problem, please stop.","grammar:119:ex:trans":"Please stop that behavior.","grammar:119:ex:structure":"〜を止めてください","grammar:119:ex:explain":"This sentence makes a request using the transitive verb 「止める」 with 「を」. 「止める」 has two readings: 「やめる」 means “stop (an activity),” while 「とめる」 means “bring… to a stop (a car or machine).” Here, 「行動を止める」 is read 「やめる」 and means “stop an action.” 「その」 directly modifies 「行動」. The verb’s te-form 「止めて」 combines with 「ください」 to make a polite request. The whole sentence, 「その行動を止めてください」, means “Please stop that behavior.”","grammar:119:ex:words:0:zh":"that","grammar:119:ex:words:0:pos":"pre-noun adjectival","grammar:119:ex:words:1:zh":"actions","grammar:119:ex:words:1:note":"こうどう","grammar:119:ex:words:1:pos":"noun","grammar:119:ex:words:2:zh":"(object marker)","grammar:119:ex:words:2:pos":"particle","grammar:119:ex:words:3:zh":"stop","grammar:119:ex:words:3:note":"やめて","grammar:119:ex:words:3:pos":"verb","grammar:119:ex:words:4:zh":"please","grammar:119:ex:words:4:pos":"auxiliary verb","grammar:119:ex:points:0":"❗止める: read 『やめる』, it means “stop (an activity)”; read 『とめる』, it means “bring… to a stop (a car or machine)”; here, 『行動を止める（やめる）』＝stop an action.","grammar:119:ex:points:1":"行動を止める: stop an action.","grammar:119:ex2:trans":"You should stop smoking.","grammar:119:ex2:structure":"〜を止めた方がいい","grammar:119:ex2:words:0:zh":"Smoking","grammar:119:ex2:words:0:note":"きつえん","grammar:119:ex2:words:0:pos":"noun","grammar:119:ex2:words:1:zh":"(object marker)","grammar:119:ex2:words:1:pos":"particle","grammar:119:ex2:words:2:zh":"stop","grammar:119:ex2:words:2:note":"やめた","grammar:119:ex2:words:2:pos":"verb","grammar:119:ex2:words:3:zh":"it's better to","grammar:119:ex2:words:3:note":"ほうがいい","grammar:119:ex2:words:3:pos":"set phrase","grammar:119:ex2:points:0":"❗喫煙を止める（やめる）: quit smoking; 〜た方がいい＝it is best to….","grammar:119:ex2:points:1":"喫煙を止める: quit smoking.","grammar:119:ex3:trans":"I will stop doing this job.","grammar:119:ex3:structure":"〜を止めます","grammar:119:ex3:words:0:zh":"I","grammar:119:ex3:words:0:note":"わたし","grammar:119:ex3:words:0:pos":"pronoun","grammar:119:ex3:words:1:zh":"(topic)","grammar:119:ex3:words:1:pos":"particle","grammar:119:ex3:words:2:zh":"this","grammar:119:ex3:words:2:pos":"pre-noun adjectival","grammar:119:ex3:words:3:zh":"work","grammar:119:ex3:words:3:note":"しごと","grammar:119:ex3:words:3:pos":"noun","grammar:119:ex3:words:4:zh":"(object marker)","grammar:119:ex3:words:4:pos":"particle","grammar:119:ex3:words:5:zh":"stop","grammar:119:ex3:words:5:note":"やめます","grammar:119:ex3:words:5:pos":"verb","grammar:119:ex3:points:0":"❗仕事を止める（やめる）: to quit a job (also often written 『辞める』 in this sense).","grammar:119:ex3:points:1":"仕事を止める: to quit a job.","grammar:119:ex4:trans":"I can no longer stop.","grammar:119:ex4:structure":"もう止められない","grammar:119:ex4:words:0:zh":"already","grammar:119:ex4:words:0:pos":"adverb","grammar:119:ex4:words:1:zh":"cannot stop","grammar:119:ex4:words:1:note":"とめられない","grammar:119:ex4:words:1:pos":"verb","grammar:119:ex4:points:0":"❗止められない: cannot stop (the negative potential form of 止める『とめる』, meaning to make something stop); as with an unstoppable trend, 止まらない.","grammar:119:ex4:points:1":"止められない: cannot stop.","grammar:119:ex5:trans":"If there is a problem, please stop.","grammar:119:ex5:structure":"〜があれば止めてください","grammar:119:ex5:words:0:zh":"what","grammar:119:ex5:words:0:note":"なにか","grammar:119:ex5:words:0:pos":"pronoun","grammar:119:ex5:words:1:zh":"problem","grammar:119:ex5:words:1:note":"もんだい","grammar:119:ex5:words:1:pos":"noun","grammar:119:ex5:words:2:zh":"(nominative)","grammar:119:ex5:words:2:pos":"particle","grammar:119:ex5:words:3:zh":"if there is","grammar:119:ex5:words:3:pos":"verb","grammar:119:ex5:words:4:zh":"to stop","grammar:119:ex5:words:4:note":"とめて","grammar:119:ex5:words:4:pos":"verb","grammar:119:ex5:words:5:zh":"please","grammar:119:ex5:words:5:pos":"auxiliary verb","grammar:119:ex5:points:0":"❗止める（とめる）: to stop something (a machine or an action); 問題があれば止める = to stop the machine if there is a problem.","grammar:119:ex5:points:1":"止める: to make something stop."},"120":{"example:120:exzh":"Please call my name.","example:120:exzh2":"He called me.","example:120:exzh3":"When you call the dog, it comes.","example:120:exzh4":"She called me over and asked me for help.","example:120:exzh5":"I'll call friends over and throw a party.","grammar:120:ex:trans":"Please call my name.","grammar:120:ex:structure":"〜を呼んでください","grammar:120:ex:explain":"This sentence uses the transitive verb 「呼ぶ」 with 「を」 to make a request. 「呼ぶ（よぶ）」 means 'to call, to call out to, to hail'; the person or thing being called is marked with 「を」, so 「名前を呼ぶ」 = 'to call someone's name'. 「呼ぶ」 ends in 「ぶ」 and is a godan (u-) verb; its te-form is 「呼んで」 (the sound change ぶ→んで), and adding 「ください」 makes a polite request. The whole sentence 「名前を呼んでください」 = 'please call my name' — the te-form sound change for verbs ending in 「ぶ」 is the key point.","grammar:120:ex:words:0:zh":"name","grammar:120:ex:words:0:note":"なまえ","grammar:120:ex:words:0:pos":"noun","grammar:120:ex:words:1:zh":"(object marker)","grammar:120:ex:words:1:pos":"particle","grammar:120:ex:words:2:zh":"call","grammar:120:ex:words:2:note":"よんで","grammar:120:ex:words:2:pos":"verb","grammar:120:ex:words:3:zh":"please","grammar:120:ex:words:3:pos":"auxiliary verb","grammar:120:ex:points:0":"❗呼ぶ（よぶ）: to call, to call out, to hail.","grammar:120:ex:points:1":"名前を呼ぶ: to call someone's name.","grammar:120:ex2:trans":"He called me.","grammar:120:ex2:structure":"〜を呼びました","grammar:120:ex2:words:0:zh":"he","grammar:120:ex2:words:0:note":"かれ","grammar:120:ex2:words:0:pos":"pronoun","grammar:120:ex2:words:1:zh":"(topic)","grammar:120:ex2:words:1:pos":"particle","grammar:120:ex2:words:2:zh":"I","grammar:120:ex2:words:2:note":"わたし","grammar:120:ex2:words:2:pos":"pronoun","grammar:120:ex2:words:3:zh":"(object marker)","grammar:120:ex2:words:3:pos":"particle","grammar:120:ex2:words:4:zh":"called","grammar:120:ex2:words:4:note":"よびました","grammar:120:ex2:words:4:pos":"verb","grammar:120:ex2:points:0":"私を呼ぶ: to call me.","grammar:120:ex2:points:1":"呼ぶ→呼びました。","grammar:120:ex3:trans":"When you call the dog, it comes.","grammar:120:ex3:structure":"〜を呼ぶと〜ます","grammar:120:ex3:words:0:zh":"dog","grammar:120:ex3:words:0:note":"いぬ","grammar:120:ex3:words:0:pos":"noun","grammar:120:ex3:words:1:zh":"(object marker)","grammar:120:ex3:words:1:pos":"particle","grammar:120:ex3:words:2:zh":"call","grammar:120:ex3:words:2:note":"よぶ","grammar:120:ex3:words:2:pos":"verb","grammar:120:ex3:words:3:zh":"(as soon as…)","grammar:120:ex3:words:3:pos":"particle","grammar:120:ex3:words:4:zh":"come","grammar:120:ex3:words:4:note":"きます","grammar:120:ex3:words:4:pos":"verb","grammar:120:ex3:points:0":"❗〜と: as soon as ..., ... (call it and it comes).","grammar:120:ex3:points:1":"犬を呼ぶ: to call the dog.","grammar:120:ex4:trans":"She called me over and asked me to help.","grammar:120:ex4:structure":"〜を呼んで、助けを求めた","grammar:120:ex4:explain":"「私を呼んで」 means 'called me' and uses the te-form to link to the next action, asking for help. Here 「助け」 is a noun acting as the object of 「求める」. The past tense of 「求めた」 covers the whole sequence, showing that both calling me and asking for help already happened.","grammar:120:ex4:words:0:zh":"she","grammar:120:ex4:words:0:note":"かのじょ","grammar:120:ex4:words:0:pos":"pronoun","grammar:120:ex4:words:1:zh":"(topic)","grammar:120:ex4:words:1:pos":"particle","grammar:120:ex4:words:2:zh":"I","grammar:120:ex4:words:2:note":"わたし","grammar:120:ex4:words:2:pos":"pronoun","grammar:120:ex4:words:3:zh":"(object)","grammar:120:ex4:words:3:pos":"particle","grammar:120:ex4:words:4:zh":"call, call out","grammar:120:ex4:words:4:note":"よん","grammar:120:ex4:words:4:pos":"verb","grammar:120:ex4:words:5:zh":"(links the two actions)","grammar:120:ex4:words:5:pos":"particle","grammar:120:ex4:words:6:zh":"help","grammar:120:ex4:words:6:note":"たすけ","grammar:120:ex4:words:6:pos":"noun","grammar:120:ex4:words:7:zh":"(object)","grammar:120:ex4:words:7:pos":"particle","grammar:120:ex4:words:8:zh":"seek, ask for","grammar:120:ex4:words:8:note":"もとめ","grammar:120:ex4:words:8:pos":"verb","grammar:120:ex4:words:9:zh":"(past, completed)","grammar:120:ex4:words:9:pos":"auxiliary verb","grammar:120:ex4:points:0":"The te-form of 「呼ぶ」 is 「呼んで」; godan verbs ending in 「ぶ」 change to 「んで」.","grammar:120:ex4:points:1":"「助けを求める」 is a common set phrase meaning to ask for help.","grammar:120:ex5:trans":"I'll invite friends over and throw a party.","grammar:120:ex5:structure":"〜を呼んで〜を開きます","grammar:120:ex5:words:0:zh":"friend","grammar:120:ex5:words:0:note":"ともだち","grammar:120:ex5:words:0:pos":"noun","grammar:120:ex5:words:1:zh":"(object marker)","grammar:120:ex5:words:1:pos":"particle","grammar:120:ex5:words:2:zh":"call","grammar:120:ex5:words:2:note":"よんで","grammar:120:ex5:words:2:pos":"verb","grammar:120:ex5:words:3:zh":"party","grammar:120:ex5:words:3:note":"loanword","grammar:120:ex5:words:3:pos":"noun","grammar:120:ex5:words:4:zh":"(object marker)","grammar:120:ex5:words:4:pos":"particle","grammar:120:ex5:words:5:zh":"hold (an event)","grammar:120:ex5:words:5:note":"ひらきます","grammar:120:ex5:words:5:pos":"verb","grammar:120:ex5:points:0":"❗パーティーを開く: to throw a party.","grammar:120:ex5:points:1":"友達を呼ぶ: to invite friends."},"121":{"example:121:exzh":"The police came.","example:121:exzh2":"I asked the police for help.","example:121:exzh3":"The police officer is very kind.","example:121:exzh4":"I reported the incident to the police.","example:121:exzh5":"The police keep the city safe.","grammar:121:ex:trans":"The police came.","grammar:121:ex:structure":"〜が来ました","grammar:121:ex:explain":"This sentence uses 「が」 to mark something that appears or happens. 「警察」 means police, and the past polite form of the verb 「来る」 is the irregular 「来ました」. 「が」 is used rather than 「は」 because this describes something that has just appeared or happened, presenting 「警察」 as new information; 「警察が来ました」 means the police have come (this has happened). With 「警察は」, the nuance would shift to contrasting or explaining the police. The whole sentence is a typical way to report a sudden situation happening right in front of you.","grammar:121:ex:words:0:zh":"police","grammar:121:ex:words:0:note":"けいさつ","grammar:121:ex:words:0:pos":"noun","grammar:121:ex:words:1:zh":"(nominative)","grammar:121:ex:words:1:pos":"particle","grammar:121:ex:words:2:zh":"came","grammar:121:ex:words:2:note":"きました","grammar:121:ex:words:2:pos":"verb","grammar:121:ex:points:0":"警察（けいさつ）: police.","grammar:121:ex:points:1":"が marks the one who comes (new information).","grammar:121:ex2:trans":"I asked the police for help.","grammar:121:ex2:structure":"〜に助けを求めました","grammar:121:ex2:words:0:zh":"I","grammar:121:ex2:words:0:note":"わたし","grammar:121:ex2:words:0:pos":"pronoun","grammar:121:ex2:words:1:zh":"(topic)","grammar:121:ex2:words:1:pos":"particle","grammar:121:ex2:words:2:zh":"police","grammar:121:ex2:words:2:note":"けいさつ","grammar:121:ex2:words:2:pos":"noun","grammar:121:ex2:words:3:zh":"(object)","grammar:121:ex2:words:3:pos":"particle","grammar:121:ex2:words:4:zh":"help","grammar:121:ex2:words:4:note":"たすけ","grammar:121:ex2:words:4:pos":"noun","grammar:121:ex2:words:5:zh":"(object marker)","grammar:121:ex2:words:5:pos":"particle","grammar:121:ex2:words:6:zh":"asked for","grammar:121:ex2:words:6:note":"もとめました","grammar:121:ex2:words:6:pos":"verb","grammar:121:ex2:points:0":"〜に助けを求める: to ask … for help (the person asked takes に).","grammar:121:ex2:points:1":"求める: to ask for, to seek.","grammar:121:ex3:trans":"The police officer is very kind.","grammar:121:ex3:structure":"〜はとても〜です","grammar:121:ex3:words:0:zh":"police officer","grammar:121:ex3:words:0:note":"けいさつかん","grammar:121:ex3:words:0:pos":"noun","grammar:121:ex3:words:1:zh":"(topic)","grammar:121:ex3:words:1:pos":"particle","grammar:121:ex3:words:2:zh":"extremely","grammar:121:ex3:words:2:pos":"adverb","grammar:121:ex3:words:3:zh":"kind","grammar:121:ex3:words:3:note":"しんせつ","grammar:121:ex3:words:3:pos":"na-adjective","grammar:121:ex3:words:4:zh":"(polite form)","grammar:121:ex3:words:4:pos":"copula","grammar:121:ex3:points:0":"警察官: police officer (官 indicates a person in that role).","grammar:121:ex3:points:1":"親切: kind (na-adjective).","grammar:121:ex4:trans":"I reported the incident to the police.","grammar:121:ex4:structure":"〜を〜に報告しました","grammar:121:ex4:words:0:zh":"incident","grammar:121:ex4:words:0:note":"じけん","grammar:121:ex4:words:0:pos":"noun","grammar:121:ex4:words:1:zh":"(object marker)","grammar:121:ex4:words:1:pos":"particle","grammar:121:ex4:words:2:zh":"police","grammar:121:ex4:words:2:note":"けいさつ","grammar:121:ex4:words:2:pos":"noun","grammar:121:ex4:words:3:zh":"(object)","grammar:121:ex4:words:3:pos":"particle","grammar:121:ex4:words:4:zh":"reported","grammar:121:ex4:words:4:note":"ほうこくしました","grammar:121:ex4:words:4:pos":"verb","grammar:121:ex4:points:0":"〜を〜に報告する: to report … to … (を marks the content, に the recipient).","grammar:121:ex4:points:1":"報告する→報告しました。","grammar:121:ex5:trans":"The police keep the city safe.","grammar:121:ex5:structure":"〜を守っています","grammar:121:ex5:words:0:zh":"police","grammar:121:ex5:words:0:note":"けいさつ","grammar:121:ex5:words:0:pos":"noun","grammar:121:ex5:words:1:zh":"(topic)","grammar:121:ex5:words:1:pos":"particle","grammar:121:ex5:words:2:zh":"city","grammar:121:ex5:words:2:note":"まち","grammar:121:ex5:words:2:pos":"noun","grammar:121:ex5:words:3:zh":"'s","grammar:121:ex5:words:3:pos":"particle","grammar:121:ex5:words:4:zh":"safe","grammar:121:ex5:words:4:note":"あんぜん","grammar:121:ex5:words:4:pos":"noun","grammar:121:ex5:words:5:zh":"(object marker)","grammar:121:ex5:words:5:pos":"particle","grammar:121:ex5:words:6:zh":"protecting","grammar:121:ex5:words:6:note":"まもっています","grammar:121:ex5:words:6:pos":"verb","grammar:121:ex5:points:0":"守る: to protect, to guard.","grammar:121:ex5:points:1":"〜ている: ongoing (they keep it safe)."},"122":{"example:122:exzh":"I'm worried about her.","example:122:exzh2":"Parents worry about their children.","example:122:exzh3":"Please don't worry.","example:122:exzh4":"I'm worried about tomorrow's exam.","example:122:exzh5":"He seems to be worried.","grammar:122:ex:trans":"I'm really worried about her.","grammar:122:ex:structure":"person＋のことを心配しています","grammar:122:ex:explain":"「彼女のこと」 doesn't refer to one specific thing; it sums up her situation as a whole, so it's naturally translated as 'her'. 「を」 marks what the worry is about, and 「心配しています」 shows that the state of worrying continues. The original sentence has no adverb of degree, but the 'really' in the Chinese is kept as specified in the translation.","grammar:122:ex:words:0:zh":"she","grammar:122:ex:words:0:note":"かのじょ","grammar:122:ex:words:0:pos":"pronoun","grammar:122:ex:words:1:zh":"(links the person to 「こと」)","grammar:122:ex:words:1:pos":"particle","grammar:122:ex:words:2:zh":"things concerning her, her situation","grammar:122:ex:words:2:pos":"noun","grammar:122:ex:words:3:zh":"(object)","grammar:122:ex:words:3:pos":"particle","grammar:122:ex:words:4:zh":"worry","grammar:122:ex:words:4:note":"しんぱいし","grammar:122:ex:words:4:pos":"verb","grammar:122:ex:words:5:zh":"(links to the progressive expression that follows)","grammar:122:ex:words:5:pos":"particle","grammar:122:ex:words:6:zh":"(the worry continues)","grammar:122:ex:words:6:pos":"verb","grammar:122:ex:words:7:zh":"(polite tone)","grammar:122:ex:words:7:pos":"auxiliary verb","grammar:122:ex:points:0":"「人物＋のこと」 can cover the person's circumstances, safety, and other related matters.","grammar:122:ex:points:1":"With the verb 「心配する」, what you're worried about can be marked with 「を」.","grammar:122:ex2:trans":"Parents worry about their children.","grammar:122:ex2:structure":"〜のことを心配します","grammar:122:ex2:words:0:zh":"parents","grammar:122:ex2:words:0:note":"おや","grammar:122:ex2:words:0:pos":"noun","grammar:122:ex2:words:1:zh":"(topic)","grammar:122:ex2:words:1:pos":"particle","grammar:122:ex2:words:2:zh":"child","grammar:122:ex2:words:2:note":"こども","grammar:122:ex2:words:2:pos":"noun","grammar:122:ex2:words:3:zh":"'s","grammar:122:ex2:words:3:pos":"particle","grammar:122:ex2:words:4:zh":"thing / matter","grammar:122:ex2:words:4:pos":"noun","grammar:122:ex2:words:5:zh":"(object marker)","grammar:122:ex2:words:5:pos":"particle","grammar:122:ex2:words:6:zh":"worry","grammar:122:ex2:words:6:note":"しんぱいします","grammar:122:ex2:words:6:pos":"verb","grammar:122:ex2:points:0":"❗〜のことを心配する: to worry about ...","grammar:122:ex2:points:1":"親: parents","grammar:122:ex3:trans":"Please don't worry.","grammar:122:ex3:structure":"心配しないでください","grammar:122:ex3:words:0:zh":"don't worry","grammar:122:ex3:words:0:note":"しんぱいしないで","grammar:122:ex3:words:0:pos":"verb","grammar:122:ex3:words:1:zh":"please","grammar:122:ex3:words:1:pos":"auxiliary verb","grammar:122:ex3:points:0":"❗〜ないでください: please don't ...","grammar:122:ex3:points:1":"心配しないで: don't worry.","grammar:122:ex4:trans":"I'm worried about tomorrow's exam.","grammar:122:ex4:structure":"〜のことを心配しています","grammar:122:ex4:explain":"The first 「の」 lets 「明日」 modify 「テスト」, and the second 「の」 links the whole 「明日のテスト」 to 「こと」. 「明日のテストのこと」 can include the exam's content, how prepared you are, the result, and other related matters. 「心配しています」 shows ongoing worry now, and the subject 'I' is left out because it's understood from context.","grammar:122:ex4:words:0:zh":"tomorrow","grammar:122:ex4:words:0:note":"あした","grammar:122:ex4:words:0:pos":"noun","grammar:122:ex4:words:1:zh":"(time modifier)","grammar:122:ex4:words:1:pos":"particle","grammar:122:ex4:words:2:zh":"test","grammar:122:ex4:words:2:pos":"noun","grammar:122:ex4:words:3:zh":"(links the matter to 「こと」)","grammar:122:ex4:words:3:pos":"particle","grammar:122:ex4:words:4:zh":"related matters","grammar:122:ex4:words:4:pos":"noun","grammar:122:ex4:words:5:zh":"(object)","grammar:122:ex4:words:5:pos":"particle","grammar:122:ex4:words:6:zh":"worry","grammar:122:ex4:words:6:note":"しんぱいし","grammar:122:ex4:words:6:pos":"verb","grammar:122:ex4:words:7:zh":"(links to the progressive expression that follows)","grammar:122:ex4:words:7:pos":"particle","grammar:122:ex4:words:8:zh":"(the worry continues)","grammar:122:ex4:words:8:pos":"verb","grammar:122:ex4:words:9:zh":"(polite tone)","grammar:122:ex4:words:9:pos":"auxiliary verb","grammar:122:ex4:points:0":"「明日のテスト」 uses 「の」 to attach the time noun to the exam, meaning tomorrow's exam.","grammar:122:ex4:points:1":"「〜のこと」 frames the scope of the worry as the situation surrounding that matter.","grammar:122:ex5:trans":"He seems to be worried.","grammar:122:ex5:structure":"verb in the plain form＋ようです","grammar:122:ex5:explain":"「心配している」 describes the ongoing state of being worried, and 「ようです」 shows that the speaker is inferring that state. This way of speaking suits describing a third person's inner feelings, since the speaker can usually judge only from expressions, behavior, or information. Here 「よう」 means 'seems', not a simile.","grammar:122:ex5:words:0:zh":"he","grammar:122:ex5:words:0:note":"かれ","grammar:122:ex5:words:0:pos":"pronoun","grammar:122:ex5:words:1:zh":"(topic)","grammar:122:ex5:words:1:pos":"particle","grammar:122:ex5:words:2:zh":"worry","grammar:122:ex5:words:2:note":"しんぱいし","grammar:122:ex5:words:2:pos":"verb","grammar:122:ex5:words:3:zh":"(links to the progressive expression that follows)","grammar:122:ex5:words:3:pos":"particle","grammar:122:ex5:words:4:zh":"(the worry continues)","grammar:122:ex5:words:4:pos":"verb","grammar:122:ex5:words:5:zh":"seems, apparently","grammar:122:ex5:words:5:pos":"auxiliary verb","grammar:122:ex5:words:6:zh":"(polite statement)","grammar:122:ex5:words:6:pos":"auxiliary verb","grammar:122:ex5:points:0":"「〜ようです」 expresses an inference based on observation or information.","grammar:122:ex5:points:1":"「心配している」 stays in its plain form and then takes 「ようです」."},"123":{"example:123:exzh":"He always gets up early.","example:123:exzh2":"Please come early.","example:123:exzh3":"The cherry blossoms bloomed early this year.","example:123:exzh4":"Let's set off early.","example:123:exzh5":"Early to bed and early to rise is good for your health.","grammar:123:ex:trans":"He always gets up early.","grammar:123:ex:structure":"いつも早く起きます","grammar:123:ex:explain":"This sentence practices the adverbial form of i-adjectives. 「早い（はやい）」 is an i-adjective meaning early (in time); to modify a verb, change the final 「い」 to 「く」 to make the adverb 「早く」, so 「早く起きる」 = 'to get up early'. The adverb 「いつも」 means 'always'. The verb 「起きる」 is an ichidan (ru-) verb, and its polite form is 「起きます」. The whole sentence 「彼はいつも早く起きます」 = 'he always gets up early'. The key point is the i-adjective → adverb rule 「い→く」.","grammar:123:ex:words:0:zh":"he","grammar:123:ex:words:0:note":"かれ","grammar:123:ex:words:0:pos":"pronoun","grammar:123:ex:words:1:zh":"(topic)","grammar:123:ex:words:1:pos":"particle","grammar:123:ex:words:2:zh":"always","grammar:123:ex:words:2:pos":"adverb","grammar:123:ex:words:3:zh":"early (as an adverb)","grammar:123:ex:words:3:note":"はやく","grammar:123:ex:words:3:pos":"adverb","grammar:123:ex:words:4:zh":"to get up","grammar:123:ex:words:4:note":"おきます","grammar:123:ex:words:4:pos":"verb","grammar:123:ex:points:0":"❗早い（はやい）: early (in time); 早く is the adverbial form.","grammar:123:ex:points:1":"早く起きる: to get up early.","grammar:123:ex2:trans":"Please come early.","grammar:123:ex2:structure":"早く来てください","grammar:123:ex2:words:0:zh":"early (as an adverb)","grammar:123:ex2:words:0:note":"はやく","grammar:123:ex2:words:0:pos":"adverb","grammar:123:ex2:words:1:zh":"come","grammar:123:ex2:words:1:note":"きて","grammar:123:ex2:words:1:pos":"verb","grammar:123:ex2:words:2:zh":"please","grammar:123:ex2:words:2:pos":"auxiliary verb","grammar:123:ex2:points:0":"❗早く: early, quickly (早い→早く).","grammar:123:ex2:points:1":"早く来て: come early.","grammar:123:ex3:trans":"The cherry blossoms bloomed early this year.","grammar:123:ex3:structure":"早く〜が咲いた","grammar:123:ex3:words:0:zh":"this year","grammar:123:ex3:words:0:note":"ことし","grammar:123:ex3:words:0:pos":"noun","grammar:123:ex3:words:1:zh":"(topic)","grammar:123:ex3:words:1:pos":"particle","grammar:123:ex3:words:2:zh":"early (as an adverb)","grammar:123:ex3:words:2:note":"はやく","grammar:123:ex3:words:2:pos":"adverb","grammar:123:ex3:words:3:zh":"cherry blossoms","grammar:123:ex3:words:3:note":"さくら","grammar:123:ex3:words:3:pos":"noun","grammar:123:ex3:words:4:zh":"(nominative)","grammar:123:ex3:words:4:pos":"particle","grammar:123:ex3:words:5:zh":"bloomed","grammar:123:ex3:words:5:note":"さいた","grammar:123:ex3:words:5:pos":"verb","grammar:123:ex3:points:0":"桜が咲く: the cherry blossoms bloom.","grammar:123:ex3:points:1":"早く咲いた: bloomed early.","grammar:123:ex4:trans":"Let's set off early.","grammar:123:ex4:structure":"早い時間に〜しましょう","grammar:123:ex4:words:0:zh":"early","grammar:123:ex4:words:0:note":"はやい","grammar:123:ex4:words:0:pos":"adjective","grammar:123:ex4:words:1:zh":"time","grammar:123:ex4:words:1:note":"じかん","grammar:123:ex4:words:1:pos":"noun","grammar:123:ex4:words:2:zh":"(point in time)","grammar:123:ex4:words:2:pos":"particle","grammar:123:ex4:words:3:zh":"let's set off","grammar:123:ex4:words:3:note":"しゅっぱつしましょう","grammar:123:ex4:words:3:pos":"verb","grammar:123:ex4:points:0":"❗早い時間: an early time (attributive: 早い + noun).","grammar:123:ex4:points:1":"出発する: to set off, to depart.","grammar:123:ex5:trans":"Early to bed and early to rise is good for your health.","grammar:123:ex5:structure":"〜は〜に良い","grammar:123:ex5:words:0:zh":"early to bed and early to rise","grammar:123:ex5:words:0:note":"はやねはやおき","grammar:123:ex5:words:0:pos":"noun","grammar:123:ex5:words:1:zh":"(topic)","grammar:123:ex5:words:1:pos":"particle","grammar:123:ex5:words:2:zh":"health","grammar:123:ex5:words:2:note":"けんこう","grammar:123:ex5:words:2:pos":"noun","grammar:123:ex5:words:3:zh":"(object)","grammar:123:ex5:words:3:pos":"particle","grammar:123:ex5:words:4:zh":"good","grammar:123:ex5:words:4:note":"いい","grammar:123:ex5:words:4:pos":"adjective","grammar:123:ex5:points:0":"❗早寝早起き: early to bed and early to rise (a fixed four-character idiom).","grammar:123:ex5:points:1":"〜に良い: good for ...","exam:123:zh":"We'd agreed on ten o'clock, but I got there at nine, so my friend said to me, \"You're early.\"","exam:123:why":"Arriving earlier than the agreed time is 「早い」. 「遅い」 means late, the opposite of nine o'clock being earlier than ten."},"127":{"example:127:exzh":"That won't do.","example:127:exzh2":"We were planning to go out today, but it fell through.","example:127:exzh3":"There are many reasons why it won't work.","example:127:exzh4":"There are also things that are not allowed here.","example:127:exzh5":"When someone tells me it's no good, I get a strong feeling.","grammar:127:ex:trans":"That is no good.","grammar:127:ex:structure":"〜はダメです","grammar:127:ex:explain":"This sentence uses 「〜はダメです」 to express a negative judgment or prohibition. 「ダメ」 is a na-adjective meaning no good, not allowed, or useless, often used to refuse or stop someone. 「それはダメです」 makes that the topic and attaches 「です」 directly to the predicate. The whole sentence 「それはダメです」 means that is not okay. 「ダメ」 is extremely common in casual speech and can stand alone for a strong prohibition; before a noun it takes な (ダメな人 = a useless person). The tone is direct, with a clear negative.","grammar:127:ex:words:0:zh":"that","grammar:127:ex:words:0:pos":"pronoun","grammar:127:ex:words:1:zh":"(topic)","grammar:127:ex:words:1:pos":"particle","grammar:127:ex:words:2:zh":"no good","grammar:127:ex:words:2:pos":"na-adjective","grammar:127:ex:words:3:zh":"(polite form)","grammar:127:ex:words:3:pos":"copula","grammar:127:ex:points:0":"ダメ: no good, not allowed (na-adjective).","grammar:127:ex:points:1":"それはダメです: that is not okay.","grammar:127:ex2:trans":"I was planning to go out today, but it fell through.","grammar:127:ex2:structure":"〜予定でしたが、ダメになりました","grammar:127:ex2:words:0:zh":"today","grammar:127:ex2:words:0:note":"きょう","grammar:127:ex2:words:0:pos":"noun","grammar:127:ex2:words:1:zh":"(topic)","grammar:127:ex2:words:1:pos":"particle","grammar:127:ex2:words:2:zh":"hang out","grammar:127:ex2:words:2:note":"あそび","grammar:127:ex2:words:2:pos":"noun","grammar:127:ex2:words:3:zh":"(purpose)","grammar:127:ex2:words:3:pos":"particle","grammar:127:ex2:words:4:zh":"go","grammar:127:ex2:words:4:note":"いく","grammar:127:ex2:words:4:pos":"verb","grammar:127:ex2:words:5:zh":"plan","grammar:127:ex2:words:5:note":"よてい","grammar:127:ex2:words:5:pos":"noun","grammar:127:ex2:words:6:zh":"(past) was","grammar:127:ex2:words:6:pos":"copula","grammar:127:ex2:words:7:zh":"but","grammar:127:ex2:words:7:pos":"particle","grammar:127:ex2:words:8:zh":"no good","grammar:127:ex2:words:8:pos":"na-adjective","grammar:127:ex2:words:9:zh":"became","grammar:127:ex2:words:9:pos":"verb","grammar:127:ex2:points:0":"〜が: but (contrast).","grammar:127:ex2:points:1":"ダメになる: to become no good, to fall through (に＋なる).","grammar:127:ex3:trans":"There are many reasons why something falls through.","grammar:127:ex3:structure":"ダメになる〜がたくさんあります","grammar:127:ex3:words:0:zh":"no good","grammar:127:ex3:words:0:pos":"na-adjective","grammar:127:ex3:words:1:zh":"become","grammar:127:ex3:words:1:pos":"verb","grammar:127:ex3:words:2:zh":"reason","grammar:127:ex3:words:2:note":"りゆう","grammar:127:ex3:words:2:pos":"noun","grammar:127:ex3:words:3:zh":"(topic)","grammar:127:ex3:words:3:pos":"particle","grammar:127:ex3:words:4:zh":"a lot","grammar:127:ex3:words:4:pos":"adverb","grammar:127:ex3:words:5:zh":"there is / are","grammar:127:ex3:words:5:pos":"verb","grammar:127:ex3:points:0":"ダメになる: to fall through, to fail (the verb modifies 理由).","grammar:127:ex3:points:1":"〜がたくさんあります: there are many ….","grammar:127:ex4:trans":"Here there are also things that are not allowed.","grammar:127:ex4:structure":"〜ではダメなこともあります","grammar:127:ex4:words:0:zh":"here","grammar:127:ex4:words:0:pos":"pronoun","grammar:127:ex4:words:1:zh":"(place)","grammar:127:ex4:words:1:pos":"particle","grammar:127:ex4:words:2:zh":"(contrast)","grammar:127:ex4:words:2:pos":"particle","grammar:127:ex4:words:3:zh":"no good","grammar:127:ex4:words:3:pos":"na-adjective","grammar:127:ex4:words:4:zh":"(attributive form)","grammar:127:ex4:words:4:pos":"auxiliary verb","grammar:127:ex4:words:5:zh":"thing / matter","grammar:127:ex4:words:5:pos":"noun","grammar:127:ex4:words:6:zh":"also, too","grammar:127:ex4:words:6:pos":"particle","grammar:127:ex4:words:7:zh":"there is / are","grammar:127:ex4:words:7:pos":"verb","grammar:127:ex4:points:0":"ダメなこと: something that is not allowed (な＋noun).","grammar:127:ex4:points:1":"こともあります: there are also cases where ….","grammar:127:ex5:trans":"When someone tells me it is no good, I get strong feelings.","grammar:127:ex5:structure":"〜と言われると、〜になります","grammar:127:ex5:words:0:zh":"no good","grammar:127:ex5:words:0:pos":"na-adjective","grammar:127:ex5:words:1:zh":"is","grammar:127:ex5:words:1:pos":"copula","grammar:127:ex5:words:2:zh":"(quotation)","grammar:127:ex5:words:2:pos":"particle","grammar:127:ex5:words:3:zh":"is said","grammar:127:ex5:words:3:note":"いわれる","grammar:127:ex5:words:3:pos":"verb","grammar:127:ex5:words:4:zh":"(condition)","grammar:127:ex5:words:4:pos":"particle","grammar:127:ex5:words:5:zh":"strong","grammar:127:ex5:words:5:note":"つよい","grammar:127:ex5:words:5:pos":"adjective","grammar:127:ex5:words:6:zh":"feelings","grammar:127:ex5:words:6:note":"きもち","grammar:127:ex5:words:6:pos":"noun","grammar:127:ex5:words:7:zh":"(result)","grammar:127:ex5:words:7:pos":"particle","grammar:127:ex5:words:8:zh":"become","grammar:127:ex5:words:8:pos":"verb","grammar:127:ex5:points:0":"〜と言われると: once someone says … to you, then … (passive form + conditional と).","grammar:127:ex5:points:1":"〜になります: to become … (に＋なる)."},"128":{"example:128:exzh":"Dad went to work.","example:128:exzh2":"Today is Dad's birthday.","example:128:exzh3":"She is playing with Dad.","example:128:exzh4":"Dad is very kind.","example:128:exzh5":"My dad is a good cook.","grammar:128:ex:trans":"Dad went off to work.","grammar:128:ex:structure":"〜に行きました","grammar:128:ex:explain":"This sentence uses 「〜に行きました」 to say that someone went to do something. 「パパ」 is the casual, childlike word for 'dad' and sounds affectionate. In 「仕事に行く」, 「に」 marks the purpose of the action, 'to go to work.' The past polite form of the verb 「行く」 is 「行きました」. The whole sentence 「パパは仕事に行きました」 means 'Dad went out to work.' Here 「に」 marks purpose (going in order to do something), which feels close to the 「に」 that marks the endpoint of movement; both point out the direction or the purpose of going.","grammar:128:ex:words:0:zh":"dad","grammar:128:ex:words:0:pos":"noun","grammar:128:ex:words:1:zh":"(topic)","grammar:128:ex:words:1:pos":"particle","grammar:128:ex:words:2:zh":"work","grammar:128:ex:words:2:note":"しごと","grammar:128:ex:words:2:pos":"noun","grammar:128:ex:words:3:zh":"(purpose)","grammar:128:ex:words:3:pos":"particle","grammar:128:ex:words:4:zh":"went","grammar:128:ex:words:4:note":"いきました","grammar:128:ex:words:4:pos":"verb","grammar:128:ex:points:0":"「パパ」: dad (casual / childlike).","grammar:128:ex:points:1":"「仕事に行く」: to go to work.","grammar:128:ex2:trans":"Today is Dad's birthday.","grammar:128:ex2:structure":"〜はパパの〜です","grammar:128:ex2:words:0:zh":"today","grammar:128:ex2:words:0:note":"きょう","grammar:128:ex2:words:0:pos":"noun","grammar:128:ex2:words:1:zh":"(topic)","grammar:128:ex2:words:1:pos":"particle","grammar:128:ex2:words:2:zh":"dad","grammar:128:ex2:words:2:pos":"noun","grammar:128:ex2:words:3:zh":"'s","grammar:128:ex2:words:3:pos":"particle","grammar:128:ex2:words:4:zh":"birthday","grammar:128:ex2:words:4:note":"たんじょうび","grammar:128:ex2:words:4:pos":"noun","grammar:128:ex2:words:5:zh":"is","grammar:128:ex2:words:5:pos":"copula","grammar:128:ex2:points:0":"「パパの誕生日」: Dad's birthday.","grammar:128:ex2:points:1":"「誕生日」: birthday.","grammar:128:ex3:trans":"She is playing with Dad.","grammar:128:ex3:structure":"〜と一緒に遊んでいます","grammar:128:ex3:words:0:zh":"she","grammar:128:ex3:words:0:note":"かのじょ","grammar:128:ex3:words:0:pos":"pronoun","grammar:128:ex3:words:1:zh":"(topic)","grammar:128:ex3:words:1:pos":"particle","grammar:128:ex3:words:2:zh":"dad","grammar:128:ex3:words:2:pos":"noun","grammar:128:ex3:words:3:zh":"with","grammar:128:ex3:words:3:pos":"particle","grammar:128:ex3:words:4:zh":"together","grammar:128:ex3:words:4:note":"いっしょに","grammar:128:ex3:words:4:pos":"adverb","grammar:128:ex3:words:5:zh":"playing","grammar:128:ex3:words:5:note":"あそんでいます","grammar:128:ex3:words:5:pos":"verb","grammar:128:ex3:points:0":"〜と一緒に: together with…","grammar:128:ex3:points:1":"〜ている: ongoing action.","grammar:128:ex4:trans":"Dad is kind.","grammar:128:ex4:structure":"パパは〜です","grammar:128:ex4:words:0:zh":"dad","grammar:128:ex4:words:0:pos":"noun","grammar:128:ex4:words:1:zh":"(topic)","grammar:128:ex4:words:1:pos":"particle","grammar:128:ex4:words:2:zh":"kind","grammar:128:ex4:words:2:note":"やさしい","grammar:128:ex4:words:2:pos":"adjective","grammar:128:ex4:words:3:zh":"(polite form)","grammar:128:ex4:words:3:pos":"copula","grammar:128:ex4:points:0":"優しい: kind (i-adjective).","grammar:128:ex4:points:1":"パパは優しい。","grammar:128:ex5:trans":"My dad is a good cook.","grammar:128:ex5:structure":"〜は〜が上手です","grammar:128:ex5:words:0:zh":"I","grammar:128:ex5:words:0:note":"わたし","grammar:128:ex5:words:0:pos":"pronoun","grammar:128:ex5:words:1:zh":"'s","grammar:128:ex5:words:1:pos":"particle","grammar:128:ex5:words:2:zh":"dad","grammar:128:ex5:words:2:pos":"noun","grammar:128:ex5:words:3:zh":"(topic)","grammar:128:ex5:words:3:pos":"particle","grammar:128:ex5:words:4:zh":"cooking","grammar:128:ex5:words:4:note":"りょうり","grammar:128:ex5:words:4:pos":"noun","grammar:128:ex5:words:5:zh":"(object)","grammar:128:ex5:words:5:pos":"particle","grammar:128:ex5:words:6:zh":"good at","grammar:128:ex5:words:6:note":"じょうず","grammar:128:ex5:words:6:pos":"na-adjective","grammar:128:ex5:words:7:zh":"(polite form)","grammar:128:ex5:words:7:pos":"copula","grammar:128:ex5:points:0":"The object of 「上手」 takes が (料理が上手).","grammar:128:ex5:points:1":"「私のパパ」: my dad.","exam:128:zh":"My little daughter calls her mother 「ママ」 and her father 「パパ」.","exam:128:why":"「パパ」 is a small child's affectionate word for dad. 「おじいちゃん」 means grandpa, on either the father's or the mother's side, not dad."},"130":{"example:130:exzh":"The book is on the table.","example:130:exzh2":"A bird is flying in the sky.","example:130:exzh3":"He waved to a friend up above.","example:130:exzh4":"There's a library on the floor above.","example:130:exzh5":"If you look up, you can see the stars.","grammar:130:ex:trans":"The book is on the table.","grammar:130:ex:structure":"noun は + 〔名詞の上〕 + に + あります. 「の上」 shows relative position, and 「に＋ある」 shows existing in a place.","grammar:130:ex:explain":"This sentence combines a position noun with an existence sentence. In 「テーブルの上」, 「の」 links the position noun 「上」 (うえ) to make on top of the table, and 「に」 marks the place where something exists. The verb 「ある」 expresses the existence of inanimate things, so 「本は⋯にあります」 = the book is at …. The topic particle 「は」 raises 「本」 as the topic. The whole sentence 「本はテーブルの上にあります」 = The book is on the table. Position noun (上・下・中・前) + の + に + ある/いる is the basic structure of existence sentences.","grammar:130:ex:words:0:zh":"book","grammar:130:ex:words:0:note":"ほん","grammar:130:ex:words:0:pos":"noun","grammar:130:ex:words:1:zh":"(topic marker)","grammar:130:ex:words:1:pos":"particle","grammar:130:ex:words:2:zh":"desk","grammar:130:ex:words:2:note":"loanword (table)","grammar:130:ex:words:2:pos":"noun","grammar:130:ex:words:3:zh":"'s","grammar:130:ex:words:3:pos":"particle","grammar:130:ex:words:4:zh":"on top of","grammar:130:ex:words:4:note":"うえ; a position noun","grammar:130:ex:words:4:pos":"noun","grammar:130:ex:words:5:zh":"(the place where something exists)","grammar:130:ex:words:5:pos":"particle","grammar:130:ex:words:6:zh":"there is / to be","grammar:130:ex:words:6:note":"existence of inanimate things","grammar:130:ex:words:6:pos":"verb","grammar:130:ex:points:0":"noun + の + 上: on top of … (position noun)","grammar:130:ex:points:1":"place に 〜がある / はある: existence pattern","grammar:130:ex2:trans":"Birds are flying in the sky.","grammar:130:ex2:structure":"noun が + 〔place〕 + を + motion verb-ています. The space that movement passes through takes 「を」, and 「〜ている」 shows an action in progress.","grammar:130:ex2:words:0:zh":"bird","grammar:130:ex2:words:0:note":"とり","grammar:130:ex2:words:0:pos":"noun","grammar:130:ex2:words:1:zh":"(nominative)","grammar:130:ex2:words:1:pos":"particle","grammar:130:ex2:words:2:zh":"sky","grammar:130:ex2:words:2:note":"そら","grammar:130:ex2:words:2:pos":"noun","grammar:130:ex2:words:3:zh":"'s","grammar:130:ex2:words:3:pos":"particle","grammar:130:ex2:words:4:zh":"above; on top of","grammar:130:ex2:words:4:note":"うえ","grammar:130:ex2:words:4:pos":"noun","grammar:130:ex2:words:5:zh":"(through)","grammar:130:ex2:words:5:note":"marks the space that movement passes through","grammar:130:ex2:words:5:pos":"particle","grammar:130:ex2:words:6:zh":"is flying","grammar:130:ex2:words:6:note":"とんでいます; 〜ている shows progress","grammar:130:ex2:words:6:pos":"verb","grammar:130:ex2:points:0":"を marks the path or space that movement passes through: 空を飛ぶ","grammar:130:ex2:points:1":"飛ぶ→飛んで (te-form) + います","grammar:130:ex3:trans":"He waved to his friend above.","grammar:130:ex3:structure":"〔上にいる〕＋noun＋に＋手を振った. 「上にいる」 is a verb clause modifying 「友達」, and the person who is waved at takes に.","grammar:130:ex3:words:0:zh":"he","grammar:130:ex3:words:0:note":"かれ","grammar:130:ex3:words:0:pos":"pronoun","grammar:130:ex3:words:1:zh":"(topic marker)","grammar:130:ex3:words:1:pos":"particle","grammar:130:ex3:words:2:zh":"on top of","grammar:130:ex3:words:2:note":"うえ","grammar:130:ex3:words:2:pos":"noun","grammar:130:ex3:words:3:zh":"(the place where something exists)","grammar:130:ex3:words:3:pos":"particle","grammar:130:ex3:words:4:zh":"exist","grammar:130:ex3:words:4:note":"existence of animate things; the dictionary form modifies a noun","grammar:130:ex3:words:4:pos":"verb","grammar:130:ex3:words:5:zh":"friend","grammar:130:ex3:words:5:note":"ともだち","grammar:130:ex3:words:5:pos":"noun","grammar:130:ex3:words:6:zh":"(object)","grammar:130:ex3:words:6:note":"the person who is waved at","grammar:130:ex3:words:6:pos":"particle","grammar:130:ex3:words:7:zh":"waved","grammar:130:ex3:words:7:note":"てをふった; a set expression, ta-form past","grammar:130:ex3:words:7:pos":"verb","grammar:130:ex3:points:0":"the dictionary form of a verb modifies a noun: 上にいる友達 (the friend who is above)","grammar:130:ex3:points:1":"〜に手を振る: to wave at …","grammar:130:ex4:trans":"There is a library upstairs.","grammar:130:ex4:structure":"〔place〕＋には＋noun＋が＋あります. 「上の階」 = upstairs; this is the existence pattern.","grammar:130:ex4:words:0:zh":"on top of","grammar:130:ex4:words:0:note":"うえ","grammar:130:ex4:words:0:pos":"noun","grammar:130:ex4:words:1:zh":"'s","grammar:130:ex4:words:1:pos":"particle","grammar:130:ex4:words:2:zh":"floor","grammar:130:ex4:words:2:note":"かい","grammar:130:ex4:words:2:pos":"noun","grammar:130:ex4:words:3:zh":"(the place where something exists)","grammar:130:ex4:words:3:pos":"particle","grammar:130:ex4:words:4:zh":"(emphasis)","grammar:130:ex4:words:4:pos":"particle","grammar:130:ex4:words:5:zh":"library","grammar:130:ex4:words:5:note":"としょかん","grammar:130:ex4:words:5:pos":"noun","grammar:130:ex4:words:6:zh":"(nominative)","grammar:130:ex4:words:6:pos":"particle","grammar:130:ex4:words:7:zh":"there is / are","grammar:130:ex4:words:7:note":"existence of inanimate things","grammar:130:ex4:words:7:pos":"verb","grammar:130:ex4:points:0":"上の階: the floor above = upstairs","grammar:130:ex4:points:1":"place には 〜がある: somewhere has …","grammar:130:ex5:trans":"When you look up, you can see the stars.","grammar:130:ex5:structure":"〔verb dictionary form〕＋と、〜が見えます. 「と」 expresses the inevitable result of whenever …, then …, followed by a result that happens naturally.","grammar:130:ex5:words:0:zh":"above; on top of","grammar:130:ex5:words:0:note":"うえ","grammar:130:ex5:words:0:pos":"noun","grammar:130:ex5:words:1:zh":"(object)","grammar:130:ex5:words:1:pos":"particle","grammar:130:ex5:words:2:zh":"to look up","grammar:130:ex5:words:2:note":"みあげる; dictionary form","grammar:130:ex5:words:2:pos":"verb","grammar:130:ex5:words:3:zh":"(as soon as…)","grammar:130:ex5:words:3:note":"expresses a general condition","grammar:130:ex5:words:3:pos":"particle","grammar:130:ex5:words:4:zh":"star","grammar:130:ex5:words:4:note":"ほし","grammar:130:ex5:words:4:pos":"noun","grammar:130:ex5:words:5:zh":"(nominative)","grammar:130:ex5:words:5:pos":"particle","grammar:130:ex5:words:6:zh":"can see (is visible)","grammar:130:ex5:words:6:note":"みえます","grammar:130:ex5:words:6:pos":"verb","grammar:130:ex5:points:0":"〜と: whenever …, … (an invariable or natural result)","grammar:130:ex5:points:1":"見上げると星が見える: look up and you see the stars","exam:130:zh":"The cat got up on the table and sat next to the plate.","exam:130:why":"「テーブルの上に乗る」 means getting up onto the tabletop. 「下」 is under the table, which doesn't fit 「乗る」 or sitting beside the plate on the table."},"131":{"example:131:exzh":"What kind of books do you like?","example:131:exzh2":"What kind of cooking are you good at?","example:131:exzh3":"What kind of person is he?","example:131:exzh4":"What color do you like?","example:131:exzh5":"What kind of movie did you see?","grammar:131:ex:trans":"What kind of books do you like?","grammar:131:ex:structure":"どんな〜が好きですか","grammar:131:ex:explain":"This sentence uses the pre-noun adjectival 「どんな」 to ask about a type. 「どんな」 means 'what kind of' and can only come before a noun, so 「どんな本」 means 'what kind of books.' 「好き」 is a na-adjective, and the thing you like is marked with 「が」: 「本が好き」 means 'like books.' The final 「か」 turns it into a question. The whole sentence 「どんな本が好きですか」 means 'What kind of books do you like?' Remember that 「どんな」 is a pre-noun adjectival asking about nature or type, and it must always be followed by a noun.","grammar:131:ex:words:0:zh":"what kind of","grammar:131:ex:words:0:pos":"pre-noun adjectival","grammar:131:ex:words:1:zh":"book","grammar:131:ex:words:1:note":"ほん","grammar:131:ex:words:1:pos":"noun","grammar:131:ex:words:2:zh":"(object)","grammar:131:ex:words:2:pos":"particle","grammar:131:ex:words:3:zh":"to like","grammar:131:ex:words:3:note":"すき","grammar:131:ex:words:3:pos":"na-adjective","grammar:131:ex:words:4:zh":"(polite form)","grammar:131:ex:words:4:pos":"copula","grammar:131:ex:words:5:zh":"(question)","grammar:131:ex:words:5:pos":"particle","grammar:131:ex:points:0":"「どんな」: what kind of (pre-noun adjectival, followed by a noun).","grammar:131:ex:points:1":"The object of 「好き」 takes が.","grammar:131:ex2:trans":"What kind of cooking are you good at?","grammar:131:ex2:structure":"どんな〜が得意ですか","grammar:131:ex2:words:0:zh":"what kind of","grammar:131:ex2:words:0:pos":"pre-noun adjectival","grammar:131:ex2:words:1:zh":"dish / cuisine","grammar:131:ex2:words:1:note":"りょうり","grammar:131:ex2:words:1:pos":"noun","grammar:131:ex2:words:2:zh":"(object)","grammar:131:ex2:words:2:pos":"particle","grammar:131:ex2:words:3:zh":"good at","grammar:131:ex2:words:3:note":"とくい","grammar:131:ex2:words:3:pos":"na-adjective","grammar:131:ex2:words:4:zh":"(polite form)","grammar:131:ex2:words:4:pos":"copula","grammar:131:ex2:words:5:zh":"(question)","grammar:131:ex2:words:5:pos":"particle","grammar:131:ex2:points:0":"「どんな料理」: what kind of cooking.","grammar:131:ex2:points:1":"The object of 「得意」 takes が.","grammar:131:ex3:trans":"What kind of person is he?","grammar:131:ex3:structure":"〜はどんな人ですか","grammar:131:ex3:words:0:zh":"he","grammar:131:ex3:words:0:note":"かれ","grammar:131:ex3:words:0:pos":"pronoun","grammar:131:ex3:words:1:zh":"(topic)","grammar:131:ex3:words:1:pos":"particle","grammar:131:ex3:words:2:zh":"what kind of","grammar:131:ex3:words:2:pos":"pre-noun adjectival","grammar:131:ex3:words:3:zh":"person","grammar:131:ex3:words:3:note":"ひと","grammar:131:ex3:words:3:pos":"noun","grammar:131:ex3:words:4:zh":"is","grammar:131:ex3:words:4:pos":"copula","grammar:131:ex3:words:5:zh":"(question)","grammar:131:ex3:words:5:pos":"particle","grammar:131:ex3:points:0":"「どんな人」: what kind of person.","grammar:131:ex3:points:1":"A common way to ask about someone's personality or type.","grammar:131:ex4:trans":"What color do you like?","grammar:131:ex4:structure":"どんな色が好きですか","grammar:131:ex4:words:0:zh":"what kind of","grammar:131:ex4:words:0:pos":"pre-noun adjectival","grammar:131:ex4:words:1:zh":"color","grammar:131:ex4:words:1:note":"いろ","grammar:131:ex4:words:1:pos":"noun","grammar:131:ex4:words:2:zh":"(object)","grammar:131:ex4:words:2:pos":"particle","grammar:131:ex4:words:3:zh":"to like","grammar:131:ex4:words:3:note":"すき","grammar:131:ex4:words:3:pos":"na-adjective","grammar:131:ex4:words:4:zh":"(polite form)","grammar:131:ex4:words:4:pos":"copula","grammar:131:ex4:words:5:zh":"(question)","grammar:131:ex4:words:5:pos":"particle","grammar:131:ex4:points:0":"「色（いろ）」: color.","grammar:131:ex4:points:1":"The object of 「好き」 takes が.","grammar:131:ex5:trans":"What kind of movie did you see?","grammar:131:ex5:structure":"どんな〜を見ましたか","grammar:131:ex5:words:0:zh":"what kind of","grammar:131:ex5:words:0:pos":"pre-noun adjectival","grammar:131:ex5:words:1:zh":"movie","grammar:131:ex5:words:1:note":"えいが","grammar:131:ex5:words:1:pos":"noun","grammar:131:ex5:words:2:zh":"(object marker)","grammar:131:ex5:words:2:pos":"particle","grammar:131:ex5:words:3:zh":"watched","grammar:131:ex5:words:3:note":"みました","grammar:131:ex5:words:3:pos":"verb","grammar:131:ex5:words:4:zh":"(question)","grammar:131:ex5:words:4:pos":"particle","grammar:131:ex5:points:0":"「どんな映画」: what kind of movie.","grammar:131:ex5:points:1":"を＋見ました: saw …"},"132":{"example:132:exzh":"Let's try harder.","example:132:exzh2":"More information is needed.","example:132:exzh3":"I want to sleep more.","example:132:exzh4":"I want to make more friends.","example:132:exzh5":"More practice is needed.","grammar:132:ex:trans":"Let's try harder.","grammar:132:ex:structure":"もっと〜ましょう","grammar:132:ex:explain":"This sentence combines the adverb 「もっと」 with a volitional form. 「もっと」 means 'more' and raises the degree, suggesting more than there is now. The verb 「頑張る」 is a godan (u-) verb; to make the volitional form, the final 「る」 changes to 「り」 and 「ましょう」 is added, giving 「頑張りましょう」, which means 'let's (do it together).' The whole sentence 「もっと頑張りましょう」 means 'Let's try harder.' It is a common phrase for cheering someone on and encouraging each other, with 「もっと」 bringing out the expectation of stepping it up.","grammar:132:ex:words:0:zh":"more","grammar:132:ex:words:0:pos":"adverb","grammar:132:ex:words:1:zh":"let's do our best","grammar:132:ex:words:1:note":"がんばりましょう","grammar:132:ex:words:1:pos":"verb","grammar:132:ex:points:0":"「もっと」: more (stronger degree).","grammar:132:ex:points:1":"「頑張る」→「頑張りましょう」: proposing that we work hard together.","grammar:132:ex2:trans":"We need more information.","grammar:132:ex2:structure":"もっと〜が必要です","grammar:132:ex2:words:0:zh":"more","grammar:132:ex2:words:0:pos":"adverb","grammar:132:ex2:words:1:zh":"information","grammar:132:ex2:words:1:note":"じょうほう","grammar:132:ex2:words:1:pos":"noun","grammar:132:ex2:words:2:zh":"(object)","grammar:132:ex2:words:2:pos":"particle","grammar:132:ex2:words:3:zh":"necessary","grammar:132:ex2:words:3:note":"ひつよう","grammar:132:ex2:words:3:pos":"na-adjective","grammar:132:ex2:words:4:zh":"(polite form)","grammar:132:ex2:words:4:pos":"copula","grammar:132:ex2:points:0":"「もっと情報」: more information.","grammar:132:ex2:points:1":"「〜が必要です」: need …","grammar:132:ex3:trans":"I want to sleep more.","grammar:132:ex3:structure":"もっと〜たいです","grammar:132:ex3:words:0:zh":"more","grammar:132:ex3:words:0:pos":"adverb","grammar:132:ex3:words:1:zh":"want to sleep","grammar:132:ex3:words:1:note":"ねたい","grammar:132:ex3:words:1:pos":"verb","grammar:132:ex3:words:2:zh":"(polite form)","grammar:132:ex3:words:2:pos":"copula","grammar:132:ex3:points:0":"「寝る」→「寝たい」 (〜たい = desire).","grammar:132:ex3:points:1":"「もっと」: more.","grammar:132:ex4:trans":"I want to make more friends.","grammar:132:ex4:structure":"もっと〜を作りたい","grammar:132:ex4:words:0:zh":"more","grammar:132:ex4:words:0:pos":"adverb","grammar:132:ex4:words:1:zh":"friend","grammar:132:ex4:words:1:note":"ともだち","grammar:132:ex4:words:1:pos":"noun","grammar:132:ex4:words:2:zh":"(object marker)","grammar:132:ex4:words:2:pos":"particle","grammar:132:ex4:words:3:zh":"want to make","grammar:132:ex4:words:3:note":"つくりたい","grammar:132:ex4:words:3:pos":"verb","grammar:132:ex4:points:0":"「友達を作る」: to make friends.","grammar:132:ex4:points:1":"作る→作りたい。","grammar:132:ex5:trans":"We need more practice.","grammar:132:ex5:structure":"もっと〜が必要です","grammar:132:ex5:words:0:zh":"more","grammar:132:ex5:words:0:pos":"adverb","grammar:132:ex5:words:1:zh":"practice","grammar:132:ex5:words:1:note":"れんしゅう","grammar:132:ex5:words:1:pos":"noun","grammar:132:ex5:words:2:zh":"(object)","grammar:132:ex5:words:2:pos":"particle","grammar:132:ex5:words:3:zh":"necessary","grammar:132:ex5:words:3:note":"ひつよう","grammar:132:ex5:words:3:pos":"na-adjective","grammar:132:ex5:words:4:zh":"(polite form)","grammar:132:ex5:words:4:pos":"copula","grammar:132:ex5:points:0":"「もっと練習」: more practice.","grammar:132:ex5:points:1":"「〜が必要です」: need …","exam:132:zh":"There's still room for books in this box, so on top of the books already in it, please put in some more.","exam:132:why":"「もっと」 means more, adding to the current amount or degree. 「初めて」 means for the first time, which doesn't fit a box that already has books in it."},"133":{"example:133:exzh":"I have strength.","example:133:exzh2":"This power is important.","grammar:133:ex:trans":"I have power.","grammar:133:ex:structure":"〜は力がある","grammar:133:ex:explain":"This sentence uses 「〜は〜がある」 to describe possession. The topic 「私は」 is introduced with 「は」, and the thing possessed, 「力」, is marked with 「が」: 「力がある」 means 'have power.' This 「AはＢがある」 frame is a common way to say that someone has a certain quality or ability. The verb 「ある」 is in the plain dictionary form; the polite form is 「あります」. The whole sentence 「私は力がある」 means 'I have power.' Note that what is possessed or what exists always takes 「が」.","grammar:133:ex:words:0:zh":"I","grammar:133:ex:words:0:note":"わたし","grammar:133:ex:words:0:pos":"pronoun","grammar:133:ex:words:1:zh":"(topic)","grammar:133:ex:words:1:pos":"particle","grammar:133:ex:words:2:zh":"power","grammar:133:ex:words:2:note":"ちから","grammar:133:ex:words:2:pos":"noun","grammar:133:ex:words:3:zh":"(nominative)","grammar:133:ex:words:3:pos":"particle","grammar:133:ex:words:4:zh":"there is / are","grammar:133:ex:words:4:pos":"verb","grammar:133:ex:points:0":"❓Why が? The thing possessed (power) takes が.","grammar:133:ex:points:1":"「力（ちから）」: power.","grammar:133:ex2:trans":"This power is important.","grammar:133:ex2:structure":"この力は〜だ","grammar:133:ex2:words:0:zh":"this","grammar:133:ex2:words:0:pos":"pre-noun adjectival","grammar:133:ex2:words:1:zh":"power","grammar:133:ex2:words:1:note":"ちから","grammar:133:ex2:words:1:pos":"noun","grammar:133:ex2:words:2:zh":"(topic)","grammar:133:ex2:words:2:pos":"particle","grammar:133:ex2:words:3:zh":"important","grammar:133:ex2:words:3:note":"たいせつ","grammar:133:ex2:words:3:pos":"na-adjective","grammar:133:ex2:words:4:zh":"is (plain form)","grammar:133:ex2:words:4:pos":"copula","grammar:133:ex2:points:0":"「力」: power.","grammar:133:ex2:points:1":"「大切だ」: important (plain form of a na-adjective)."},"134":{"example:134:exzh":"Well then, let's go.","grammar:134:ex:trans":"Then let's go.","grammar:134:ex:structure":"じゃあ、〜 (volitional form)","grammar:134:ex:explain":"This sentence uses 「じゃあ」 plus the volitional form. 「じゃあ」 is the casual contraction of 「では」, meaning 'then,' and it picks up what came before to lead into a conclusion or an action. The volitional form of the verb 「行く」 is 「行こう」, which expresses the speaker's intention or a suggestion, 'let's go.' It sounds more casual than 「行きましょう」 and suits people you know well. The whole sentence 「じゃあ、行こう」 means 'Then let's go.' The volitional 「〜こう／〜よう」 is the plain-form way to invite someone or state your resolve.","grammar:134:ex:words:0:zh":"that much","grammar:134:ex:words:0:pos":"conjunction","grammar:134:ex:words:1:zh":"let's go","grammar:134:ex:words:1:note":"いこう","grammar:134:ex:words:1:pos":"verb","grammar:134:ex:points:0":"「じゃあ」: then, well then (casual form of では).","grammar:134:ex:points:1":"「行く」→「行こう」 (volitional form, 'let's go').","exam:134:zh":"My friend told me, \"The shop is closed today,\" so I replied, \"Then let's go tomorrow.\"","exam:134:why":"「じゃあ」 marks a decision based on what you just heard; here it's switching to tomorrow. 「それに」 is for adding information and doesn't naturally express this decision."},"135":{"example:135:exzh":"The police started an investigation.","example:135:exzh2":"The investigation is still ongoing."},"137":{"example:137:exzh":"I've already forgotten him.","example:137:exzh2":"Don't forget what's important.","grammar:137:ex:trans":"I've already forgotten him.","grammar:137:ex:structure":"〜を忘れてしまった","grammar:137:ex:explain":"This sentence uses 「〜てしまった」 to express regret or completion. The verb 「忘れる」 is an ichidan (ru-) verb; its te-form 「忘れて」 attaches to the past form 「しまった」 of 「しまう」, showing that the action was completed thoroughly and often carrying a tone of regret over something careless or irreversible, so 「忘れてしまった」 = '(accidentally) forgot'. 「を」 marks the object. The whole sentence 「彼を忘れてしまった」 = 'I forgot him', and in casual speech 「〜てしまう」 often contracts to 「〜ちゃう」.","grammar:137:ex:words:0:zh":"he","grammar:137:ex:words:0:note":"かれ","grammar:137:ex:words:0:pos":"pronoun","grammar:137:ex:words:1:zh":"(object marker)","grammar:137:ex:words:1:pos":"particle","grammar:137:ex:words:2:zh":"forgot","grammar:137:ex:words:2:note":"わすれて","grammar:137:ex:words:2:pos":"verb","grammar:137:ex:words:3:zh":"(regret)","grammar:137:ex:words:3:pos":"auxiliary verb","grammar:137:ex:points:0":"❗忘れる（わすれる）: to forget (transitive verb).","grammar:137:ex:points:1":"〜てしまった: (accidentally / already) ended up …ing.","grammar:137:ex2:trans":"Don't forget what's important.","grammar:137:ex2:structure":"〜を忘れないで","grammar:137:ex2:words:0:zh":"important","grammar:137:ex2:words:0:note":"じゅうよう","grammar:137:ex2:words:0:pos":"na-adjective","grammar:137:ex2:words:1:zh":"(attributive form)","grammar:137:ex2:words:1:pos":"auxiliary verb","grammar:137:ex2:words:2:zh":"thing / matter","grammar:137:ex2:words:2:pos":"noun","grammar:137:ex2:words:3:zh":"(object marker)","grammar:137:ex2:words:3:pos":"particle","grammar:137:ex2:words:4:zh":"don't forget","grammar:137:ex2:words:4:note":"わすれないで","grammar:137:ex2:words:4:pos":"verb","grammar:137:ex2:points:0":"重要なこと: something important.","grammar:137:ex2:points:1":"〜ないで: don't…","exam:137:zh":"It would be a problem if I forgot tomorrow's appointment, so I'll write it in my planner.","exam:137:why":"「忘れる」 means to forget, and writing it in a planner is exactly how you avoid forgetting. 「覚える」 means to remember, the opposite of the situation you want to avoid."},"138":{"example:138:exzh":"What does this word mean?","example:138:exzh2":"I didn't know the meaning.","grammar:138:ex:trans":"What does this word mean?","grammar:138:ex:structure":"〜の意味は何ですか","grammar:138:ex:explain":"This is the pattern for asking what something means. 「言葉の意味」 joins two nouns with 「の」: 「言葉」 is 'word' and 「意味」 is 'meaning,' so together they mean 'the meaning of the word.' 「は」 makes 「この言葉の意味」 the topic, and the sentence ends with 「何ですか」 (read なんですか), asking 'what is it?' The whole sentence 「この言葉の意味は何ですか」 means 'What does this word mean?' This is the most practical sentence when learning a language; with 「〜の意味は何ですか」 you can ask the meaning of any word.","grammar:138:ex:words:0:zh":"this","grammar:138:ex:words:0:pos":"pre-noun adjectival","grammar:138:ex:words:1:zh":"word","grammar:138:ex:words:1:note":"ことば","grammar:138:ex:words:1:pos":"noun","grammar:138:ex:words:2:zh":"'s","grammar:138:ex:words:2:pos":"particle","grammar:138:ex:words:3:zh":"meaning","grammar:138:ex:words:3:note":"いみ","grammar:138:ex:words:3:pos":"noun","grammar:138:ex:words:4:zh":"(topic)","grammar:138:ex:words:4:pos":"particle","grammar:138:ex:words:5:zh":"what","grammar:138:ex:words:5:note":"なに","grammar:138:ex:words:5:pos":"question word","grammar:138:ex:words:6:zh":"is","grammar:138:ex:words:6:pos":"copula","grammar:138:ex:words:7:zh":"(question)","grammar:138:ex:words:7:pos":"particle","grammar:138:ex:points:0":"「言葉の意味」: the meaning of the word.","grammar:138:ex:points:1":"何ですか: asks what something is.","grammar:138:ex2:trans":"I didn't know the meaning.","grammar:138:ex2:structure":"〜を知らなかった","grammar:138:ex2:words:0:zh":"meaning","grammar:138:ex2:words:0:note":"いみ","grammar:138:ex2:words:0:pos":"noun","grammar:138:ex2:words:1:zh":"(object marker)","grammar:138:ex2:words:1:pos":"particle","grammar:138:ex2:words:2:zh":"(past) didn't know","grammar:138:ex2:words:2:note":"しらなかった","grammar:138:ex2:words:2:pos":"verb","grammar:138:ex2:points:0":"「知る」→「知らなかった」 (plain past negative).","grammar:138:ex2:points:1":"を＋知る: to know …","exam:138:zh":"I can read this word, but I don't know what it means, so I'll look up the meaning in a dictionary.","exam:138:why":"When you don't know what a word means, you look up its 「意味」. 「値段」 is price, which doesn't answer the question of what a word means."},"139":{"example:139:exzh":"I want to go, but it's raining.","grammar:139:ex:trans":"I want to go, but it's raining.","grammar:139:ex:structure":"〜、しかし〜","grammar:139:ex:explain":"This sentence uses the contrastive conjunction 「しかし」. 「しかし」 means 'but' or 'however' and connects two clauses with opposite meanings; it is more formal and more written in style than the casual 「でも」. The first clause 「行きたい」 ('I want to go') and the second 「雨が降っている」 ('it is raining') set up a contrast. In 「雨が降る」, 「が」 marks what is falling, and 「降っている」 uses 「ている」 to show an ongoing state. The whole sentence means 'I want to go, but it's raining,' with 「しかし」 highlighting the conflict between the two facts.","grammar:139:ex:words:0:zh":"want to go","grammar:139:ex:words:0:note":"いきたい","grammar:139:ex:words:0:pos":"verb","grammar:139:ex:words:1:zh":"but","grammar:139:ex:words:1:pos":"conjunction","grammar:139:ex:words:2:zh":"rain","grammar:139:ex:words:2:note":"あめ","grammar:139:ex:words:2:pos":"noun","grammar:139:ex:words:3:zh":"(nominative)","grammar:139:ex:words:3:pos":"particle","grammar:139:ex:words:4:zh":"is falling","grammar:139:ex:words:4:note":"ふっている","grammar:139:ex:words:4:pos":"verb","grammar:139:ex:points:0":"「しかし」: but (written / formal contrast, more formal than でも).","grammar:139:ex:points:1":"「雨が降る」: to rain (the subject takes が)."},"140":{"example:140:exzh":"This is the last chance.","example:140:exzh2":"I'll keep going to the very end.","grammar:140:ex:trans":"This is the last chance.","grammar:140:ex:structure":"最後の〜です","grammar:140:ex:explain":"This is an identifying sentence with a possessive. 「最後（さいご）」 means 'last,' and 「最後のチャンス」 links it with 「の」 to mean 'the last chance.' 「これは⋯です」 is the frame for a noun identifying sentence (here 「これは」 is left out), and the predicate 「最後のチャンスです」 uses 「です」 for a polite statement. The whole sentence 「最後のチャンスです」 means 'This is the last chance.' Here 「の」 links 「最後」 and 'chance' in a modifying relationship, the basic way to attach one noun to another.","grammar:140:ex:words:0:zh":"last","grammar:140:ex:words:0:note":"さいご","grammar:140:ex:words:0:pos":"noun","grammar:140:ex:words:1:zh":"'s","grammar:140:ex:words:1:pos":"particle","grammar:140:ex:words:2:zh":"chance","grammar:140:ex:words:2:note":"loanword","grammar:140:ex:words:2:pos":"noun","grammar:140:ex:words:3:zh":"is","grammar:140:ex:words:3:pos":"copula","grammar:140:ex:points:0":"「最後（さいご）」: last.","grammar:140:ex:points:1":"「最後のチャンス」: the last chance.","grammar:140:ex2:trans":"Keep at it to the very end.","grammar:140:ex2:structure":"〜まで頑張る","grammar:140:ex2:words:0:zh":"last","grammar:140:ex2:words:0:note":"さいご","grammar:140:ex2:words:0:pos":"noun","grammar:140:ex2:words:1:zh":"until","grammar:140:ex2:words:1:pos":"particle","grammar:140:ex2:words:2:zh":"effort","grammar:140:ex2:words:2:note":"がんばる","grammar:140:ex2:words:2:pos":"verb","grammar:140:ex2:points:0":"「〜まで」: until … (the endpoint of a range).","grammar:140:ex2:points:1":"「頑張る」: to work hard, to do your best."},"141":{"example:141:exzh":"My wish is for him to succeed.","example:141:exzh2":"I hope your wish comes true.","example:141:exzh3":"I wished upon a star with all my heart.","example:141:exzh4":"Her wish was for peace.","example:141:exzh5":"I'll work hard to make my wish come true.","grammar:141:ex:trans":"My wish is that he succeeds.","grammar:141:ex:structure":"〜の願いは〜の成功です","grammar:141:ex:explain":"「私の願い」 is the topic of the sentence, and 「彼の成功」 explains the content of the wish. Both instances of 「の」 link nouns, one showing my wish and the other his success. The Japanese sentence uses the noun 「成功」, which is naturally rendered as 'that he succeeds'; that 'succeeds' does not correspond to a separate Japanese potential form.","grammar:141:ex:words:0:zh":"I","grammar:141:ex:words:0:note":"わたし","grammar:141:ex:words:0:pos":"pronoun","grammar:141:ex:words:1:zh":"(possession)","grammar:141:ex:words:1:pos":"particle","grammar:141:ex:words:2:zh":"wish","grammar:141:ex:words:2:note":"ねがい","grammar:141:ex:words:2:pos":"noun","grammar:141:ex:words:3:zh":"(topic)","grammar:141:ex:words:3:pos":"particle","grammar:141:ex:words:4:zh":"he","grammar:141:ex:words:4:note":"かれ","grammar:141:ex:words:4:pos":"pronoun","grammar:141:ex:words:5:zh":"(the person the success belongs to)","grammar:141:ex:words:5:pos":"particle","grammar:141:ex:words:6:zh":"success","grammar:141:ex:words:6:note":"せいこう","grammar:141:ex:words:6:pos":"noun","grammar:141:ex:words:7:zh":"is (polite statement)","grammar:141:ex:words:7:pos":"auxiliary verb","grammar:141:ex:points:0":"「願い」 is a noun meaning 'wish'; the corresponding verb is 「願う」.","grammar:141:ex:points:1":"「AはBです」 can be used to state the specific content of a wish.","grammar:141:ex2:trans":"I hope your wish comes true.","grammar:141:ex2:structure":"〜といいですね","grammar:141:ex2:words:0:zh":"wish","grammar:141:ex2:words:0:note":"ねがいごと","grammar:141:ex2:words:0:pos":"noun","grammar:141:ex2:words:1:zh":"(nominative)","grammar:141:ex2:words:1:pos":"particle","grammar:141:ex2:words:2:zh":"come true","grammar:141:ex2:words:2:note":"かなう","grammar:141:ex2:words:2:pos":"verb","grammar:141:ex2:words:3:zh":"(condition)","grammar:141:ex2:words:3:pos":"particle","grammar:141:ex2:words:4:zh":"good","grammar:141:ex2:words:4:pos":"adjective","grammar:141:ex2:words:5:zh":"(polite form)","grammar:141:ex2:words:5:pos":"copula","grammar:141:ex2:words:6:zh":"right?","grammar:141:ex2:words:6:pos":"particle","grammar:141:ex2:points:0":"「〜といいですね」: I hope … (a wish).","grammar:141:ex2:points:1":"「叶う」: (a wish) comes true (intransitive verb; the subject takes が).","grammar:141:ex3:trans":"Made a wish on a star, pouring that wish into it.","grammar:141:ex3:structure":"〜を込めて〜に願いをかけた","grammar:141:ex3:words:0:zh":"wish","grammar:141:ex3:words:0:note":"ねがい","grammar:141:ex3:words:0:pos":"noun","grammar:141:ex3:words:1:zh":"(object marker)","grammar:141:ex3:words:1:pos":"particle","grammar:141:ex3:words:2:zh":"pouring in","grammar:141:ex3:words:2:note":"こめて","grammar:141:ex3:words:2:pos":"verb","grammar:141:ex3:words:3:zh":"star","grammar:141:ex3:words:3:note":"ほし","grammar:141:ex3:words:3:pos":"noun","grammar:141:ex3:words:4:zh":"(object)","grammar:141:ex3:words:4:pos":"particle","grammar:141:ex3:words:5:zh":"wish","grammar:141:ex3:words:5:note":"ねがい","grammar:141:ex3:words:5:pos":"noun","grammar:141:ex3:words:6:zh":"(object marker)","grammar:141:ex3:words:6:pos":"particle","grammar:141:ex3:words:7:zh":"make (a wish)","grammar:141:ex3:words:7:note":"かけた","grammar:141:ex3:words:7:pos":"verb","grammar:141:ex3:points:0":"「〜を込めて」: with … in it (込める = to pour in).","grammar:141:ex3:points:1":"「星に願いをかける」: to make a wish on a star.","grammar:141:ex4:trans":"Her wish was peace.","grammar:141:ex4:structure":"〜は〜であった","grammar:141:ex4:words:0:zh":"she","grammar:141:ex4:words:0:note":"かのじょ","grammar:141:ex4:words:0:pos":"pronoun","grammar:141:ex4:words:1:zh":"'s","grammar:141:ex4:words:1:pos":"particle","grammar:141:ex4:words:2:zh":"wish","grammar:141:ex4:words:2:note":"ねがい","grammar:141:ex4:words:2:pos":"noun","grammar:141:ex4:words:3:zh":"(topic)","grammar:141:ex4:words:3:pos":"particle","grammar:141:ex4:words:4:zh":"peace","grammar:141:ex4:words:4:note":"へいわ","grammar:141:ex4:words:4:pos":"noun","grammar:141:ex4:words:5:zh":"(past) was","grammar:141:ex4:words:5:pos":"copula","grammar:141:ex4:points:0":"「彼女の願い」: her wish.","grammar:141:ex4:points:1":"「であった」: (written style) past statement 'was' (= でした).","grammar:141:ex5:trans":"Work hard to make the wish come true.","grammar:141:ex5:structure":"〜を叶えるために〜する","grammar:141:ex5:words:0:zh":"wish","grammar:141:ex5:words:0:note":"ねがい","grammar:141:ex5:words:0:pos":"noun","grammar:141:ex5:words:1:zh":"(object marker)","grammar:141:ex5:words:1:pos":"particle","grammar:141:ex5:words:2:zh":"come true","grammar:141:ex5:words:2:note":"かなえる","grammar:141:ex5:words:2:pos":"verb","grammar:141:ex5:words:3:zh":"for the sake of","grammar:141:ex5:words:3:pos":"particle","grammar:141:ex5:words:4:zh":"effort","grammar:141:ex5:words:4:note":"どりょくする","grammar:141:ex5:words:4:pos":"verb","grammar:141:ex5:points:0":"❗「叶える」 (transitive verb: to make … come true) vs 「叶う」 (intransitive verb: to come true).","grammar:141:ex5:points:1":"「〜ために」: in order to … (purpose)."},"142":{"example:142:exzh":"The weather is nice today, isn't it?","example:142:exzh2":"What's the plan for today?","example:142:exzh3":"I'm going to school today.","example:142:exzh4":"What should we make for dinner today?","example:142:exzh5":"I have plans to meet a friend today.","grammar:142:ex:trans":"The weather is nice today, isn't it?","grammar:142:ex:structure":"今日は〜ですね","grammar:142:ex:explain":"This sentence comments on the weather and invites agreement. 「今日は」 makes 'today' the topic, and 「いい天気」 is the i-adjective 「いい」 directly modifying the noun 「天気」 to mean 'nice weather.' The sentence-final 「ね」 is a particle that seeks the other person's agreement and closes the distance: 「ですね」 works like '…, isn't it?' The whole sentence 「今日はいい天気ですね」 means 'The weather is nice today, isn't it?'; it is an all-purpose everyday greeting, and 「ね」 makes the exchange interactive, inviting the other person to chime in.","grammar:142:ex:words:0:zh":"today","grammar:142:ex:words:0:note":"きょう","grammar:142:ex:words:0:pos":"noun","grammar:142:ex:words:1:zh":"(topic)","grammar:142:ex:words:1:pos":"particle","grammar:142:ex:words:2:zh":"good","grammar:142:ex:words:2:pos":"adjective","grammar:142:ex:words:3:zh":"weather","grammar:142:ex:words:3:note":"てんき","grammar:142:ex:words:3:pos":"noun","grammar:142:ex:words:4:zh":"(polite form)","grammar:142:ex:words:4:pos":"copula","grammar:142:ex:words:5:zh":"right?","grammar:142:ex:words:5:pos":"particle","grammar:142:ex:points:0":"「いい天気」: nice weather.","grammar:142:ex:points:1":"ね: seeking agreement.","grammar:142:ex2:trans":"What's the plan for today?","grammar:142:ex2:structure":"今日の〜は何ですか","grammar:142:ex2:words:0:zh":"today","grammar:142:ex2:words:0:note":"きょう","grammar:142:ex2:words:0:pos":"noun","grammar:142:ex2:words:1:zh":"'s","grammar:142:ex2:words:1:pos":"particle","grammar:142:ex2:words:2:zh":"plan","grammar:142:ex2:words:2:note":"よてい","grammar:142:ex2:words:2:pos":"noun","grammar:142:ex2:words:3:zh":"(topic)","grammar:142:ex2:words:3:pos":"particle","grammar:142:ex2:words:4:zh":"what","grammar:142:ex2:words:4:note":"なに","grammar:142:ex2:words:4:pos":"question word","grammar:142:ex2:words:5:zh":"is","grammar:142:ex2:words:5:pos":"copula","grammar:142:ex2:words:6:zh":"(question)","grammar:142:ex2:words:6:pos":"particle","grammar:142:ex2:points:0":"「今日の予定」: today's plan.","grammar:142:ex2:points:1":"何ですか: asks what something is.","grammar:142:ex3:trans":"I'm going to school today.","grammar:142:ex3:structure":"今日〜に行きます","grammar:142:ex3:words:0:zh":"I","grammar:142:ex3:words:0:note":"わたし","grammar:142:ex3:words:0:pos":"pronoun","grammar:142:ex3:words:1:zh":"(topic)","grammar:142:ex3:words:1:pos":"particle","grammar:142:ex3:words:2:zh":"today","grammar:142:ex3:words:2:note":"きょう","grammar:142:ex3:words:2:pos":"noun","grammar:142:ex3:words:3:zh":"school","grammar:142:ex3:words:3:note":"がっこう","grammar:142:ex3:words:3:pos":"noun","grammar:142:ex3:words:4:zh":"(destination)","grammar:142:ex3:words:4:pos":"particle","grammar:142:ex3:words:5:zh":"go","grammar:142:ex3:words:5:pos":"verb","grammar:142:ex3:points:0":"「今日」: today (time words can go in the middle of a sentence).","grammar:142:ex3:points:1":"「学校に行く」: to go to school.","grammar:142:ex4:trans":"What are we making for dinner today?","grammar:142:ex4:structure":"〜は何を作りますか","grammar:142:ex4:words:0:zh":"today","grammar:142:ex4:words:0:note":"きょう","grammar:142:ex4:words:0:pos":"noun","grammar:142:ex4:words:1:zh":"'s","grammar:142:ex4:words:1:pos":"particle","grammar:142:ex4:words:2:zh":"dinner","grammar:142:ex4:words:2:note":"ゆうしょく","grammar:142:ex4:words:2:pos":"noun","grammar:142:ex4:words:3:zh":"(topic)","grammar:142:ex4:words:3:pos":"particle","grammar:142:ex4:words:4:zh":"what","grammar:142:ex4:words:4:note":"なに","grammar:142:ex4:words:4:pos":"question word","grammar:142:ex4:words:5:zh":"(object marker)","grammar:142:ex4:words:5:pos":"particle","grammar:142:ex4:words:6:zh":"will make","grammar:142:ex4:words:6:note":"つくりますか","grammar:142:ex4:words:6:pos":"verb","grammar:142:ex4:points:0":"「夕食（ゆうしょく）」: dinner.","grammar:142:ex4:points:1":"「何を作る」: make what.","grammar:142:ex5:trans":"I have an appointment to meet a friend today.","grammar:142:ex5:structure":"〜と会う約束があります","grammar:142:ex5:words:0:zh":"today","grammar:142:ex5:words:0:note":"きょう","grammar:142:ex5:words:0:pos":"noun","grammar:142:ex5:words:1:zh":"(topic)","grammar:142:ex5:words:1:pos":"particle","grammar:142:ex5:words:2:zh":"friend","grammar:142:ex5:words:2:note":"ともだち","grammar:142:ex5:words:2:pos":"noun","grammar:142:ex5:words:3:zh":"with","grammar:142:ex5:words:3:pos":"particle","grammar:142:ex5:words:4:zh":"meet","grammar:142:ex5:words:4:note":"あう","grammar:142:ex5:words:4:pos":"verb","grammar:142:ex5:words:5:zh":"appointment","grammar:142:ex5:words:5:note":"やくそく","grammar:142:ex5:words:5:pos":"noun","grammar:142:ex5:words:6:zh":"(nominative)","grammar:142:ex5:words:6:pos":"particle","grammar:142:ex5:words:7:zh":"there is / are","grammar:142:ex5:words:7:pos":"verb","grammar:142:ex5:points:0":"「会う約束」: an appointment to meet (a verb modifying a noun).","grammar:142:ex5:points:1":"「〜があります」: there is … (an appointment).","exam:142:zh":"Yesterday was October 6th, so today is October 7th.","exam:142:why":"「今日」 means today, the day after yesterday. 「明日」 means tomorrow, which here would be October 8th."},"143":{"example:143:exzh":"He ran away right away.","example:143:exzh2":"When you sense danger, it's important to run away.","example:143:exzh3":"She couldn't run away from the problem.","example:143:exzh4":"Look for a way to escape work.","example:143:exzh5":"Sometimes it's necessary to run away.","grammar:143:ex:trans":"He ran away immediately.","grammar:143:ex:structure":"〜が逃げた","grammar:143:ex:explain":"This sentence uses the ta-form of the intransitive verb 「逃げる」. 「逃げる（にげる）」 means to run away or escape; it is an intransitive verb, so the one who runs away normally takes 「が」 (here 「は」 marks it as the topic). 「逃げる」 is an ichidan (ru-) verb, and the ta-form drops る and adds た to make 「逃げた」, showing past tense. The adverb 「すぐに」 means immediately. The whole sentence 「彼はすぐに逃げた」 means he ran away immediately; it's in plain form, which suits narration and casual speech.","grammar:143:ex:words:0:zh":"he","grammar:143:ex:words:0:note":"かれ","grammar:143:ex:words:0:pos":"pronoun","grammar:143:ex:words:1:zh":"(topic)","grammar:143:ex:words:1:pos":"particle","grammar:143:ex:words:2:zh":"soon","grammar:143:ex:words:2:pos":"adverb","grammar:143:ex:words:3:zh":"ran away","grammar:143:ex:words:3:note":"にげた","grammar:143:ex:words:3:pos":"verb","grammar:143:ex:points:0":"❗逃げる（にげる）: to run away, to escape (intransitive verb); すぐに逃げる = run away at once.","grammar:143:ex:points:1":"逃げる: to run away.","grammar:143:ex2:trans":"It's important to run away when you sense danger.","grammar:143:ex2:structure":"〜逃げることが大切だ","grammar:143:ex2:words:0:zh":"dangerous","grammar:143:ex2:words:0:note":"きけん","grammar:143:ex2:words:0:pos":"noun","grammar:143:ex2:words:1:zh":"(object marker)","grammar:143:ex2:words:1:pos":"particle","grammar:143:ex2:words:2:zh":"feel","grammar:143:ex2:words:2:note":"かんじて","grammar:143:ex2:words:2:pos":"verb","grammar:143:ex2:words:3:zh":"to run away","grammar:143:ex2:words:3:note":"にげる","grammar:143:ex2:words:3:pos":"verb","grammar:143:ex2:words:4:zh":"(nominalizer)","grammar:143:ex2:words:4:pos":"noun","grammar:143:ex2:words:5:zh":"(nominative)","grammar:143:ex2:words:5:pos":"particle","grammar:143:ex2:words:6:zh":"important","grammar:143:ex2:words:6:note":"たいせつ","grammar:143:ex2:words:6:pos":"na-adjective","grammar:143:ex2:words:7:zh":"is","grammar:143:ex2:words:7:pos":"copula","grammar:143:ex2:points:0":"❗危険を感じて逃げる: sense danger and run; 〜ことが大切 = it's important to …","grammar:143:ex2:points:1":"危険を感じて逃げる: run when you sense danger.","grammar:143:ex3:trans":"She couldn't escape the problem.","grammar:143:ex3:structure":"〜から逃げることができなかった","grammar:143:ex3:words:0:zh":"she","grammar:143:ex3:words:0:note":"かのじょ","grammar:143:ex3:words:0:pos":"pronoun","grammar:143:ex3:words:1:zh":"(topic)","grammar:143:ex3:words:1:pos":"particle","grammar:143:ex3:words:2:zh":"problem","grammar:143:ex3:words:2:note":"もんだい","grammar:143:ex3:words:2:pos":"noun","grammar:143:ex3:words:3:zh":"from","grammar:143:ex3:words:3:pos":"particle","grammar:143:ex3:words:4:zh":"escape","grammar:143:ex3:words:4:note":"にげる","grammar:143:ex3:words:4:pos":"verb","grammar:143:ex3:words:5:zh":"(nominalizer)","grammar:143:ex3:words:5:pos":"noun","grammar:143:ex3:words:6:zh":"(nominative)","grammar:143:ex3:words:6:pos":"particle","grammar:143:ex3:words:7:zh":"can't","grammar:143:ex3:words:7:pos":"verb","grammar:143:ex3:points:0":"❗〜から逃げる: to run away from … (から = starting point); 問題から逃げる = run away from a problem.","grammar:143:ex3:points:1":"問題から逃げる: run away from a problem.","grammar:143:ex4:trans":"Look for a way to escape work.","grammar:143:ex4:structure":"〜から逃げる方法を探す","grammar:143:ex4:explain":"The whole phrase 「仕事から逃げる」 modifies 「方法」, giving a way to escape work. 「から」 marks what you want to get away from, and 「逃げる」 is an intransitive verb. 「方法を探す」 means to look for a way, and since the sentence ends in the dictionary form, the exact tense depends on the context.","grammar:143:ex4:words:0:zh":"work","grammar:143:ex4:words:0:note":"しごと","grammar:143:ex4:words:0:pos":"noun","grammar:143:ex4:words:1:zh":"(what you are escaping from)","grammar:143:ex4:words:1:pos":"particle","grammar:143:ex4:words:2:zh":"escape","grammar:143:ex4:words:2:note":"にげる","grammar:143:ex4:words:2:pos":"verb","grammar:143:ex4:words:3:zh":"way, means","grammar:143:ex4:words:3:note":"ほうほう","grammar:143:ex4:words:3:pos":"noun","grammar:143:ex4:words:4:zh":"(object)","grammar:143:ex4:words:4:pos":"particle","grammar:143:ex4:words:5:zh":"looking for","grammar:143:ex4:words:5:note":"さがす","grammar:143:ex4:words:5:pos":"verb","grammar:143:ex4:points:0":"「〜から逃げる」 can mean physically escaping from a place, or avoiding work or responsibility.","grammar:143:ex4:points:1":"dictionary form + 方法 expresses a way of doing something.","grammar:143:ex5:trans":"Sometimes it's necessary to run away.","grammar:143:ex5:structure":"逃げることは時には必要だ","grammar:143:ex5:words:0:zh":"escape","grammar:143:ex5:words:0:note":"にげる","grammar:143:ex5:words:0:pos":"verb","grammar:143:ex5:words:1:zh":"(nominalizer)","grammar:143:ex5:words:1:pos":"noun","grammar:143:ex5:words:2:zh":"(topic)","grammar:143:ex5:words:2:pos":"particle","grammar:143:ex5:words:3:zh":"sometimes","grammar:143:ex5:words:3:note":"ときには","grammar:143:ex5:words:3:pos":"adverb","grammar:143:ex5:words:4:zh":"necessary","grammar:143:ex5:words:4:note":"ひつよう","grammar:143:ex5:words:4:pos":"na-adjective","grammar:143:ex5:words:5:zh":"is","grammar:143:ex5:words:5:pos":"copula","grammar:143:ex5:points:0":"❗逃げること: running away (also in the positive sense of stepping back for now); 時には = sometimes.","grammar:143:ex5:points:1":"逃げる: run away."},"144":{"example:144:exzh":"He is a police officer.","example:144:exzh2":"Work as a public official carries heavy responsibility.","example:144:exzh3":"It is a public official's duty to obey the country's laws.","example:144:exzh4":"A public official's decisions have a major impact.","example:144:exzh5":"Many public officials attended the meeting."},"146":{"example:146:exzh":"Please come over here.","example:146:exzh2":"Please take this road.","example:146:exzh3":"This way is my house.","example:146:exzh4":"This way is more fun.","example:146:exzh5":"Please look this way.","grammar:146:ex:trans":"Please come over here.","grammar:146:ex:structure":"こっちに来てください","grammar:146:ex:explain":"This sentence makes a request with 「こっちに来てください」. 「こっち」 is the casual form of 「こちら」, meaning 'this way,' and sounds relaxed. 「に」 marks the direction of movement. The verb 「来る」 is irregular: its te-form 「来て」 (read きて) plus 「ください」 makes a polite request. The whole sentence 「こっちに来てください」 means 'Please come over here.' Note that the te-form of 「来る」 is pronounced 「きて」; memorize this irregular change carefully.","grammar:146:ex:words:0:zh":"this way","grammar:146:ex:words:0:pos":"pronoun","grammar:146:ex:words:1:zh":"(direction)","grammar:146:ex:words:1:pos":"particle","grammar:146:ex:words:2:zh":"come","grammar:146:ex:words:2:note":"きて","grammar:146:ex:words:2:pos":"verb","grammar:146:ex:words:3:zh":"please","grammar:146:ex:words:3:pos":"auxiliary verb","grammar:146:ex:points:0":"「こっち」: this way (casual form of こちら).","grammar:146:ex:points:1":"来る→来て＋ください.","grammar:146:ex2:trans":"Please go along this road.","grammar:146:ex2:structure":"こっちの道を行ってください","grammar:146:ex2:words:0:zh":"this way","grammar:146:ex2:words:0:pos":"pronoun","grammar:146:ex2:words:1:zh":"'s","grammar:146:ex2:words:1:pos":"particle","grammar:146:ex2:words:2:zh":"road","grammar:146:ex2:words:2:note":"みち","grammar:146:ex2:words:2:pos":"noun","grammar:146:ex2:words:3:zh":"(path)","grammar:146:ex2:words:3:pos":"particle","grammar:146:ex2:words:4:zh":"walk","grammar:146:ex2:words:4:note":"いって","grammar:146:ex2:words:4:pos":"verb","grammar:146:ex2:words:5:zh":"please","grammar:146:ex2:words:5:pos":"auxiliary verb","grammar:146:ex2:points:0":"を＋行く: to go along … (the path takes を).","grammar:146:ex2:points:1":"「こっちの道」: this road.","grammar:146:ex3:trans":"This is my house.","grammar:146:ex3:structure":"こっちが〜です","grammar:146:ex3:words:0:zh":"this way","grammar:146:ex3:words:0:pos":"pronoun","grammar:146:ex3:words:1:zh":"(nominative)","grammar:146:ex3:words:1:pos":"particle","grammar:146:ex3:words:2:zh":"I","grammar:146:ex3:words:2:note":"わたし","grammar:146:ex3:words:2:pos":"pronoun","grammar:146:ex3:words:3:zh":"'s","grammar:146:ex3:words:3:pos":"particle","grammar:146:ex3:words:4:zh":"house","grammar:146:ex3:words:4:note":"いえ","grammar:146:ex3:words:4:pos":"noun","grammar:146:ex3:words:5:zh":"is","grammar:146:ex3:words:5:pos":"copula","grammar:146:ex3:points:0":"❓Why が? が singles out 'this one' as the house.","grammar:146:ex3:points:1":"「私の家」: my house.","grammar:146:ex4:trans":"This side is more fun, you know.","grammar:146:ex4:structure":"こっちの方が〜よ","grammar:146:ex4:words:0:zh":"this way","grammar:146:ex4:words:0:pos":"pronoun","grammar:146:ex4:words:1:zh":"'s","grammar:146:ex4:words:1:pos":"particle","grammar:146:ex4:words:2:zh":"one (of them) / one side","grammar:146:ex4:words:2:note":"ほう","grammar:146:ex4:words:2:pos":"noun","grammar:146:ex4:words:3:zh":"(nominative)","grammar:146:ex4:words:3:pos":"particle","grammar:146:ex4:words:4:zh":"interesting","grammar:146:ex4:words:4:note":"たのしい","grammar:146:ex4:words:4:pos":"adjective","grammar:146:ex4:words:5:zh":"you know","grammar:146:ex4:words:5:pos":"particle","grammar:146:ex4:points:0":"「〜の方が〜」: … is more … (comparative sentence).","grammar:146:ex4:points:1":"「よ」: sentence-final particle that tells the listener something.","grammar:146:ex5:trans":"Please look this way.","grammar:146:ex5:structure":"こっちを見てください","grammar:146:ex5:words:0:zh":"this way","grammar:146:ex5:words:0:pos":"pronoun","grammar:146:ex5:words:1:zh":"(object marker)","grammar:146:ex5:words:1:pos":"particle","grammar:146:ex5:words:2:zh":"look","grammar:146:ex5:words:2:note":"みて","grammar:146:ex5:words:2:pos":"verb","grammar:146:ex5:words:3:zh":"please","grammar:146:ex5:words:3:pos":"auxiliary verb","grammar:146:ex5:points:0":"「こっちを見る」: to look this way.","grammar:146:ex5:points:1":"見る→見て＋ください。"},"147":{"example:147:exzh":"The relationship with him is good.","example:147:exzh2":"That incident is connected to us.","example:147:exzh3":"Please value family relationships.","example:147:exzh4":"I think about the relationship between work and private life.","example:147:exzh5":"The relationship with her is complicated.","grammar:147:ex:trans":"The relationship with him is good.","grammar:147:ex:structure":"〜との関係は〜です","grammar:147:ex:explain":"This sentence uses 「〜との関係」 to describe a relationship between people. 「と」 marks the other party, and 「の」 links it to a noun, so 「彼との関係」 means 'the relationship with him.' This 「〜との＋noun」 pattern turns 'the relationship with someone' into a noun phrase. 「は」 makes it the topic, and the predicate 「良好」 is a na-adjective that attaches directly to 「です」. The whole sentence 「彼との関係は良好です」 means 'The relationship with him is good.' 「〜との」 is a common structure for saying 'with whom,' and it is clearer than using 「の」 alone.","grammar:147:ex:words:0:zh":"he","grammar:147:ex:words:0:note":"かれ","grammar:147:ex:words:0:pos":"pronoun","grammar:147:ex:words:1:zh":"with","grammar:147:ex:words:1:pos":"particle","grammar:147:ex:words:2:zh":"'s","grammar:147:ex:words:2:pos":"particle","grammar:147:ex:words:3:zh":"relationship","grammar:147:ex:words:3:note":"かんけい","grammar:147:ex:words:3:pos":"noun","grammar:147:ex:words:4:zh":"(topic)","grammar:147:ex:words:4:pos":"particle","grammar:147:ex:words:5:zh":"good","grammar:147:ex:words:5:note":"りょうこう","grammar:147:ex:words:5:pos":"na-adjective","grammar:147:ex:words:6:zh":"(polite form)","grammar:147:ex:words:6:pos":"copula","grammar:147:ex:points:0":"「〜との関係」: the relationship with … (と＋の).","grammar:147:ex:points:1":"「良好」: good (na-adjective).","grammar:147:ex2:trans":"That case has something to do with us.","grammar:147:ex2:structure":"〜に関係があります","grammar:147:ex2:words:0:zh":"that","grammar:147:ex2:words:0:pos":"pre-noun adjectival","grammar:147:ex2:words:1:zh":"incident","grammar:147:ex2:words:1:note":"じけん","grammar:147:ex2:words:1:pos":"noun","grammar:147:ex2:words:2:zh":"(topic)","grammar:147:ex2:words:2:pos":"particle","grammar:147:ex2:words:3:zh":"we","grammar:147:ex2:words:3:note":"わたしたち","grammar:147:ex2:words:3:pos":"pronoun","grammar:147:ex2:words:4:zh":"(object)","grammar:147:ex2:words:4:pos":"particle","grammar:147:ex2:words:5:zh":"relationship","grammar:147:ex2:words:5:note":"かんけい","grammar:147:ex2:words:5:pos":"noun","grammar:147:ex2:words:6:zh":"(nominative)","grammar:147:ex2:words:6:pos":"particle","grammar:147:ex2:words:7:zh":"there is / are","grammar:147:ex2:words:7:pos":"verb","grammar:147:ex2:points:0":"「〜に関係がある」: to have a connection with … (に marks the target).","grammar:147:ex2:points:1":"が marks the 'connection' that exists.","grammar:147:ex3:trans":"Please cherish your family relationships.","grammar:147:ex3:structure":"〜を大切にしてください","grammar:147:ex3:words:0:zh":"family","grammar:147:ex3:words:0:note":"かぞく","grammar:147:ex3:words:0:pos":"noun","grammar:147:ex3:words:1:zh":"'s","grammar:147:ex3:words:1:pos":"particle","grammar:147:ex3:words:2:zh":"relationship","grammar:147:ex3:words:2:note":"かんけい","grammar:147:ex3:words:2:pos":"noun","grammar:147:ex3:words:3:zh":"(object marker)","grammar:147:ex3:words:3:pos":"particle","grammar:147:ex3:words:4:zh":"cherish","grammar:147:ex3:words:4:note":"たいせつにして","grammar:147:ex3:words:4:pos":"verb","grammar:147:ex3:words:5:zh":"please","grammar:147:ex3:words:5:pos":"auxiliary verb","grammar:147:ex3:points:0":"「家族の関係」: family relationships.","grammar:147:ex3:points:1":"「〜を大切にする」: to cherish …","grammar:147:ex4:trans":"I think about the relationship between work and private life.","grammar:147:ex4:structure":"〜と〜の関係を考えます","grammar:147:ex4:words:0:zh":"work","grammar:147:ex4:words:0:note":"しごと","grammar:147:ex4:words:0:pos":"noun","grammar:147:ex4:words:1:zh":"with","grammar:147:ex4:words:1:pos":"particle","grammar:147:ex4:words:2:zh":"private life","grammar:147:ex4:words:2:note":"loanword","grammar:147:ex4:words:2:pos":"noun","grammar:147:ex4:words:3:zh":"'s","grammar:147:ex4:words:3:pos":"particle","grammar:147:ex4:words:4:zh":"relationship","grammar:147:ex4:words:4:note":"かんけい","grammar:147:ex4:words:4:pos":"noun","grammar:147:ex4:words:5:zh":"(object marker)","grammar:147:ex4:words:5:pos":"particle","grammar:147:ex4:words:6:zh":"consider","grammar:147:ex4:words:6:note":"かんがえます","grammar:147:ex4:words:6:pos":"verb","grammar:147:ex4:points:0":"「AとBの関係」: the relationship between A and B.","grammar:147:ex4:points:1":"「考える」: to think about, to consider.","grammar:147:ex5:trans":"The relationship with her is complicated.","grammar:147:ex5:structure":"〜との関係は〜だ","grammar:147:ex5:words:0:zh":"she","grammar:147:ex5:words:0:note":"かのじょ","grammar:147:ex5:words:0:pos":"pronoun","grammar:147:ex5:words:1:zh":"with","grammar:147:ex5:words:1:pos":"particle","grammar:147:ex5:words:2:zh":"'s","grammar:147:ex5:words:2:pos":"particle","grammar:147:ex5:words:3:zh":"relationship","grammar:147:ex5:words:3:note":"かんけい","grammar:147:ex5:words:3:pos":"noun","grammar:147:ex5:words:4:zh":"(topic)","grammar:147:ex5:words:4:pos":"particle","grammar:147:ex5:words:5:zh":"complicated","grammar:147:ex5:words:5:note":"ふくざつ","grammar:147:ex5:words:5:pos":"na-adjective","grammar:147:ex5:words:6:zh":"is (plain form)","grammar:147:ex5:words:6:pos":"copula","grammar:147:ex5:points:0":"「〜との関係」: the relationship with …","grammar:147:ex5:points:1":"「複雑だ」: complicated (plain form of a na-adjective)."},"148":{"example:148:exzh":"He lives happily.","example:148:exzh2":"Sometimes life is hard.","example:148:exzh3":"She lives each day full of energy.","example:148:exzh4":"I want to live in a good environment.","example:148:exzh5":"As long as you're alive, there's still hope.","grammar:148:ex:trans":"He lives happily.","grammar:148:ex:structure":"幸せに生きている","grammar:148:ex:explain":"This sentence uses the intransitive verb 「生きる」 together with an adverb. 「生きる（いきる）」 means \"to live, to survive\" and is an intransitive verb. Adding 「に」 to the na-adjective 「幸せ」 turns it into the adverb 「幸せに」, which modifies the verb, so 「幸せに生きる」 = \"to live happily.\" This is the 「に」 usage where a na-adjective becomes an adverb (compare with 「く」 for i-adjectives). The te-form of the verb 「生きて」 plus 「いる」 expresses a continuing state. The whole sentence 「彼は幸せに生きている」 = \"He lives happily.\"","grammar:148:ex:words:0:zh":"he","grammar:148:ex:words:0:note":"かれ","grammar:148:ex:words:0:pos":"pronoun","grammar:148:ex:words:1:zh":"(topic)","grammar:148:ex:words:1:pos":"particle","grammar:148:ex:words:2:zh":"happy","grammar:148:ex:words:2:note":"しあわせ","grammar:148:ex:words:2:pos":"na-adjective","grammar:148:ex:words:3:zh":"(made adverbial)","grammar:148:ex:words:3:pos":"particle","grammar:148:ex:words:4:zh":"living","grammar:148:ex:words:4:note":"いきている","grammar:148:ex:words:4:pos":"verb","grammar:148:ex:points:0":"❗生きる（いきる）: to live, to survive (intransitive verb).","grammar:148:ex:points:1":"幸せに生きる: to live happily.","grammar:148:ex2:trans":"Life is sometimes hard.","grammar:148:ex2:structure":"〜ことは〜時もある","grammar:148:ex2:words:0:zh":"to live","grammar:148:ex2:words:0:note":"いきる","grammar:148:ex2:words:0:pos":"verb","grammar:148:ex2:words:1:zh":"(nominalizer)","grammar:148:ex2:words:1:pos":"noun","grammar:148:ex2:words:2:zh":"(topic)","grammar:148:ex2:words:2:pos":"particle","grammar:148:ex2:words:3:zh":"difficult","grammar:148:ex2:words:3:note":"むずかしい","grammar:148:ex2:words:3:pos":"adjective","grammar:148:ex2:words:4:zh":"time","grammar:148:ex2:words:4:note":"とき","grammar:148:ex2:words:4:pos":"noun","grammar:148:ex2:words:5:zh":"also, too","grammar:148:ex2:words:5:pos":"particle","grammar:148:ex2:words:6:zh":"there is / are","grammar:148:ex2:words:6:pos":"verb","grammar:148:ex2:points:0":"生きること: living (nominalized).","grammar:148:ex2:points:1":"〜時もある: there are times when … too.","grammar:148:ex3:trans":"She lives every day full of energy.","grammar:148:ex3:structure":"毎日を〜に生きている","grammar:148:ex3:explain":"「毎日を」 is not used as an ordinary time adverb; it treats each day as actual lived time of one's life. 「元気に」 modifies 「生きる」, describing the state or manner in which she lives. Here 「生きている」 describes her living an energetic life on an ongoing basis.","grammar:148:ex3:words:0:zh":"she","grammar:148:ex3:words:0:note":"かのじょ","grammar:148:ex3:words:0:pos":"pronoun","grammar:148:ex3:words:1:zh":"(topic)","grammar:148:ex3:words:1:pos":"particle","grammar:148:ex3:words:2:zh":"every day","grammar:148:ex3:words:2:note":"まいにち","grammar:148:ex3:words:2:pos":"noun","grammar:148:ex3:words:3:zh":"(the span of time being lived through)","grammar:148:ex3:words:3:pos":"particle","grammar:148:ex3:words:4:zh":"energetic, in good spirits","grammar:148:ex3:words:4:note":"げんき","grammar:148:ex3:words:4:pos":"na-adjective","grammar:148:ex3:words:5:zh":"(adverbial use of a na-adjective)","grammar:148:ex3:words:5:pos":"auxiliary verb","grammar:148:ex3:words:6:zh":"to live, to be alive","grammar:148:ex3:words:6:note":"いき","grammar:148:ex3:words:6:pos":"verb","grammar:148:ex3:words:7:zh":"(links to the progressive expression that follows)","grammar:148:ex3:words:7:pos":"particle","grammar:148:ex3:words:8:zh":"(a continuing state of living)","grammar:148:ex3:words:8:pos":"verb","grammar:148:ex3:points:0":"「毎日を生きる」 treats each day as a span of time you live through, which feels stronger than plain 「毎日」.","grammar:148:ex3:points:1":"Na-adjectives take 「〜に」 when modifying a verb, so 「元気に」 means \"energetically.\"","grammar:148:ex4:trans":"I want to live in a good environment.","grammar:148:ex4:structure":"〜で生きたい","grammar:148:ex4:words:0:zh":"good","grammar:148:ex4:words:0:note":"いい","grammar:148:ex4:words:0:pos":"adjective","grammar:148:ex4:words:1:zh":"environment","grammar:148:ex4:words:1:note":"かんきょう","grammar:148:ex4:words:1:pos":"noun","grammar:148:ex4:words:2:zh":"(place)","grammar:148:ex4:words:2:pos":"particle","grammar:148:ex4:words:3:zh":"want to live","grammar:148:ex4:words:3:note":"いきたい","grammar:148:ex4:words:3:pos":"verb","grammar:148:ex4:points:0":"❓良い環境で: in a good environment (で = place).","grammar:148:ex4:points:1":"〜たい: to want to ….","grammar:148:ex5:trans":"As long as you're alive, there's still hope.","grammar:148:ex5:structure":"〜限り、〜はある","grammar:148:ex5:words:0:zh":"living","grammar:148:ex5:words:0:note":"いきている","grammar:148:ex5:words:0:pos":"verb","grammar:148:ex5:words:1:zh":"range","grammar:148:ex5:words:1:note":"かぎり","grammar:148:ex5:words:1:pos":"noun","grammar:148:ex5:words:2:zh":"hope","grammar:148:ex5:words:2:note":"きぼう","grammar:148:ex5:words:2:pos":"noun","grammar:148:ex5:words:3:zh":"(topic)","grammar:148:ex5:words:3:pos":"particle","grammar:148:ex5:words:4:zh":"there is / are","grammar:148:ex5:words:4:pos":"verb","grammar:148:ex5:points:0":"❗〜限り: as long as …","grammar:148:ex5:points:1":"生きている限り: as long as you live."},"149":{"example:149:exzh":"Everyone gathered together.","example:149:exzh2":"All the problems were solved.","example:149:exzh3":"She understands everything.","example:149:exzh4":"All the preparations are done.","example:149:exzh5":"It's okay to throw everything away."},"151":{"example:151:exzh":"He came along with a friend.","example:151:exzh2":"I plan to go together with a companion.","example:151:exzh3":"It's reassuring to have a companion with you.","example:151:exzh4":"My companion on this trip is a family member.","example:151:exzh5":"She went home with her child."},"153":{"example:153:exzh":"Let's go outside.","example:153:exzh2":"It's cold outside.","example:153:exzh3":"The scenery outside is beautiful.","example:153:exzh4":"He's playing outside.","example:153:exzh5":"There are many people outside.","grammar:153:ex:trans":"Let's go outside.","grammar:153:ex:structure":"外に出ましょう","grammar:153:ex:explain":"This sentence uses 「外に出ましょう」 to suggest going out. 「外（そと）」 is a noun meaning the outside, and 「に」 marks the direction of movement. The verb 「出る」 is an ichidan verb; to make the volitional form you drop る and add ましょう, giving 「出ましょう」, which means let's do something together. The whole sentence 「外に出ましょう」 means let's go outside. Note that 「出る」 is an intransitive verb (a person goes out); its transitive counterpart is 「出す」 (to take something out), and the two are used differently.","grammar:153:ex:words:0:zh":"outside","grammar:153:ex:words:0:note":"そと","grammar:153:ex:words:0:pos":"noun","grammar:153:ex:words:1:zh":"(direction)","grammar:153:ex:words:1:pos":"particle","grammar:153:ex:words:2:zh":"let's go out","grammar:153:ex:words:2:note":"でましょう","grammar:153:ex:words:2:pos":"verb","grammar:153:ex:points:0":"外（そと）: the outside.","grammar:153:ex:points:1":"出る→出ましょう: a suggestion.","grammar:153:ex2:trans":"It's cold outside.","grammar:153:ex2:structure":"外は〜です","grammar:153:ex2:words:0:zh":"outside","grammar:153:ex2:words:0:note":"そと","grammar:153:ex2:words:0:pos":"noun","grammar:153:ex2:words:1:zh":"(topic)","grammar:153:ex2:words:1:pos":"particle","grammar:153:ex2:words:2:zh":"cold","grammar:153:ex2:words:2:note":"さむい","grammar:153:ex2:words:2:pos":"adjective","grammar:153:ex2:words:3:zh":"(polite form)","grammar:153:ex2:words:3:pos":"copula","grammar:153:ex2:points:0":"外は寒い: it's cold outside.","grammar:153:ex2:points:1":"寒い: i-adjective.","grammar:153:ex3:trans":"The scenery outside is beautiful.","grammar:153:ex3:structure":"〜がきれいです","grammar:153:ex3:words:0:zh":"outside","grammar:153:ex3:words:0:note":"そと","grammar:153:ex3:words:0:pos":"noun","grammar:153:ex3:words:1:zh":"'s","grammar:153:ex3:words:1:pos":"particle","grammar:153:ex3:words:2:zh":"scenery","grammar:153:ex3:words:2:note":"ふうけい","grammar:153:ex3:words:2:pos":"noun","grammar:153:ex3:words:3:zh":"(nominative)","grammar:153:ex3:words:3:pos":"particle","grammar:153:ex3:words:4:zh":"beautiful","grammar:153:ex3:words:4:pos":"na-adjective","grammar:153:ex3:words:5:zh":"(polite form)","grammar:153:ex3:words:5:pos":"copula","grammar:153:ex3:points:0":"外の風景: the scenery outside.","grammar:153:ex3:points:1":"きれい: na-adjective (the subject takes が).","grammar:153:ex4:trans":"He is playing outside.","grammar:153:ex4:structure":"〜で遊んでいます","grammar:153:ex4:words:0:zh":"he","grammar:153:ex4:words:0:note":"かれ","grammar:153:ex4:words:0:pos":"pronoun","grammar:153:ex4:words:1:zh":"(topic)","grammar:153:ex4:words:1:pos":"particle","grammar:153:ex4:words:2:zh":"outside","grammar:153:ex4:words:2:note":"そと","grammar:153:ex4:words:2:pos":"noun","grammar:153:ex4:words:3:zh":"(place of the action)","grammar:153:ex4:words:3:pos":"particle","grammar:153:ex4:words:4:zh":"playing","grammar:153:ex4:words:4:note":"あそんでいます","grammar:153:ex4:words:4:pos":"verb","grammar:153:ex4:points:0":"❓Why で? Playing is an action, so the place takes で.","grammar:153:ex4:points:1":"〜ている: ongoing action.","grammar:153:ex5:trans":"There are many people outside.","grammar:153:ex5:structure":"〜に〜がたくさんいます","grammar:153:ex5:words:0:zh":"outside","grammar:153:ex5:words:0:note":"そと","grammar:153:ex5:words:0:pos":"noun","grammar:153:ex5:words:1:zh":"(location of existence)","grammar:153:ex5:words:1:pos":"particle","grammar:153:ex5:words:2:zh":"person","grammar:153:ex5:words:2:note":"ひと","grammar:153:ex5:words:2:pos":"noun","grammar:153:ex5:words:3:zh":"(nominative)","grammar:153:ex5:words:3:pos":"particle","grammar:153:ex5:words:4:zh":"a lot","grammar:153:ex5:words:4:pos":"adverb","grammar:153:ex5:words:5:zh":"there is / are","grammar:153:ex5:words:5:pos":"verb","grammar:153:ex5:points:0":"に＋がいます: there is (a person) in a place.","grammar:153:ex5:points:1":"たくさん: a lot.","exam:153:zh":"It's warm inside the room, but it's cold outside where it's snowing.","exam:153:why":"「外」 means the place outside the room, which fits the snowy situation. 「中」 contradicts the earlier statement that the room is warm."},"155":{"example:155:exzh":"My mother is good at cooking.","example:155:exzh2":"I'm grateful to my mother.","example:155:exzh3":"She lives with her mother.","example:155:exzh4":"A letter from my mother arrived.","example:155:exzh5":"I gave her a present on Mother's Day.","grammar:155:ex:trans":"My mother is good at cooking.","grammar:155:ex:structure":"〜は〜が得意です","grammar:155:ex:explain":"This sentence uses 「〜が得意です」 to say that someone is good at something. 「母（はは）」 is the humble way to refer to your own mother when talking to outsiders; for someone else's mother you use the respectful 「お母さん」. 「得意」 is a na-adjective meaning good at, skilled at, and the thing you are good at is marked with 「が」: 「料理が得意」 means good at cooking, the same pattern as 「好き・上手」 taking 「が」. The whole sentence 「私の母は料理が得意です」 means my mother is good at cooking, and it reviews both the humble term and the use of 「が」.","grammar:155:ex:words:0:zh":"I","grammar:155:ex:words:0:note":"わたし","grammar:155:ex:words:0:pos":"pronoun","grammar:155:ex:words:1:zh":"'s","grammar:155:ex:words:1:pos":"particle","grammar:155:ex:words:2:zh":"mother","grammar:155:ex:words:2:note":"はは","grammar:155:ex:words:2:pos":"noun","grammar:155:ex:words:3:zh":"(topic)","grammar:155:ex:words:3:pos":"particle","grammar:155:ex:words:4:zh":"cooking","grammar:155:ex:words:4:note":"りょうり","grammar:155:ex:words:4:pos":"noun","grammar:155:ex:words:5:zh":"(object)","grammar:155:ex:words:5:pos":"particle","grammar:155:ex:words:6:zh":"good at","grammar:155:ex:words:6:note":"とくい","grammar:155:ex:words:6:pos":"na-adjective","grammar:155:ex:words:7:zh":"(polite form)","grammar:155:ex:words:7:pos":"copula","grammar:155:ex:points:0":"❗母（はは）: (humble) one's own mother; for someone else's mother, use お母さん.","grammar:155:ex:points:1":"The object of 「得意」 takes が.","grammar:155:ex2:trans":"I am grateful to my mother.","grammar:155:ex2:structure":"〜に感謝しています","grammar:155:ex2:words:0:zh":"mother","grammar:155:ex2:words:0:note":"はは","grammar:155:ex2:words:0:pos":"noun","grammar:155:ex2:words:1:zh":"(object)","grammar:155:ex2:words:1:pos":"particle","grammar:155:ex2:words:2:zh":"am grateful","grammar:155:ex2:words:2:note":"かんしゃしています","grammar:155:ex2:words:2:pos":"verb","grammar:155:ex2:points:0":"〜に感謝する: to be grateful to… (the target takes に).","grammar:155:ex2:points:1":"〜ている: an ongoing feeling.","grammar:155:ex3:trans":"She lives together with her mother.","grammar:155:ex3:structure":"〜と一緒に暮らしています","grammar:155:ex3:words:0:zh":"she","grammar:155:ex3:words:0:note":"かのじょ","grammar:155:ex3:words:0:pos":"pronoun","grammar:155:ex3:words:1:zh":"(topic)","grammar:155:ex3:words:1:pos":"particle","grammar:155:ex3:words:2:zh":"mother","grammar:155:ex3:words:2:note":"おかあさん","grammar:155:ex3:words:2:pos":"noun","grammar:155:ex3:words:3:zh":"with","grammar:155:ex3:words:3:pos":"particle","grammar:155:ex3:words:4:zh":"together","grammar:155:ex3:words:4:note":"いっしょに","grammar:155:ex3:words:4:pos":"adverb","grammar:155:ex3:words:5:zh":"lives","grammar:155:ex3:words:5:note":"くらしています","grammar:155:ex3:words:5:pos":"verb","grammar:155:ex3:points:0":"❗お母さん: (respectful) someone else's mother / how you address your own mother.","grammar:155:ex3:points:1":"暮らす: to live, to get by from day to day.","grammar:155:ex4:trans":"A letter from my mother arrived.","grammar:155:ex4:structure":"〜から〜が届きました","grammar:155:ex4:words:0:zh":"mother","grammar:155:ex4:words:0:note":"はは","grammar:155:ex4:words:0:pos":"noun","grammar:155:ex4:words:1:zh":"from","grammar:155:ex4:words:1:pos":"particle","grammar:155:ex4:words:2:zh":"letter","grammar:155:ex4:words:2:note":"てがみ","grammar:155:ex4:words:2:pos":"noun","grammar:155:ex4:words:3:zh":"(nominative)","grammar:155:ex4:words:3:pos":"particle","grammar:155:ex4:words:4:zh":"arrived","grammar:155:ex4:words:4:note":"とどきました","grammar:155:ex4:words:4:pos":"verb","grammar:155:ex4:points:0":"〜から: from… (the source).","grammar:155:ex4:points:1":"届く: (something) arrives (intransitive verb; the subject takes が).","grammar:155:ex5:trans":"I gave her a present on Mother's Day.","grammar:155:ex5:structure":"〜にプレゼントをあげました","grammar:155:ex5:words:0:zh":"Mother's Day","grammar:155:ex5:words:0:note":"ははのひ","grammar:155:ex5:words:0:pos":"noun","grammar:155:ex5:words:1:zh":"(point in time)","grammar:155:ex5:words:1:pos":"particle","grammar:155:ex5:words:2:zh":"present","grammar:155:ex5:words:2:note":"loanword","grammar:155:ex5:words:2:pos":"noun","grammar:155:ex5:words:3:zh":"(object marker)","grammar:155:ex5:words:3:pos":"particle","grammar:155:ex5:words:4:zh":"gave","grammar:155:ex5:words:4:pos":"verb","grammar:155:ex5:points:0":"母の日: Mother's Day.","grammar:155:ex5:points:1":"あげる: (I) give (to someone else); あげる→あげました.","exam:155:zh":"The person who gave birth to me is my mother.","exam:155:why":"「母」 means one's own mother. 「姉」 means older sister, who is not the person who gave birth to you."},"157":{"example:157:exzh":"No, I'm not going.","example:157:exzh2":"No, that's not right.","example:157:exzh3":"No, I haven't eaten yet.","example:157:exzh4":"No, he isn't a student.","example:157:exzh5":"No, there's no problem.","grammar:157:ex:trans":"No, I'm not going.","grammar:157:ex:structure":"いいえ、〜ません","grammar:157:ex:explain":"This is a negative answer. 「いいえ」 means no and is used to negate the other person's question or suggestion. The polite negative of the verb 「行く」 is 「行きません」: replace 「ます」 in the masu-form with 「ません」 to mean not going. 「私は」 makes the speaker the topic. The whole sentence 「いいえ、私は行きません」 means no, I'm not going. Note that Japanese 「はい／いいえ」 sometimes answers whether the question itself is true, so when replying to a negative question the logic works a little differently—keep that in mind.","grammar:157:ex:words:0:zh":"No","grammar:157:ex:words:0:pos":"a set greeting phrase","grammar:157:ex:words:1:zh":"I","grammar:157:ex:words:1:note":"わたし","grammar:157:ex:words:1:pos":"pronoun","grammar:157:ex:words:2:zh":"(topic)","grammar:157:ex:words:2:pos":"particle","grammar:157:ex:words:3:zh":"not going","grammar:157:ex:words:3:note":"いきません","grammar:157:ex:words:3:pos":"verb","grammar:157:ex:points:0":"いいえ: no (a negative answer).","grammar:157:ex:points:1":"行く→行きません (polite negative).","grammar:157:ex2:trans":"No, that's wrong.","grammar:157:ex2:structure":"いいえ、違います","grammar:157:ex2:words:0:zh":"No","grammar:157:ex2:words:0:pos":"a set greeting phrase","grammar:157:ex2:words:1:zh":"that's not right","grammar:157:ex2:words:1:note":"ちがいます","grammar:157:ex2:words:1:pos":"verb","grammar:157:ex2:points:0":"違います: that's wrong, that's not how it is.","grammar:157:ex2:points:1":"違う→違います.","grammar:157:ex3:trans":"No, I haven't eaten yet.","grammar:157:ex3:structure":"いいえ、まだ〜ていません","grammar:157:ex3:words:0:zh":"No","grammar:157:ex3:words:0:pos":"a set greeting phrase","grammar:157:ex3:words:1:zh":"still / yet","grammar:157:ex3:words:1:pos":"adverb","grammar:157:ex3:words:2:zh":"haven't eaten yet","grammar:157:ex3:words:2:note":"たべていません","grammar:157:ex3:words:2:pos":"verb","grammar:157:ex3:points:0":"まだ〜ていません: haven't (done)… yet.","grammar:157:ex3:points:1":"A negative answer plus a description of the state.","grammar:157:ex4:trans":"No, he is not a student.","grammar:157:ex4:structure":"いいえ、〜ではありません","grammar:157:ex4:words:0:zh":"No","grammar:157:ex4:words:0:pos":"a set greeting phrase","grammar:157:ex4:words:1:zh":"he","grammar:157:ex4:words:1:note":"かれ","grammar:157:ex4:words:1:pos":"pronoun","grammar:157:ex4:words:2:zh":"(topic)","grammar:157:ex4:words:2:pos":"particle","grammar:157:ex4:words:3:zh":"student","grammar:157:ex4:words:3:note":"がくせい","grammar:157:ex4:words:3:pos":"noun","grammar:157:ex4:words:4:zh":"is not","grammar:157:ex4:words:4:pos":"copula","grammar:157:ex4:points:0":"ではありません: is not… (polite negative for nouns).","grammar:157:ex4:points:1":"いいえ: a negative answer.","grammar:157:ex5:trans":"No, there's no problem.","grammar:157:ex5:structure":"いいえ、問題ありません","grammar:157:ex5:words:0:zh":"No","grammar:157:ex5:words:0:pos":"a set greeting phrase","grammar:157:ex5:words:1:zh":"problem","grammar:157:ex5:words:1:note":"もんだい","grammar:157:ex5:words:1:pos":"noun","grammar:157:ex5:words:2:zh":"don't have","grammar:157:ex5:words:2:pos":"verb","grammar:157:ex5:points:0":"問題ありません: there's no problem (が is omitted).","grammar:157:ex5:points:1":"ありません: the polite negative of ある.","exam:157:zh":"When I was asked, \"Is this your umbrella?\" I answered, \"No, it isn't mine.\"","exam:157:why":"「いいえ」 is used to say no to the other person's question. 「はい」 means yes, which contradicts the \"it isn't mine\" that follows."},"158":{"example:158:exzh":"He is a being like a god.","example:158:exzh2":"Do you believe in God?","example:158:exzh3":"I visit a shrine to pray to the gods.","example:158:exzh4":"We treasure the teachings of God.","example:158:exzh5":"Many gods appear in myths."},"167":{"example:167:exzh":"I know his name.","example:167:exzh2":"I wish I could know everything.","example:167:exzh3":"If I could find out a little more, I might be able to help.","example:167:exzh4":"The facts that came to light are important.","example:167:exzh5":"I learned a lot about him.","grammar:167:ex:trans":"I know his name.","grammar:167:ex:structure":"noun + を + 知っています. When 「知る」 describes a state, it always takes 〜ている: 知っている = currently know.","grammar:167:ex:explain":"The key here is that 「知る」 needs 「ている」 to express a state. When the verb 「知る」 describes the state of knowing, it is always 「知っている／知っています」; you cannot just say 「知ります」 (that means you will come to know). 「彼の名前を知っています」 = I know his name, and 「を」 marks what is known. The sentence states a fact that is already known. Verbs like 「知る・持つ・住む」 often use 「ている」 for a continuing state, and this is a must-know point for beginners.","grammar:167:ex:words:0:zh":"he","grammar:167:ex:words:0:note":"かれ","grammar:167:ex:words:0:pos":"pronoun","grammar:167:ex:words:1:zh":"'s","grammar:167:ex:words:1:pos":"particle","grammar:167:ex:words:2:zh":"name","grammar:167:ex:words:2:note":"なまえ","grammar:167:ex:words:2:pos":"noun","grammar:167:ex:words:3:zh":"(object marker)","grammar:167:ex:words:3:pos":"particle","grammar:167:ex:words:4:zh":"know","grammar:167:ex:words:4:note":"しっています; the 〜ている form of 知る expresses the state of knowing","grammar:167:ex:words:4:pos":"verb","grammar:167:ex:points:0":"知っている: expresses the state of knowing (you don't say 知る)","grammar:167:ex:points:1":"を marks what is known","grammar:167:ex2:trans":"If only I could know everything.","grammar:167:ex2:structure":"〜たら＋いいのに. 「知れる」 is the potential form of 知る, たら marks the condition, and 「いいのに」 carries a note of regret: if only it were possible, though it is not.","grammar:167:ex2:words:0:zh":"everything / all","grammar:167:ex2:words:0:pos":"noun","grammar:167:ex2:words:1:zh":"(object marker)","grammar:167:ex2:words:1:pos":"particle","grammar:167:ex2:words:2:zh":"if I could know","grammar:167:ex2:words:2:note":"しれたら; the たら conditional of the potential form 知れる","grammar:167:ex2:words:2:pos":"verb","grammar:167:ex2:words:3:zh":"if only … (with regret)","grammar:167:ex2:words:3:note":"〜たらいいのに expresses an unfulfilled wish and regret","grammar:167:ex2:words:3:pos":"phrase","grammar:167:ex2:points:0":"〜たらいいのに: if only … (with regret)","grammar:167:ex2:points:1":"知れる: the potential form of 知る, meaning can know","grammar:167:ex3:trans":"If I could learn a little more, I might be able to help.","grammar:167:ex3:structure":"〜ば、verb dictionary form＋ことができるかもしれない","grammar:167:ex3:explain":"「もう少し」 means a little more; the potential form of 「知る」 is 「知れる」, and its conditional form is 「知れれば」, which splits into the hypothetical base 「知れれ」 and 「ば」. 「助けることができる」 means to be able to help, and 「かもしれない」 is added to lower the level of certainty. The final 「か・も・しれ・ない」 should be understood as a single unit meaning maybe, not translated word by word.","grammar:167:ex3:words:0:zh":"more, further","grammar:167:ex3:words:0:pos":"adverb","grammar:167:ex3:words:1:zh":"just a little bit","grammar:167:ex3:words:1:note":"すこし","grammar:167:ex3:words:1:pos":"adverb","grammar:167:ex3:words:2:zh":"can know","grammar:167:ex3:words:2:note":"しれれ","grammar:167:ex3:words:2:pos":"verb","grammar:167:ex3:words:3:zh":"if","grammar:167:ex3:words:3:pos":"particle","grammar:167:ex3:words:4:zh":"help","grammar:167:ex3:words:4:note":"たすける","grammar:167:ex3:words:4:pos":"verb","grammar:167:ex3:words:5:zh":"(nominalizes the action)","grammar:167:ex3:words:5:pos":"noun","grammar:167:ex3:words:6:zh":"(something within one's ability)","grammar:167:ex3:words:6:pos":"particle","grammar:167:ex3:words:7:zh":"be able to","grammar:167:ex3:words:7:pos":"verb","grammar:167:ex3:words:8:zh":"(combines with what follows to form an expression of possibility)","grammar:167:ex3:words:8:pos":"particle","grammar:167:ex3:words:9:zh":"(combines with the surrounding text to form an expression of possibility)","grammar:167:ex3:words:9:pos":"particle","grammar:167:ex3:words:10:zh":"(in this set phrase, means to know for certain)","grammar:167:ex3:words:10:pos":"verb","grammar:167:ex3:words:11:zh":"(negative; the whole unit means maybe)","grammar:167:ex3:words:11:pos":"auxiliary verb","grammar:167:ex3:points:0":"「知れれば」 is the ba-form of the potential 「知れる」, meaning if I can know.","grammar:167:ex3:points:1":"「verb dictionary form + ことができる」 means to be able to do something.","grammar:167:ex3:points:2":"「〜かもしれない」 is a fixed expression meaning maybe or possibly.","grammar:167:ex4:trans":"The fact that became known is important.","grammar:167:ex4:structure":"〔verb in the ta-form〕＋noun＋は＋na-adjective＋だ. 「知れた」 modifies 「事実」, and the na-adjective ends with だ (plain form).","grammar:167:ex4:words:0:zh":"that became known","grammar:167:ex4:words:0:note":"しれた; the ta-form used as a noun modifier","grammar:167:ex4:words:0:pos":"verb","grammar:167:ex4:words:1:zh":"fact","grammar:167:ex4:words:1:note":"じじつ","grammar:167:ex4:words:1:pos":"noun","grammar:167:ex4:words:2:zh":"(topic marker)","grammar:167:ex4:words:2:pos":"particle","grammar:167:ex4:words:3:zh":"important","grammar:167:ex4:words:3:note":"じゅうよう; だ is the plain copula","grammar:167:ex4:words:3:pos":"na-adjective","grammar:167:ex4:points:0":"the verb ta-form modifies a noun: 知れた事実","grammar:167:ex4:points:1":"plain-form na-adjective: 重要だ","grammar:167:ex5:trans":"I learned a lot about him.","grammar:167:ex5:structure":"〜について＋多くのこと＋を＋知れた. 「について」 marks the topic, and 「知れた」 is the past potential form, was able to come to know.","grammar:167:ex5:words:0:zh":"he","grammar:167:ex5:words:0:note":"かれ","grammar:167:ex5:words:0:pos":"pronoun","grammar:167:ex5:words:1:zh":"about","grammar:167:ex5:words:1:note":"marks the topic","grammar:167:ex5:words:1:pos":"phrase","grammar:167:ex5:words:2:zh":"many","grammar:167:ex5:words:2:note":"おおく","grammar:167:ex5:words:2:pos":"noun","grammar:167:ex5:words:3:zh":"'s","grammar:167:ex5:words:3:pos":"particle","grammar:167:ex5:words:4:zh":"thing / matter","grammar:167:ex5:words:4:pos":"noun","grammar:167:ex5:words:5:zh":"(object marker)","grammar:167:ex5:words:5:pos":"particle","grammar:167:ex5:words:6:zh":"came to know","grammar:167:ex5:words:6:note":"しれた; the ta-form past of the potential 知れる","grammar:167:ex5:words:6:pos":"verb","grammar:167:ex5:points:0":"〜について: about …","grammar:167:ex5:points:1":"多くのこと: many things (多く＋の＋こと)"},"168":{"example:168:exzh":"This book is interesting.","example:168:exzh2":"He has many books.","example:168:exzh3":"I borrowed a book at the library.","example:168:exzh4":"Please read this book.","example:168:exzh5":"I'm writing a book.","grammar:168:ex:trans":"This book is interesting.","grammar:168:ex:structure":"この書は〜です","grammar:168:ex:explain":"This sentence uses the literary word 「書」 as the topic. 「書（しょ）」 means book, but it is formal; in everyday speech people usually say 「本」. 「この書は⋯です」 makes this book the topic, and the predicate 「面白い」 is an i-adjective; adding 「です」 makes it polite. The whole sentence 「この書は面白いです」 means this book is interesting. 「書」 can also mean calligraphy or a letter (as in 「書道」 and 「手書」), and when used alone for a book it sounds written; in ordinary conversation 「本」 is more natural.","grammar:168:ex:words:0:zh":"this","grammar:168:ex:words:0:pos":"pre-noun adjectival","grammar:168:ex:words:1:zh":"book","grammar:168:ex:words:1:note":"しょ","grammar:168:ex:words:1:pos":"noun","grammar:168:ex:words:2:zh":"(topic)","grammar:168:ex:words:2:pos":"particle","grammar:168:ex:words:3:zh":"interesting","grammar:168:ex:words:3:note":"おもしろい","grammar:168:ex:words:3:pos":"adjective","grammar:168:ex:words:4:zh":"(polite form)","grammar:168:ex:words:4:pos":"copula","grammar:168:ex:points:1":"面白いです: polite form of an i-adjective.","grammar:168:ex2:trans":"He has many books.","grammar:168:ex2:structure":"〜を持っています (has 〜)","grammar:168:ex2:words:0:zh":"he","grammar:168:ex2:words:0:note":"かれ","grammar:168:ex2:words:0:pos":"pronoun","grammar:168:ex2:words:1:zh":"(topic)","grammar:168:ex2:words:1:pos":"particle","grammar:168:ex2:words:2:zh":"a lot","grammar:168:ex2:words:2:note":"おおく","grammar:168:ex2:words:2:pos":"noun","grammar:168:ex2:words:3:zh":"'s","grammar:168:ex2:words:3:pos":"particle","grammar:168:ex2:words:4:zh":"book","grammar:168:ex2:words:4:note":"しょ","grammar:168:ex2:words:4:pos":"noun","grammar:168:ex2:words:5:zh":"(object marker)","grammar:168:ex2:words:5:pos":"particle","grammar:168:ex2:words:6:zh":"own, have","grammar:168:ex2:words:6:note":"もっています","grammar:168:ex2:words:6:pos":"verb","grammar:168:ex2:points:0":"多くの書: many books.","grammar:168:ex2:points:1":"〜を持っている: to have….","grammar:168:ex3:trans":"I borrowed a book at the library.","grammar:168:ex3:structure":"〜で〜を借りました","grammar:168:ex3:words:0:zh":"library","grammar:168:ex3:words:0:note":"としょかん","grammar:168:ex3:words:0:pos":"noun","grammar:168:ex3:words:1:zh":"(place of the action)","grammar:168:ex3:words:1:pos":"particle","grammar:168:ex3:words:2:zh":"book","grammar:168:ex3:words:2:note":"しょ","grammar:168:ex3:words:2:pos":"noun","grammar:168:ex3:words:3:zh":"(object marker)","grammar:168:ex3:words:3:pos":"particle","grammar:168:ex3:words:4:zh":"borrowed","grammar:168:ex3:words:4:note":"かりました","grammar:168:ex3:words:4:pos":"verb","grammar:168:ex3:points:0":"❓で: the place where the action of borrowing a book takes place (at the library).","grammar:168:ex3:points:1":"借りる: to borrow.","grammar:168:ex4:trans":"Please read this book.","grammar:168:ex4:structure":"〜を読んでください","grammar:168:ex4:words:0:zh":"this","grammar:168:ex4:words:0:pos":"pre-noun adjectival","grammar:168:ex4:words:1:zh":"book","grammar:168:ex4:words:1:note":"しょ","grammar:168:ex4:words:1:pos":"noun","grammar:168:ex4:words:2:zh":"(object marker)","grammar:168:ex4:words:2:pos":"particle","grammar:168:ex4:words:3:zh":"read","grammar:168:ex4:words:3:note":"よんで","grammar:168:ex4:words:3:pos":"verb","grammar:168:ex4:words:4:zh":"please","grammar:168:ex4:words:4:pos":"auxiliary verb","grammar:168:ex4:points:0":"読む→読んで (te-form)＋ください.","grammar:168:ex4:points:1":"この書: this book.","grammar:168:ex5:trans":"I'm writing a book.","grammar:168:ex5:structure":"〜を書いている","grammar:168:ex5:words:0:zh":"book","grammar:168:ex5:words:0:note":"しょ","grammar:168:ex5:words:0:pos":"noun","grammar:168:ex5:words:1:zh":"(object marker)","grammar:168:ex5:words:1:pos":"particle","grammar:168:ex5:words:2:zh":"am writing","grammar:168:ex5:words:2:note":"かいている","grammar:168:ex5:words:2:pos":"verb","grammar:168:ex5:points:0":"書を書く: to write a book.","grammar:168:ex5:points:1":"〜ている: ongoing action."},"170":{"example:170:exzh":"Is this all of it?","example:170:exzh2":"All of my work is finished.","example:170:exzh3":"How much is it in total?","example:170:exzh4":"I gave all the money in the wallet to my younger brother.","example:170:exzh5":"I need all the information.","grammar:170:ex:trans":"Is this everything?","grammar:170:ex:structure":"これが全部ですか","grammar:170:ex:explain":"This sentence uses 「これが全部ですか」 to check the scope, and the key is 「が」. Using 「が」 rather than 「は」 here carries a specifying, confirming tone: 「これが全部」 means this is all of it, stressing that what you see here is the whole amount. 「全部」 is a noun meaning all, the whole thing. The final 「か」 makes it a question. The whole sentence 「これが全部ですか」 means is this everything? With 「が」 the nuance is pinpointing and confirming—stronger than 「は」 in saying exactly these and nothing more.","grammar:170:ex:words:0:zh":"this","grammar:170:ex:words:0:pos":"pronoun","grammar:170:ex:words:1:zh":"(nominative)","grammar:170:ex:words:1:pos":"particle","grammar:170:ex:words:2:zh":"all","grammar:170:ex:words:2:note":"ぜんぶ","grammar:170:ex:words:2:pos":"noun","grammar:170:ex:words:3:zh":"is","grammar:170:ex:words:3:pos":"copula","grammar:170:ex:words:4:zh":"(question)","grammar:170:ex:words:4:pos":"particle","grammar:170:ex:points:0":"❓これが全部: this is all of it (が specifies).","grammar:170:ex:points:1":"全部: all, everything.","grammar:170:ex2:trans":"All my work is finished.","grammar:170:ex2:structure":"〜は全部〜ました","grammar:170:ex2:words:0:zh":"I","grammar:170:ex2:words:0:note":"わたし","grammar:170:ex2:words:0:pos":"pronoun","grammar:170:ex2:words:1:zh":"'s","grammar:170:ex2:words:1:pos":"particle","grammar:170:ex2:words:2:zh":"work","grammar:170:ex2:words:2:note":"しごと","grammar:170:ex2:words:2:pos":"noun","grammar:170:ex2:words:3:zh":"(topic)","grammar:170:ex2:words:3:pos":"particle","grammar:170:ex2:words:4:zh":"all","grammar:170:ex2:words:4:note":"ぜんぶ","grammar:170:ex2:words:4:pos":"adverb","grammar:170:ex2:words:5:zh":"done","grammar:170:ex2:words:5:note":"おわりました","grammar:170:ex2:words:5:pos":"verb","grammar:170:ex2:points:0":"全部: all (can also work as an adverb).","grammar:170:ex2:points:1":"終わる→終わりました (intransitive verb).","grammar:170:ex3:trans":"How much is it in total?","grammar:170:ex3:structure":"全部合わせていくらですか","grammar:170:ex3:words:0:zh":"all","grammar:170:ex3:words:0:note":"ぜんぶ","grammar:170:ex3:words:0:pos":"noun","grammar:170:ex3:words:1:zh":"total","grammar:170:ex3:words:1:note":"あわせて","grammar:170:ex3:words:1:pos":"verb","grammar:170:ex3:words:2:zh":"how much","grammar:170:ex3:words:2:pos":"question word","grammar:170:ex3:words:3:zh":"is","grammar:170:ex3:words:3:pos":"copula","grammar:170:ex3:words:4:zh":"(question)","grammar:170:ex3:words:4:pos":"particle","grammar:170:ex3:points:0":"全部合わせて: adding it all together.","grammar:170:ex3:points:1":"いくら: how much (money).","grammar:170:ex4:trans":"I gave my younger brother all the money in a wallet.","grammar:170:ex4:structure":"〜に〜を全部渡しました","grammar:170:ex4:words:0:zh":"younger brother","grammar:170:ex4:words:0:note":"おとうと","grammar:170:ex4:words:0:pos":"noun","grammar:170:ex4:words:1:zh":"(object)","grammar:170:ex4:words:1:pos":"particle","grammar:170:ex4:words:2:zh":"wallet","grammar:170:ex4:words:2:note":"さいふ","grammar:170:ex4:words:2:pos":"noun","grammar:170:ex4:words:3:zh":"'s","grammar:170:ex4:words:3:pos":"particle","grammar:170:ex4:words:4:zh":"money","grammar:170:ex4:words:4:note":"おかね","grammar:170:ex4:words:4:pos":"noun","grammar:170:ex4:words:5:zh":"(object)","grammar:170:ex4:words:5:pos":"particle","grammar:170:ex4:words:6:zh":"all","grammar:170:ex4:words:6:note":"ぜんぶ; used as an adverb","grammar:170:ex4:words:6:pos":"adverb","grammar:170:ex4:words:7:zh":"hand over","grammar:170:ex4:words:7:note":"わたしました; the past masu-form of 渡す","grammar:170:ex4:words:7:pos":"verb","grammar:170:ex4:points:0":"「お金を全部渡しました」: 全部 sits before the verb and works as an adverb meaning all of it, not a bit left, modifying 「渡しました」.","grammar:170:ex4:points:1":"The に in 「弟に」 marks the recipient (who it is given to), and the を in 「お金を」 marks the thing handed over.","grammar:170:ex4:points:2":"渡しました is the past masu-form of 渡す (to hand over), the polite way of saying gave.","grammar:170:ex5:trans":"I need all the information.","grammar:170:ex5:structure":"全部の〜が必要です","grammar:170:ex5:words:0:zh":"all","grammar:170:ex5:words:0:note":"ぜんぶ","grammar:170:ex5:words:0:pos":"noun","grammar:170:ex5:words:1:zh":"'s","grammar:170:ex5:words:1:pos":"particle","grammar:170:ex5:words:2:zh":"information","grammar:170:ex5:words:2:note":"じょうほう","grammar:170:ex5:words:2:pos":"noun","grammar:170:ex5:words:3:zh":"(object)","grammar:170:ex5:words:3:pos":"particle","grammar:170:ex5:words:4:zh":"necessary","grammar:170:ex5:words:4:note":"ひつよう","grammar:170:ex5:words:4:pos":"na-adjective","grammar:170:ex5:words:5:zh":"(polite form)","grammar:170:ex5:words:5:pos":"copula","grammar:170:ex5:points:0":"全部の情報: all the information.","grammar:170:ex5:points:1":"「〜が必要です」: need …"},"171":{"example:171:exzh":"I got new information.","example:171:exzh2":"Please check the information.","example:171:exzh3":"He has useful information.","example:171:exzh4":"Is that information correct?","example:171:exzh5":"I'm looking for information."},"172":{"example:172:exzh":"An incident was caused.","example:172:exzh2":"Cause a problem.","example:172:exzh3":"This is causing confusion.","example:172:exzh4":"He causes problems.","example:172:exzh5":"It's necessary to make something happen.","grammar:172:ex:trans":"Caused an incident.","grammar:172:ex:structure":"〜を起こした","grammar:172:ex:explain":"The key point in this sentence is the transitive verb 「起こす」. 「起こす」 means \"to cause, to wake (someone), to help (someone) up\" and is a transitive verb that takes its object with 「を」; 「事件を起こす」 = \"to cause an incident.\" Its intransitive counterparts are 「起きる」 (to get up, to happen) and 「起こる」 (to happen). These three are often tested together and easily confused: the transitive 「起こす」 carries a sense of human agency. The plain past form is 「起こした」. The whole sentence 「事件を起こした」 = \"caused an incident\"—remember to distinguish the transitive/intransitive pairs.","grammar:172:ex:words:0:zh":"incident","grammar:172:ex:words:0:note":"じけん","grammar:172:ex:words:0:pos":"noun","grammar:172:ex:words:1:zh":"(object marker)","grammar:172:ex:words:1:pos":"particle","grammar:172:ex:words:2:zh":"caused","grammar:172:ex:words:2:note":"おこした","grammar:172:ex:words:2:pos":"verb","grammar:172:ex:points:0":"❗起こす (transitive verb, to cause / to wake); vs 起きる／起こる (intransitive verbs).","grammar:172:ex:points:1":"事件を起こす: to cause an incident.","grammar:172:ex2:trans":"To cause a problem.","grammar:172:ex2:structure":"〜を起こす","grammar:172:ex2:words:0:zh":"problem","grammar:172:ex2:words:0:note":"もんだい","grammar:172:ex2:words:0:pos":"noun","grammar:172:ex2:words:1:zh":"(object marker)","grammar:172:ex2:words:1:pos":"particle","grammar:172:ex2:words:2:zh":"to cause","grammar:172:ex2:words:2:note":"おこす","grammar:172:ex2:words:2:pos":"verb","grammar:172:ex2:points:0":"❗問題を起こす: to cause trouble, to get into trouble.","grammar:172:ex2:points:1":"起こす: to cause.","grammar:172:ex3:trans":"This is causing confusion.","grammar:172:ex3:structure":"〜を起こしています","grammar:172:ex3:words:0:zh":"this","grammar:172:ex3:words:0:pos":"pronoun","grammar:172:ex3:words:1:zh":"(topic)","grammar:172:ex3:words:1:pos":"particle","grammar:172:ex3:words:2:zh":"confusion","grammar:172:ex3:words:2:note":"こんらん","grammar:172:ex3:words:2:pos":"noun","grammar:172:ex3:words:3:zh":"(object marker)","grammar:172:ex3:words:3:pos":"particle","grammar:172:ex3:words:4:zh":"is causing","grammar:172:ex3:words:4:note":"おこしています","grammar:172:ex3:words:4:pos":"verb","grammar:172:ex3:points:0":"混乱を起こす: to cause confusion.","grammar:172:ex3:points:1":"〜ている: (continuing) state.","grammar:172:ex4:trans":"He causes trouble.","grammar:172:ex4:structure":"〜は問題を起こす","grammar:172:ex4:explain":"「彼は」 presents him as the topic, and 「問題を」 marks the thing he causes. Here 「起こす」 does not mean waking someone up but making a problem happen. The dictionary form can describe a habit or a future action; with no further context, you can't conclude this is a past event that has already happened.","grammar:172:ex4:words:0:zh":"he","grammar:172:ex4:words:0:note":"かれ","grammar:172:ex4:words:0:pos":"pronoun","grammar:172:ex4:words:1:zh":"(topic)","grammar:172:ex4:words:1:pos":"particle","grammar:172:ex4:words:2:zh":"problem, trouble","grammar:172:ex4:words:2:note":"もんだい","grammar:172:ex4:words:2:pos":"noun","grammar:172:ex4:words:3:zh":"(object)","grammar:172:ex4:words:3:pos":"particle","grammar:172:ex4:words:4:zh":"to cause, to stir up","grammar:172:ex4:words:4:note":"おこす","grammar:172:ex4:words:4:pos":"verb","grammar:172:ex4:points:0":"「問題を起こす」 is a common collocation meaning to cause a problem or stir up trouble.","grammar:172:ex4:points:1":"「起こす」 is a transitive verb; its intransitive counterpart 「起こる」 is used in 「問題が起こる」.","grammar:172:ex5:trans":"There's a need to make something happen.","grammar:172:ex5:structure":"〜を起こす必要があります","grammar:172:ex5:words:0:zh":"what","grammar:172:ex5:words:0:note":"なにか","grammar:172:ex5:words:0:pos":"pronoun","grammar:172:ex5:words:1:zh":"(object marker)","grammar:172:ex5:words:1:pos":"particle","grammar:172:ex5:words:2:zh":"to cause","grammar:172:ex5:words:2:note":"おこす","grammar:172:ex5:words:2:pos":"verb","grammar:172:ex5:words:3:zh":"necessary","grammar:172:ex5:words:3:note":"ひつよう","grammar:172:ex5:words:3:pos":"noun","grammar:172:ex5:words:4:zh":"(nominative)","grammar:172:ex5:words:4:pos":"particle","grammar:172:ex5:words:5:zh":"there is / are","grammar:172:ex5:words:5:pos":"verb","grammar:172:ex5:points:0":"❗行動を起こす: to take action (idiomatic).","grammar:172:ex5:points:1":"〜必要があります：it is necessary to…"},"173":{"example:173:exzh":"I'll cook a meal.","example:173:exzh2":"She's making sweets.","example:173:exzh3":"I'll create a new project.","example:173:exzh4":"I like making furniture.","example:173:exzh5":"I've painted a picture before.","grammar:173:ex:trans":"I'll make a dish.","grammar:173:ex:structure":"〜を作ります","grammar:173:ex:explain":"This is a transitive sentence with object＋を＋verbます. 「料理」 means cooking, a dish. 「を」 marks the thing being made. The verb 「作る」 ends in 「る」 but is a godan verb; its polite form is 「作ります」, and 「料理を作る」 means to make a dish. The whole sentence 「料理を作ります」 means I'll make a dish. Note that 「作る」 is a godan verb (the sound before る is an あ-row sound); in the polite form る becomes り plus ます, so don't mistake it for an ichidan verb and simply drop る.","grammar:173:ex:words:0:zh":"dish / cuisine","grammar:173:ex:words:0:note":"りょうり","grammar:173:ex:words:0:pos":"noun","grammar:173:ex:words:1:zh":"(object marker)","grammar:173:ex:words:1:pos":"particle","grammar:173:ex:words:2:zh":"do","grammar:173:ex:words:2:note":"つくります","grammar:173:ex:words:2:pos":"verb","grammar:173:ex:points:0":"料理を作る: to make a dish.","grammar:173:ex:points:1":"作る→作ります.","grammar:173:ex2:trans":"She is making sweets.","grammar:173:ex2:structure":"〜を作っています","grammar:173:ex2:words:0:zh":"she","grammar:173:ex2:words:0:note":"かのじょ","grammar:173:ex2:words:0:pos":"pronoun","grammar:173:ex2:words:1:zh":"(topic)","grammar:173:ex2:words:1:pos":"particle","grammar:173:ex2:words:2:zh":"sweets","grammar:173:ex2:words:2:note":"おかし","grammar:173:ex2:words:2:pos":"noun","grammar:173:ex2:words:3:zh":"(object marker)","grammar:173:ex2:words:3:pos":"particle","grammar:173:ex2:words:4:zh":"is doing","grammar:173:ex2:words:4:note":"つくっています","grammar:173:ex2:words:4:pos":"verb","grammar:173:ex2:points:0":"お菓子: sweets, snacks.","grammar:173:ex2:points:1":"〜ている: ongoing action.","grammar:173:ex3:trans":"I'll create a new project.","grammar:173:ex3:structure":"〜を作ります","grammar:173:ex3:words:0:zh":"new","grammar:173:ex3:words:0:note":"あたらしい","grammar:173:ex3:words:0:pos":"adjective","grammar:173:ex3:words:1:zh":"project","grammar:173:ex3:words:1:note":"loanword","grammar:173:ex3:words:1:pos":"noun","grammar:173:ex3:words:2:zh":"(object marker)","grammar:173:ex3:words:2:pos":"particle","grammar:173:ex3:words:3:zh":"do","grammar:173:ex3:words:3:note":"つくります","grammar:173:ex3:words:3:pos":"verb","grammar:173:ex3:points:0":"プロジェクトを作る: to create a project.","grammar:173:ex3:points:1":"新しい: new (i-adjective).","grammar:173:ex4:trans":"I like making furniture.","grammar:173:ex4:structure":"〜のが好きです","grammar:173:ex4:words:0:zh":"furniture","grammar:173:ex4:words:0:note":"かぐ","grammar:173:ex4:words:0:pos":"noun","grammar:173:ex4:words:1:zh":"(object marker)","grammar:173:ex4:words:1:pos":"particle","grammar:173:ex4:words:2:zh":"do","grammar:173:ex4:words:2:note":"つくる","grammar:173:ex4:words:2:pos":"verb","grammar:173:ex4:words:3:zh":"(nominalizer)","grammar:173:ex4:words:3:pos":"particle","grammar:173:ex4:words:4:zh":"(object)","grammar:173:ex4:words:4:pos":"particle","grammar:173:ex4:words:5:zh":"to like","grammar:173:ex4:words:5:note":"すき","grammar:173:ex4:words:5:pos":"na-adjective","grammar:173:ex4:words:6:zh":"(polite form)","grammar:173:ex4:words:6:pos":"copula","grammar:173:ex4:points:0":"〜のが好き: to like doing…","grammar:173:ex4:points:1":"家具を作る: to make furniture.","grammar:173:ex5:trans":"I've drawn a picture before.","grammar:173:ex5:structure":"〜たことがあります","grammar:173:ex5:words:0:zh":"picture","grammar:173:ex5:words:0:note":"え","grammar:173:ex5:words:0:pos":"noun","grammar:173:ex5:words:1:zh":"(object marker)","grammar:173:ex5:words:1:pos":"particle","grammar:173:ex5:words:2:zh":"did","grammar:173:ex5:words:2:note":"つくった","grammar:173:ex5:words:2:pos":"verb","grammar:173:ex5:words:3:zh":"(experience)","grammar:173:ex5:words:3:pos":"noun","grammar:173:ex5:words:4:zh":"(nominative)","grammar:173:ex5:words:4:pos":"particle","grammar:173:ex5:words:5:zh":"there is / are","grammar:173:ex5:words:5:pos":"verb","grammar:173:ex5:points:0":"〜たことがあります: have (done)… before (experience).","grammar:173:ex5:points:1":"（For pictures, 描く is more natural; here 作る is used.）","exam:173:zh":"I plan to make a cake using eggs, milk, and flour.","exam:173:why":"To make a cake from ingredients you use 「作る」. 「食べる」 means eating a cake that is already made, so it can't express making something from ingredients."},"174":{"example:174:exzh":"I have a headache.","example:174:exzh2":"He's smart.","example:174:exzh3":"You need to use your head.","example:174:exzh4":"Shake your head to mean no.","example:174:exzh5":"He has lots of ideas in his head.","grammar:174:ex:trans":"I have a headache.","grammar:174:ex:structure":"頭が痛いです","grammar:174:ex:explain":"This sentence is about feeling unwell, and 「が」 is the key. The body part is treated as the subject of the sensation and marked with 「が」; 「頭が痛い」 means the same as 「頭痛」, and 「を」 is not used. 「頭（あたま）」 means head, and 「痛い」 is an i-adjective; adding 「です」 makes it polite. The whole sentence 「頭が痛いです」 means I have a headache. This is the fixed pattern 「(body part)が＋痛い」; the same logic applies to 「お腹が痛い」 and 「歯が痛い」, so you always use 「が」 to say which part hurts.","grammar:174:ex:words:0:zh":"head","grammar:174:ex:words:0:note":"あたま","grammar:174:ex:words:0:pos":"noun","grammar:174:ex:words:1:zh":"(nominative)","grammar:174:ex:words:1:pos":"particle","grammar:174:ex:words:2:zh":"hurt / painful","grammar:174:ex:words:2:note":"いたい","grammar:174:ex:words:2:pos":"adjective","grammar:174:ex:words:3:zh":"(polite form)","grammar:174:ex:words:3:pos":"copula","grammar:174:ex:points:0":"Body part ＋ が痛い: something hurts.","grammar:174:ex:points:1":"頭（あたま）：head.","grammar:174:ex2:trans":"He is smart.","grammar:174:ex2:structure":"〜は頭が良いです","grammar:174:ex2:words:0:zh":"he","grammar:174:ex2:words:0:note":"かれ","grammar:174:ex2:words:0:pos":"pronoun","grammar:174:ex2:words:1:zh":"(topic)","grammar:174:ex2:words:1:pos":"particle","grammar:174:ex2:words:2:zh":"head","grammar:174:ex2:words:2:note":"あたま","grammar:174:ex2:words:2:pos":"noun","grammar:174:ex2:words:3:zh":"(nominative)","grammar:174:ex2:words:3:pos":"particle","grammar:174:ex2:words:4:zh":"good","grammar:174:ex2:words:4:note":"いい","grammar:174:ex2:words:4:pos":"adjective","grammar:174:ex2:words:5:zh":"(polite form)","grammar:174:ex2:words:5:pos":"copula","grammar:174:ex2:points:0":"頭が良い：smart (idiomatic; literally having a good head).","grammar:174:ex2:points:1":"は marks the topic plus が for the (body) part — two particles working together.","grammar:174:ex3:trans":"You need to use your head.","grammar:174:ex3:structure":"〜必要があります","grammar:174:ex3:words:0:zh":"head","grammar:174:ex3:words:0:note":"あたま","grammar:174:ex3:words:0:pos":"noun","grammar:174:ex3:words:1:zh":"(object marker)","grammar:174:ex3:words:1:pos":"particle","grammar:174:ex3:words:2:zh":"use","grammar:174:ex3:words:2:note":"つかう","grammar:174:ex3:words:2:pos":"verb","grammar:174:ex3:words:3:zh":"necessary","grammar:174:ex3:words:3:note":"ひつよう","grammar:174:ex3:words:3:pos":"noun","grammar:174:ex3:words:4:zh":"(nominative)","grammar:174:ex3:words:4:pos":"particle","grammar:174:ex3:words:5:zh":"there is / are","grammar:174:ex3:words:5:pos":"verb","grammar:174:ex3:points:0":"頭を使う：to use one's head / to think (idiomatic).","grammar:174:ex3:points:1":"〜必要があります：it is necessary to…","grammar:174:ex4:trans":"Shaking your head means no.","grammar:174:ex4:structure":"頭を振って〜します","grammar:174:ex4:words:0:zh":"head","grammar:174:ex4:words:0:note":"あたま","grammar:174:ex4:words:0:pos":"noun","grammar:174:ex4:words:1:zh":"(object marker)","grammar:174:ex4:words:1:pos":"particle","grammar:174:ex4:words:2:zh":"shake","grammar:174:ex4:words:2:note":"ふって","grammar:174:ex4:words:2:pos":"verb","grammar:174:ex4:words:3:zh":"denial","grammar:174:ex4:words:3:note":"ひていします","grammar:174:ex4:words:3:pos":"verb","grammar:174:ex4:points:0":"頭を振る：to shake one's head.","grammar:174:ex4:points:1":"振る→振って (te-form linking to the next action).","grammar:174:ex5:trans":"He has lots of ideas in his head.","grammar:174:ex5:structure":"〜には〜がたくさんあります","grammar:174:ex5:words:0:zh":"he","grammar:174:ex5:words:0:note":"かれ","grammar:174:ex5:words:0:pos":"pronoun","grammar:174:ex5:words:1:zh":"'s","grammar:174:ex5:words:1:pos":"particle","grammar:174:ex5:words:2:zh":"head","grammar:174:ex5:words:2:note":"あたま","grammar:174:ex5:words:2:pos":"noun","grammar:174:ex5:words:3:zh":"(location of existence)","grammar:174:ex5:words:3:pos":"particle","grammar:174:ex5:words:4:zh":"(contrast)","grammar:174:ex5:words:4:pos":"particle","grammar:174:ex5:words:5:zh":"ideas","grammar:174:ex5:words:5:note":"loanword","grammar:174:ex5:words:5:pos":"noun","grammar:174:ex5:words:6:zh":"(nominative)","grammar:174:ex5:words:6:pos":"particle","grammar:174:ex5:words:7:zh":"a lot","grammar:174:ex5:words:7:pos":"adverb","grammar:174:ex5:words:8:zh":"there is / are","grammar:174:ex5:words:8:pos":"verb","grammar:174:ex5:points:0":"頭には：in his head (には = に + は).","grammar:174:ex5:points:1":"〜がたくさんある：there are many…","exam:174:zh":"It was cold, so I put a hat on my head.","exam:174:why":"A hat goes on your 「頭」. 「手」 is a body part too, but what you wear on your hands to keep warm is gloves."},"175":{"example:175:exzh":"He has a gun.","example:175:exzh2":"The use of guns has become an issue.","example:175:exzh3":"Let's discuss gun control.","example:175:exzh4":"He fired a gun.","example:175:exzh5":"A gun was involved in this incident."},"176":{"example:176:exzh":"That incident had a major impact.","example:176:exzh2":"News about the incident was reported.","example:176:exzh3":"The incident was resolved quickly.","example:176:exzh4":"He is involved in that incident.","example:176:exzh5":"We are investigating the incident."},"180":{"example:180:exzh":"I received a book.","example:180:exzh2":"I got a letter from him.","example:180:exzh3":"I'm happy to receive a souvenir.","example:180:exzh4":"I got help from a friend.","example:180:exzh5":"So I can get money?","grammar:180:ex:trans":"I received a book.","grammar:180:ex:structure":"〜をもらいました","grammar:180:ex:explain":"This sentence uses the giving-and-receiving verb 「もらう」. 「もらう」 means \"(I) receive, get (something from someone)\"; the direction of the action is someone giving to me and me receiving. The thing received is marked with 「を」; 「本をもらう」 = \"to receive a book.\" The past polite form is 「もらいました」. The whole sentence 「本をもらいました」 = \"I received a book.\" The giving-and-receiving verbs (あげる／くれる／もらう) express the direction of giving and receiving; 「もらう」 takes the receiver's perspective and must be distinguished from 「くれる」.","grammar:180:ex:words:0:zh":"book","grammar:180:ex:words:0:note":"ほん","grammar:180:ex:words:0:pos":"noun","grammar:180:ex:words:1:zh":"(object marker)","grammar:180:ex:words:1:pos":"particle","grammar:180:ex:words:2:zh":"received","grammar:180:ex:words:2:pos":"verb","grammar:180:ex:points:0":"❗もらう: to get, to receive (from someone) (giving/receiving verb).","grammar:180:ex:points:1":"本をもらう: to receive a book.","grammar:180:ex2:trans":"I received a letter from him.","grammar:180:ex2:structure":"〜から〜をもらった","grammar:180:ex2:words:0:zh":"he","grammar:180:ex2:words:0:note":"かれ","grammar:180:ex2:words:0:pos":"pronoun","grammar:180:ex2:words:1:zh":"from","grammar:180:ex2:words:1:pos":"particle","grammar:180:ex2:words:2:zh":"letter","grammar:180:ex2:words:2:note":"てがみ","grammar:180:ex2:words:2:pos":"noun","grammar:180:ex2:words:3:zh":"(object marker)","grammar:180:ex2:words:3:pos":"particle","grammar:180:ex2:words:4:zh":"received","grammar:180:ex2:words:4:pos":"verb","grammar:180:ex2:points:0":"❗〜からもらう: receive from… (から marks the giver).","grammar:180:ex2:points:1":"手紙をもらう: to receive a letter.","grammar:180:ex3:trans":"I'm happy to get a souvenir.","grammar:180:ex3:structure":"〜をもらって嬉しい","grammar:180:ex3:words:0:zh":"souvenir","grammar:180:ex3:words:0:note":"おみやげ","grammar:180:ex3:words:0:pos":"noun","grammar:180:ex3:words:1:zh":"(object marker)","grammar:180:ex3:words:1:pos":"particle","grammar:180:ex3:words:2:zh":"receiving","grammar:180:ex3:words:2:pos":"verb","grammar:180:ex3:words:3:zh":"be happy","grammar:180:ex3:words:3:note":"うれしい","grammar:180:ex3:words:3:pos":"adjective","grammar:180:ex3:points:0":"❗お土産: souvenir, local specialty.","grammar:180:ex3:points:1":"〜てもらって嬉しい: happy to receive …","grammar:180:ex4:trans":"I got help from a friend.","grammar:180:ex4:structure":"〜に〜てもらいました","grammar:180:ex4:words:0:zh":"friend","grammar:180:ex4:words:0:note":"ともだち","grammar:180:ex4:words:0:pos":"noun","grammar:180:ex4:words:1:zh":"(giver)","grammar:180:ex4:words:1:pos":"particle","grammar:180:ex4:words:2:zh":"help","grammar:180:ex4:words:2:note":"たすけて","grammar:180:ex4:words:2:pos":"verb","grammar:180:ex4:words:3:zh":"(have someone do something for me)","grammar:180:ex4:words:3:pos":"auxiliary verb","grammar:180:ex4:points:0":"❗〜てもらう: to have (someone) do … for me (助けてもらう = to get help).","grammar:180:ex4:points:1":"友達に: to a friend (に = the giver).","grammar:180:ex5:trans":"Can I get money?","grammar:180:ex5:structure":"〜をもらえるんですか","grammar:180:ex5:words:0:zh":"money","grammar:180:ex5:words:0:note":"おかね","grammar:180:ex5:words:0:pos":"noun","grammar:180:ex5:words:1:zh":"(object marker)","grammar:180:ex5:words:1:pos":"particle","grammar:180:ex5:words:2:zh":"can receive","grammar:180:ex5:words:2:pos":"verb","grammar:180:ex5:words:3:zh":"(explanation)","grammar:180:ex5:words:3:pos":"set phrase","grammar:180:ex5:words:4:zh":"(question)","grammar:180:ex5:words:4:pos":"particle","grammar:180:ex5:points:0":"❗もらえる: can get (potential form of もらう).","grammar:180:ex5:points:1":"〜んですか: (seeking confirmation) …?","exam:180:zh":"A friend is going to give me this book, so I don't need to buy it.","exam:180:why":"「友達からもらう」 means to receive something from a friend. 「あげる」 means to give to someone else, so the direction of giving is reversed."},"183":{"example:183:exzh":"I'm very happy.","example:183:exzh2":"This is very important.","example:183:exzh3":"It was a very cold day.","example:183:exzh4":"Really tasty food.","example:183:exzh5":"She's very kind.","grammar:183:ex:trans":"I'm very happy.","grammar:183:ex:structure":"とても〜です","grammar:183:ex:explain":"This sentence uses the degree adverb 「とても」 with an i-adjective. 「とても」 means very or extremely and modifies an adjective to strengthen the degree. 「嬉しい」 is an i-adjective for a subjective feeling, meaning happy; it takes 「です」 directly to become polite. The whole sentence 「とても嬉しいです」 means I'm very happy. 「とても」 is the most common degree adverb — put it before an adjective to say very…; note that it usually goes with affirmative statements, and for negatives you normally switch to 「あまり〜ない」.","grammar:183:ex:words:0:zh":"extremely","grammar:183:ex:words:0:pos":"adverb","grammar:183:ex:words:1:zh":"happy","grammar:183:ex:words:1:note":"うれしい","grammar:183:ex:words:1:pos":"adjective","grammar:183:ex:words:2:zh":"(polite form)","grammar:183:ex:words:2:pos":"copula","grammar:183:ex:points:0":"とても：very (degree adverb).","grammar:183:ex:points:1":"嬉しい：happy (i-adjective).","grammar:183:ex2:trans":"This is very important.","grammar:183:ex2:structure":"〜はとても〜です","grammar:183:ex2:words:0:zh":"this","grammar:183:ex2:words:0:pos":"pronoun","grammar:183:ex2:words:1:zh":"(topic)","grammar:183:ex2:words:1:pos":"particle","grammar:183:ex2:words:2:zh":"extremely","grammar:183:ex2:words:2:pos":"adverb","grammar:183:ex2:words:3:zh":"important","grammar:183:ex2:words:3:note":"じゅうよう","grammar:183:ex2:words:3:pos":"na-adjective","grammar:183:ex2:words:4:zh":"(polite form)","grammar:183:ex2:words:4:pos":"copula","grammar:183:ex2:points:0":"とても重要：very important.","grammar:183:ex2:points:1":"重要：na-adjective.","grammar:183:ex3:trans":"It was a very cold day.","grammar:183:ex3:structure":"とても〜日でした","grammar:183:ex3:words:0:zh":"extremely","grammar:183:ex3:words:0:pos":"adverb","grammar:183:ex3:words:1:zh":"cold","grammar:183:ex3:words:1:note":"さむい","grammar:183:ex3:words:1:pos":"adjective","grammar:183:ex3:words:2:zh":"day","grammar:183:ex3:words:2:note":"ひ","grammar:183:ex3:words:2:pos":"noun","grammar:183:ex3:words:3:zh":"(past) was","grammar:183:ex3:words:3:pos":"copula","grammar:183:ex3:points:0":"寒い日：a cold day (i-adjective + noun).","grammar:183:ex3:points:1":"でした：was (the past form of です).","grammar:183:ex4:trans":"Very delicious food.","grammar:183:ex4:structure":"とても〜料理","grammar:183:ex4:words:0:zh":"extremely","grammar:183:ex4:words:0:pos":"adverb","grammar:183:ex4:words:1:zh":"delicious","grammar:183:ex4:words:1:note":"おいしい","grammar:183:ex4:words:1:pos":"adjective","grammar:183:ex4:words:2:zh":"dish / cuisine","grammar:183:ex4:words:2:note":"りょうり","grammar:183:ex4:words:2:pos":"noun","grammar:183:ex4:points:0":"美味しい：delicious (i-adjective).","grammar:183:ex4:points:1":"とても美味しい料理：very delicious food.","grammar:183:ex5:trans":"She is very kind.","grammar:183:ex5:structure":"〜はとても〜です","grammar:183:ex5:words:0:zh":"she","grammar:183:ex5:words:0:note":"かのじょ","grammar:183:ex5:words:0:pos":"pronoun","grammar:183:ex5:words:1:zh":"(topic)","grammar:183:ex5:words:1:pos":"particle","grammar:183:ex5:words:2:zh":"extremely","grammar:183:ex5:words:2:pos":"adverb","grammar:183:ex5:words:3:zh":"kind","grammar:183:ex5:words:3:note":"やさしい","grammar:183:ex5:words:3:pos":"adjective","grammar:183:ex5:words:4:zh":"(polite form)","grammar:183:ex5:words:4:pos":"copula","grammar:183:ex5:points:0":"優しい：gentle / kind.","grammar:183:ex5:points:1":"とても modifies 優しい.","exam:183:zh":"This box is extremely heavy — even two adults can't lift it.","exam:183:why":"If even two adults can't lift it, the degree is high, so 「とても」 is the answer. 「ちょっと」 means a little, which doesn't match the degree here."},"184":{"example:184:exzh":"I got in touch with a friend.","example:184:exzh2":"Communication about work is delayed.","example:184:exzh3":"Please get in touch by phone.","example:184:exzh4":"Please tell me your contact details.","example:184:exzh5":"You can also get in touch by email.","grammar:184:ex:trans":"I got in touch with a friend.","grammar:184:ex:structure":"〜と連絡を取りました","grammar:184:ex:explain":"This sentence uses the set collocation 「連絡を取る」. 「連絡を取る」 is the fixed way to say get in touch or contact someone; the verb is 「取る」, and 「を」 marks its object 「連絡」. 「〜と」 marks the other person: 「友達と連絡を取る」 means to get in touch with a friend. The verb 「取る」 is a godan (u-) verb, and its past polite form is 「取りました」. The whole sentence 「友達と連絡を取りました」 means I got in touch with a friend. Learn 「連絡を取る」 as one chunk, with 「と」 pointing to the person you contact.","grammar:184:ex:words:0:zh":"friend","grammar:184:ex:words:0:note":"ともだち","grammar:184:ex:words:0:pos":"noun","grammar:184:ex:words:1:zh":"with","grammar:184:ex:words:1:pos":"particle","grammar:184:ex:words:2:zh":"contact","grammar:184:ex:words:2:note":"れんらく","grammar:184:ex:words:2:pos":"noun","grammar:184:ex:words:3:zh":"(object marker)","grammar:184:ex:words:3:pos":"particle","grammar:184:ex:words:4:zh":"got","grammar:184:ex:words:4:note":"とりました","grammar:184:ex:words:4:pos":"verb","grammar:184:ex:points:0":"連絡を取る：to get in touch (idiomatic).","grammar:184:ex:points:1":"〜と連絡を取る：to get in touch with…","grammar:184:ex2:trans":"Contact about work is delayed.","grammar:184:ex2:structure":"〜が遅れています","grammar:184:ex2:words:0:zh":"work","grammar:184:ex2:words:0:note":"しごと","grammar:184:ex2:words:0:pos":"noun","grammar:184:ex2:words:1:zh":"'s","grammar:184:ex2:words:1:pos":"particle","grammar:184:ex2:words:2:zh":"contact","grammar:184:ex2:words:2:note":"れんらく","grammar:184:ex2:words:2:pos":"noun","grammar:184:ex2:words:3:zh":"(nominative)","grammar:184:ex2:words:3:pos":"particle","grammar:184:ex2:words:4:zh":"is delayed","grammar:184:ex2:words:4:note":"おくれています","grammar:184:ex2:words:4:pos":"verb","grammar:184:ex2:points:0":"仕事の連絡：work-related contact.","grammar:184:ex2:points:1":"遅れる：to be delayed (intransitive verb, with the subject marked by が).","grammar:184:ex3:trans":"Please contact me by phone.","grammar:184:ex3:structure":"〜で連絡してください","grammar:184:ex3:words:0:zh":"phone call","grammar:184:ex3:words:0:note":"でんわ","grammar:184:ex3:words:0:pos":"noun","grammar:184:ex3:words:1:zh":"(means)","grammar:184:ex3:words:1:pos":"particle","grammar:184:ex3:words:2:zh":"contact","grammar:184:ex3:words:2:note":"れんらくして","grammar:184:ex3:words:2:pos":"verb","grammar:184:ex3:words:3:zh":"please","grammar:184:ex3:words:3:pos":"auxiliary verb","grammar:184:ex3:points:0":"❓で：marks the means or tool (by phone).","grammar:184:ex3:points:1":"連絡する→連絡して＋ください。","grammar:184:ex4:trans":"Please tell me your contact details.","grammar:184:ex4:structure":"〜を教えてください","grammar:184:ex4:words:0:zh":"contact details","grammar:184:ex4:words:0:note":"れんらくさき","grammar:184:ex4:words:0:pos":"noun","grammar:184:ex4:words:1:zh":"(object marker)","grammar:184:ex4:words:1:pos":"particle","grammar:184:ex4:words:2:zh":"tell","grammar:184:ex4:words:2:note":"おしえて","grammar:184:ex4:words:2:pos":"verb","grammar:184:ex4:words:3:zh":"please","grammar:184:ex4:words:3:pos":"auxiliary verb","grammar:184:ex4:points:0":"連絡先：contact details / address.","grammar:184:ex4:points:1":"教える→教えて＋ください。","grammar:184:ex5:trans":"You can also get in touch by email.","grammar:184:ex5:structure":"〜でも連絡できます","grammar:184:ex5:words:0:zh":"email","grammar:184:ex5:words:0:note":"loanword","grammar:184:ex5:words:0:pos":"noun","grammar:184:ex5:words:1:zh":"also / even","grammar:184:ex5:words:1:pos":"particle","grammar:184:ex5:words:2:zh":"can contact","grammar:184:ex5:words:2:note":"れんらくできます","grammar:184:ex5:words:2:pos":"verb","grammar:184:ex5:points:0":"〜でも：also with… / even using… (で + も).","grammar:184:ex5:points:1":"連絡できる：can contact (potential form)."},"186":{"example:186:exzh":"That's another problem.","example:186:exzh2":"I went to another place.","example:186:exzh3":"There's a special reason.","example:186:exzh4":"I decided to take a different path from him.","example:186:exzh5":"A different perspective is needed.","grammar:186:ex:trans":"That's a different issue.","grammar:186:ex:structure":"別の〜です","grammar:186:ex:explain":"This sentence uses 「別の〜」 to mean another. 「別（べつ）」 means other, different; adding 「の」 lets it modify a noun, so 「別の問題」 means another issue or a different issue. 「それは⋯です」 is the frame for a statement of judgment, with 「は」 presenting the topic. The whole sentence 「それは別の問題です」 means that's a different issue. 「別の」 is often used to set a topic apart from what is right in front of you, as in 「別の日」 (another day) or 「別の人」 (someone else) — a very handy modifier.","grammar:186:ex:words:0:zh":"that","grammar:186:ex:words:0:pos":"pronoun","grammar:186:ex:words:1:zh":"(topic)","grammar:186:ex:words:1:pos":"particle","grammar:186:ex:words:2:zh":"different","grammar:186:ex:words:2:note":"べつ","grammar:186:ex:words:2:pos":"noun","grammar:186:ex:words:3:zh":"'s","grammar:186:ex:words:3:pos":"particle","grammar:186:ex:words:4:zh":"problem","grammar:186:ex:words:4:note":"もんだい","grammar:186:ex:words:4:pos":"noun","grammar:186:ex:words:5:zh":"is","grammar:186:ex:words:5:pos":"copula","grammar:186:ex:points:0":"別の＋noun：another…","grammar:186:ex:points:1":"別（べつ）：other, different.","grammar:186:ex2:trans":"I went to another place.","grammar:186:ex2:structure":"別の〜に行きました","grammar:186:ex2:words:0:zh":"different","grammar:186:ex2:words:0:note":"べつ","grammar:186:ex2:words:0:pos":"noun","grammar:186:ex2:words:1:zh":"'s","grammar:186:ex2:words:1:pos":"particle","grammar:186:ex2:words:2:zh":"place","grammar:186:ex2:words:2:note":"ばしょ","grammar:186:ex2:words:2:pos":"noun","grammar:186:ex2:words:3:zh":"(destination)","grammar:186:ex2:words:3:pos":"particle","grammar:186:ex2:words:4:zh":"went","grammar:186:ex2:words:4:note":"いきました","grammar:186:ex2:words:4:pos":"verb","grammar:186:ex2:points:0":"別の場所：another place.","grammar:186:ex2:points:1":"に：destination of movement.","grammar:186:ex3:trans":"There is a special reason.","grammar:186:ex3:structure":"〜な〜の理由があります","grammar:186:ex3:words:0:zh":"special","grammar:186:ex3:words:0:note":"とくべつ","grammar:186:ex3:words:0:pos":"na-adjective","grammar:186:ex3:words:1:zh":"(attributive form)","grammar:186:ex3:words:1:pos":"auxiliary verb","grammar:186:ex3:words:2:zh":"different","grammar:186:ex3:words:2:note":"べつ","grammar:186:ex3:words:2:pos":"noun","grammar:186:ex3:words:3:zh":"'s","grammar:186:ex3:words:3:pos":"particle","grammar:186:ex3:words:4:zh":"reason","grammar:186:ex3:words:4:note":"りゆう","grammar:186:ex3:words:4:pos":"noun","grammar:186:ex3:words:5:zh":"(nominative)","grammar:186:ex3:words:5:pos":"particle","grammar:186:ex3:words:6:zh":"there is / are","grammar:186:ex3:words:6:pos":"verb","grammar:186:ex3:points:0":"特別な：special (な + noun).","grammar:186:ex3:points:1":"理由がある：there is a reason.","grammar:186:ex4:trans":"I decided to walk a different path from him.","grammar:186:ex4:structure":"〜とは別の〜を + verb dictionary form + ことにした","grammar:186:ex4:explain":"In 「彼とは」, 「と」 marks the person being compared and 「は」 strengthens the contrast, so it does not mean walking together with him. 「別の道を歩く」 can mean walking a different actual road, or figuratively choosing a different direction in life. 「ことにした」 shows the speaker has made this decision, but does not guarantee the action has been carried out.","grammar:186:ex4:words:0:zh":"he","grammar:186:ex4:words:0:note":"かれ","grammar:186:ex4:words:0:pos":"pronoun","grammar:186:ex4:words:1:zh":"(the person being compared or distinguished)","grammar:186:ex4:words:1:pos":"particle","grammar:186:ex4:words:2:zh":"(contrast, emphasis)","grammar:186:ex4:words:2:pos":"particle","grammar:186:ex4:words:3:zh":"different, another","grammar:186:ex4:words:3:note":"べつ","grammar:186:ex4:words:3:pos":"noun","grammar:186:ex4:words:4:zh":"(connects a modifier and a noun)","grammar:186:ex4:words:4:pos":"particle","grammar:186:ex4:words:5:zh":"road, direction in life","grammar:186:ex4:words:5:note":"みち","grammar:186:ex4:words:5:pos":"noun","grammar:186:ex4:words:6:zh":"(the route walked)","grammar:186:ex4:words:6:pos":"particle","grammar:186:ex4:words:7:zh":"walk","grammar:186:ex4:words:7:note":"あるく","grammar:186:ex4:words:7:pos":"verb","grammar:186:ex4:words:8:zh":"(nominalizes the action that is being decided)","grammar:186:ex4:words:8:pos":"noun","grammar:186:ex4:words:9:zh":"(the content of the decision)","grammar:186:ex4:words:9:pos":"particle","grammar:186:ex4:words:10:zh":"decide, choose","grammar:186:ex4:words:10:pos":"verb","grammar:186:ex4:words:11:zh":"(past, completed)","grammar:186:ex4:words:11:pos":"auxiliary verb","grammar:186:ex4:points:0":"「彼とは別の道」 means a road different from his, with 「と」 marking the object of comparison.","grammar:186:ex4:points:1":"「verb dictionary form + ことにする」 expresses making your own decision; the past form is 「ことにした」.","grammar:186:ex5:trans":"A different perspective is needed.","grammar:186:ex5:structure":"別の〜が必要です","grammar:186:ex5:words:0:zh":"different","grammar:186:ex5:words:0:note":"べつ","grammar:186:ex5:words:0:pos":"noun","grammar:186:ex5:words:1:zh":"'s","grammar:186:ex5:words:1:pos":"particle","grammar:186:ex5:words:2:zh":"perspective","grammar:186:ex5:words:2:note":"みかた","grammar:186:ex5:words:2:pos":"noun","grammar:186:ex5:words:3:zh":"(object)","grammar:186:ex5:words:3:pos":"particle","grammar:186:ex5:words:4:zh":"necessary","grammar:186:ex5:words:4:note":"ひつよう","grammar:186:ex5:words:4:pos":"na-adjective","grammar:186:ex5:words:5:zh":"(polite form)","grammar:186:ex5:words:5:pos":"copula","grammar:186:ex5:points:0":"見方：perspective / way of seeing (見る + 方).","grammar:186:ex5:points:1":"別の見方：another perspective."},"187":{"example:187:exzh":"My heart feels warm.","example:187:exzh2":"He has a kind heart.","example:187:exzh3":"Please calm your mind.","example:187:exzh4":"Inner peace is important.","example:187:exzh5":"I sincerely thank you.","grammar:187:ex:trans":"I feel warm inside.","grammar:187:ex:structure":"心が〜です","grammar:187:ex:explain":"This sentence uses 「心が〜です」 to describe an inner state. 「心（こころ）」 means heart or mind, and as the subject of the feeling it is marked with 「が」. 「温かい」 is an i-adjective meaning warm; adding 「です」 makes it polite. The whole sentence 「心が温かいです」 means I feel warm inside. This 「(body part / inner self)が + adjective」 frame works not only for physical sensations but also for abstract emotional states; 「心が温かい」 usually means feeling warmed by someone's kindness or goodwill.","grammar:187:ex:words:0:zh":"heart","grammar:187:ex:words:0:note":"こころ","grammar:187:ex:words:0:pos":"noun","grammar:187:ex:words:1:zh":"(nominative)","grammar:187:ex:words:1:pos":"particle","grammar:187:ex:words:2:zh":"warm","grammar:187:ex:words:2:note":"あたたかい","grammar:187:ex:words:2:pos":"adjective","grammar:187:ex:words:3:zh":"(polite form)","grammar:187:ex:words:3:pos":"copula","grammar:187:ex:points:0":"心（こころ）：heart, mind.","grammar:187:ex:points:1":"温かい：warm (i-adjective).","grammar:187:ex2:trans":"He is kind-hearted.","grammar:187:ex2:structure":"〜の心が〜","grammar:187:ex2:words:0:zh":"he","grammar:187:ex2:words:0:note":"かれ","grammar:187:ex2:words:0:pos":"pronoun","grammar:187:ex2:words:1:zh":"'s","grammar:187:ex2:words:1:pos":"particle","grammar:187:ex2:words:2:zh":"heart","grammar:187:ex2:words:2:note":"こころ","grammar:187:ex2:words:2:pos":"noun","grammar:187:ex2:words:3:zh":"(nominative)","grammar:187:ex2:words:3:pos":"particle","grammar:187:ex2:words:4:zh":"kind-hearted","grammar:187:ex2:words:4:note":"やさしい","grammar:187:ex2:words:4:pos":"adjective","grammar:187:ex2:points:0":"心が優しい：kind-hearted.","grammar:187:ex2:points:1":"彼の心：his heart / his inner self.","grammar:187:ex3:trans":"Please calm your mind.","grammar:187:ex3:structure":"心を落ち着けてください","grammar:187:ex3:explain":"「心を」 marks what is to be calmed, and 「落ち着ける」 means to actively settle something. 「落ち着けて」 is the te-form of this transitive verb, and with 「ください」 it forms a request. Note that 「落ち着け」 here is the stem (continuative form) of 「落ち着ける」, not an imperative.","grammar:187:ex3:words:0:zh":"heart, mind","grammar:187:ex3:words:0:note":"こころ","grammar:187:ex3:words:0:pos":"noun","grammar:187:ex3:words:1:zh":"(object)","grammar:187:ex3:words:1:pos":"particle","grammar:187:ex3:words:2:zh":"to calm, to settle","grammar:187:ex3:words:2:note":"おちつけ","grammar:187:ex3:words:2:pos":"verb","grammar:187:ex3:words:3:zh":"(connects to a request expression)","grammar:187:ex3:words:3:pos":"particle","grammar:187:ex3:words:4:zh":"please","grammar:187:ex3:words:4:pos":"verb","grammar:187:ex3:points:0":"「落ち着ける」 is a transitive verb meaning to make something settle, which is why you say 「心を落ち着ける」.","grammar:187:ex3:points:1":"「落ち着く」 is the intransitive verb; 「落ち着いてください」 simply means please calm down.","grammar:187:ex4:trans":"Peace of mind is important.","grammar:187:ex4:structure":"〜の〜が大切です","grammar:187:ex4:words:0:zh":"heart","grammar:187:ex4:words:0:note":"こころ","grammar:187:ex4:words:0:pos":"noun","grammar:187:ex4:words:1:zh":"'s","grammar:187:ex4:words:1:pos":"particle","grammar:187:ex4:words:2:zh":"peace / calm","grammar:187:ex4:words:2:note":"へいわ","grammar:187:ex4:words:2:pos":"noun","grammar:187:ex4:words:3:zh":"(nominative)","grammar:187:ex4:words:3:pos":"particle","grammar:187:ex4:words:4:zh":"important","grammar:187:ex4:words:4:note":"たいせつ","grammar:187:ex4:words:4:pos":"na-adjective","grammar:187:ex4:words:5:zh":"(polite form)","grammar:187:ex4:words:5:pos":"copula","grammar:187:ex4:points:0":"心の平和：peace of mind.","grammar:187:ex4:points:1":"〜が大切です：…is important.","grammar:187:ex5:trans":"Thank you from the bottom of my heart.","grammar:187:ex5:structure":"心から〜しています","grammar:187:ex5:words:0:zh":"from the heart","grammar:187:ex5:words:0:note":"こころから","grammar:187:ex5:words:0:pos":"adverb","grammar:187:ex5:words:1:zh":"am grateful","grammar:187:ex5:words:1:note":"かんしゃしています","grammar:187:ex5:words:1:pos":"verb","grammar:187:ex5:points:0":"心から：from the bottom of one's heart (idiomatic).","grammar:187:ex5:points:1":"感謝する：to be grateful / to give thanks."},"188":{"example:188:exzh":"I'll go alone.","example:188:exzh2":"Just one person?","example:188:exzh3":"He lives alone.","example:188:exzh4":"I like time alone.","example:188:exzh5":"I have one friend.","grammar:188:ex:trans":"I'll go alone.","grammar:188:ex:structure":"一人で行きます","grammar:188:ex:explain":"This sentence uses 「一人で」 to mean alone. 「一人（ひとり）」 means one person, and adding 「で」 shows the state or manner in which the action happens: 「一人で」 means doing something alone. The verb 「行く」 in polite form is 「行きます」. The whole sentence 「一人で行きます」 means I'll go alone. Here 「で」 marks a state or manner; it works the same way as 「皆で」 (all together), pointing out the number of people or the circumstances the action takes place in.","grammar:188:ex:words:0:zh":"one person","grammar:188:ex:words:0:note":"ひとり","grammar:188:ex:words:0:pos":"noun","grammar:188:ex:words:1:zh":"(state / manner)","grammar:188:ex:words:1:pos":"particle","grammar:188:ex:words:2:zh":"go","grammar:188:ex:words:2:pos":"verb","grammar:188:ex:points:0":"❓一人で：alone (で marks state / manner).","grammar:188:ex:points:1":"一人 (ひとり): one person.","grammar:188:ex2:trans":"Is it just one person?","grammar:188:ex2:structure":"一人だけですか","grammar:188:ex2:words:0:zh":"one person","grammar:188:ex2:words:0:note":"ひとり","grammar:188:ex2:words:0:pos":"noun","grammar:188:ex2:words:1:zh":"only","grammar:188:ex2:words:1:pos":"particle","grammar:188:ex2:words:2:zh":"is","grammar:188:ex2:words:2:pos":"copula","grammar:188:ex2:words:3:zh":"(question)","grammar:188:ex2:words:3:pos":"particle","grammar:188:ex2:points:0":"一人だけ：only one person (だけ limits).","grammar:188:ex2:points:1":"〜ですか: question.","grammar:188:ex3:trans":"He lives alone.","grammar:188:ex3:structure":"〜は一人暮らしです","grammar:188:ex3:words:0:zh":"he","grammar:188:ex3:words:0:note":"かれ","grammar:188:ex3:words:0:pos":"pronoun","grammar:188:ex3:words:1:zh":"(topic)","grammar:188:ex3:words:1:pos":"particle","grammar:188:ex3:words:2:zh":"lives alone","grammar:188:ex3:words:2:note":"ひとりぐらし","grammar:188:ex3:words:2:pos":"noun","grammar:188:ex3:words:3:zh":"is","grammar:188:ex3:words:3:pos":"copula","grammar:188:ex3:points:0":"一人暮らし：living alone (一人 + 暮らし).","grammar:188:ex3:points:1":"noun＋です.","grammar:188:ex4:trans":"I like time alone.","grammar:188:ex4:structure":"〜が好きです","grammar:188:ex4:words:0:zh":"one person","grammar:188:ex4:words:0:note":"ひとり","grammar:188:ex4:words:0:pos":"noun","grammar:188:ex4:words:1:zh":"'s","grammar:188:ex4:words:1:pos":"particle","grammar:188:ex4:words:2:zh":"time","grammar:188:ex4:words:2:note":"じかん","grammar:188:ex4:words:2:pos":"noun","grammar:188:ex4:words:3:zh":"(object)","grammar:188:ex4:words:3:pos":"particle","grammar:188:ex4:words:4:zh":"to like","grammar:188:ex4:words:4:note":"すき","grammar:188:ex4:words:4:pos":"na-adjective","grammar:188:ex4:words:5:zh":"(polite form)","grammar:188:ex4:words:5:pos":"copula","grammar:188:ex4:points:0":"一人の時間：time alone.","grammar:188:ex4:points:1":"The object of 「好き」 takes が.","grammar:188:ex5:trans":"I have a friend.","grammar:188:ex5:structure":"〜がいます","grammar:188:ex5:words:0:zh":"one","grammar:188:ex5:words:0:note":"ひとり","grammar:188:ex5:words:0:pos":"noun","grammar:188:ex5:words:1:zh":"'s","grammar:188:ex5:words:1:pos":"particle","grammar:188:ex5:words:2:zh":"friend","grammar:188:ex5:words:2:note":"ともだち","grammar:188:ex5:words:2:pos":"noun","grammar:188:ex5:words:3:zh":"(nominative)","grammar:188:ex5:words:3:pos":"particle","grammar:188:ex5:words:4:zh":"there is / are","grammar:188:ex5:words:4:pos":"verb","grammar:188:ex5:points:0":"一人の友達：one friend.","grammar:188:ex5:points:1":"〜がいます：there is (a person).","exam:188:zh":"Nobody else is coming, so today I'll open the shop alone.","exam:188:why":"Since no one else is coming, it's 「一人」 (one person). If you chose 「二人」, that would mean there's another person too, which contradicts the earlier information."},"189":{"example:189:exzh":"Five or more people will participate.","example:189:exzh2":"It's more important than all opinions.","example:189:exzh3":"There's no better friend than him.","example:189:exzh4":"It won't cost any more than this.","example:189:exzh5":"I went there over three years ago.","grammar:189:ex:trans":"Five or more people will take part.","grammar:189:ex:structure":"〜以上が〜ます","grammar:189:ex:explain":"This sentence uses 「〜以上」 to give a lower limit on a number. 「以上」 means …or more and includes that number itself, so 「5人以上」 means five people or more. 「が」 marks the subject. The verb 「参加する」 is a noun + する verb, and its polite form is 「参加します」. The whole sentence 「5人以上が参加します」 means five or more people will take part. Remember that 「以上」 includes the number itself — 「5人以上」 counts five people in — while 「未満」 excludes it, so keep the two apart.","grammar:189:ex:words:0:zh":"five people","grammar:189:ex:words:0:note":"ごにん","grammar:189:ex:words:0:pos":"noun","grammar:189:ex:words:1:zh":"or more","grammar:189:ex:words:1:note":"いじょう","grammar:189:ex:words:1:pos":"noun","grammar:189:ex:words:2:zh":"(nominative)","grammar:189:ex:words:2:pos":"particle","grammar:189:ex:words:3:zh":"join","grammar:189:ex:words:3:note":"さんかします","grammar:189:ex:words:3:pos":"verb","grammar:189:ex:points:0":"〜以上：…or more (including that number).","grammar:189:ex:points:1":"5人以上：five or more people (five included).","grammar:189:ex2:trans":"It matters more than any opinion.","grammar:189:ex2:structure":"〜以上に大切です","grammar:189:ex2:words:0:zh":"all","grammar:189:ex2:words:0:pos":"noun","grammar:189:ex2:words:1:zh":"'s","grammar:189:ex2:words:1:pos":"particle","grammar:189:ex2:words:2:zh":"opinion","grammar:189:ex2:words:2:note":"いけん","grammar:189:ex2:words:2:pos":"noun","grammar:189:ex2:words:3:zh":"or more","grammar:189:ex2:words:3:note":"いじょう","grammar:189:ex2:words:3:pos":"noun","grammar:189:ex2:words:4:zh":"(comparison)","grammar:189:ex2:words:4:pos":"particle","grammar:189:ex2:words:5:zh":"important","grammar:189:ex2:words:5:note":"たいせつ","grammar:189:ex2:words:5:pos":"na-adjective","grammar:189:ex2:words:6:zh":"(polite form)","grammar:189:ex2:words:6:pos":"copula","grammar:189:ex2:points:0":"〜以上に：more… than… (degree).","grammar:189:ex2:points:1":"すべての意見：all opinions.","grammar:189:ex3:trans":"There's no better friend than him.","grammar:189:ex3:structure":"〜以上の〜はいない","grammar:189:ex3:words:0:zh":"he","grammar:189:ex3:words:0:note":"かれ","grammar:189:ex3:words:0:pos":"pronoun","grammar:189:ex3:words:1:zh":"or more","grammar:189:ex3:words:1:note":"いじょう","grammar:189:ex3:words:1:pos":"noun","grammar:189:ex3:words:2:zh":"'s","grammar:189:ex3:words:2:pos":"particle","grammar:189:ex3:words:3:zh":"friend","grammar:189:ex3:words:3:note":"ゆうじん","grammar:189:ex3:words:3:pos":"noun","grammar:189:ex3:words:4:zh":"(topic)","grammar:189:ex3:words:4:pos":"particle","grammar:189:ex3:words:5:zh":"don't have","grammar:189:ex3:words:5:pos":"verb","grammar:189:ex3:points:0":"〜以上の：surpassing… (comparison).","grammar:189:ex3:points:1":"いない：there is no (one) (the negative of いる).","grammar:189:ex4:trans":"It won't cost any more.","grammar:189:ex4:structure":"これ以上は〜ません","grammar:189:ex4:words:0:zh":"any more / beyond this","grammar:189:ex4:words:0:note":"これいじょう","grammar:189:ex4:words:0:pos":"adverb","grammar:189:ex4:words:1:zh":"(contrast)","grammar:189:ex4:words:1:pos":"particle","grammar:189:ex4:words:2:zh":"doesn't cost","grammar:189:ex4:words:2:pos":"verb","grammar:189:ex4:points:0":"これ以上：any more, beyond this.","grammar:189:ex4:points:1":"かかる：to take / to cost (time or money); かかりません is the negative.","grammar:189:ex5:trans":"I went there over three years ago.","grammar:189:ex5:structure":"〜前に行きました","grammar:189:ex5:words:0:zh":"three years","grammar:189:ex5:words:0:note":"さんねん","grammar:189:ex5:words:0:pos":"noun","grammar:189:ex5:words:1:zh":"or more","grammar:189:ex5:words:1:note":"いじょう","grammar:189:ex5:words:1:pos":"noun","grammar:189:ex5:words:2:zh":"before","grammar:189:ex5:words:2:note":"まえ","grammar:189:ex5:words:2:pos":"noun","grammar:189:ex5:words:3:zh":"(point in time)","grammar:189:ex5:words:3:pos":"particle","grammar:189:ex5:words:4:zh":"went","grammar:189:ex5:words:4:note":"いきました","grammar:189:ex5:words:4:pos":"verb","grammar:189:ex5:points:0":"3年以上前：more than three years ago.","grammar:189:ex5:points:1":"〜前に：before… (a point in time)."},"190":{"example:190:exzh":"This road is long.","example:190:exzh2":"Her hair is long.","example:190:exzh3":"I waited a long time.","example:190:exzh4":"I told a long story.","example:190:exzh5":"It takes a long time.","grammar:190:ex:trans":"This road is long.","grammar:190:ex:structure":"〜は長いです","grammar:190:ex:explain":"This is a comment sentence with an i-adjective as the predicate. 「道（みち）」 means road, and 「この」 is a pre-noun adjectival that modifies it directly. 「は」 makes this road the topic; the predicate 「長い」 is an i-adjective meaning long, and adding 「です」 makes it polite. The whole sentence 「この道は長いです」 means this road is long. 「長い」 refers to length, so keep it apart from 「高い」 (tall) and 「広い」 (wide) — all basic i-adjectives for describing spatial properties.","grammar:190:ex:words:0:zh":"this","grammar:190:ex:words:0:pos":"pre-noun adjectival","grammar:190:ex:words:1:zh":"road","grammar:190:ex:words:1:note":"みち","grammar:190:ex:words:1:pos":"noun","grammar:190:ex:words:2:zh":"(topic)","grammar:190:ex:words:2:pos":"particle","grammar:190:ex:words:3:zh":"long","grammar:190:ex:words:3:note":"ながい","grammar:190:ex:words:3:pos":"adjective","grammar:190:ex:words:4:zh":"(polite form)","grammar:190:ex:words:4:pos":"copula","grammar:190:ex:points:0":"長い：long (i-adjective).","grammar:190:ex:points:1":"この道は長い：this road is long.","grammar:190:ex2:trans":"Her hair is long.","grammar:190:ex2:structure":"〜の髪は長い","grammar:190:ex2:words:0:zh":"she","grammar:190:ex2:words:0:note":"かのじょ","grammar:190:ex2:words:0:pos":"pronoun","grammar:190:ex2:words:1:zh":"'s","grammar:190:ex2:words:1:pos":"particle","grammar:190:ex2:words:2:zh":"hair","grammar:190:ex2:words:2:note":"かみ","grammar:190:ex2:words:2:pos":"noun","grammar:190:ex2:words:3:zh":"(topic)","grammar:190:ex2:words:3:pos":"particle","grammar:190:ex2:words:4:zh":"long","grammar:190:ex2:words:4:note":"ながい","grammar:190:ex2:words:4:pos":"adjective","grammar:190:ex2:points:0":"髪（かみ）：hair.","grammar:190:ex2:points:1":"長い：plain-form ending.","grammar:190:ex3:trans":"I waited a long time.","grammar:190:ex3:structure":"長い間〜ました","grammar:190:ex3:words:0:zh":"a long time","grammar:190:ex3:words:0:note":"ながいあいだ","grammar:190:ex3:words:0:pos":"adverb","grammar:190:ex3:words:1:zh":"waited","grammar:190:ex3:words:1:note":"まちました","grammar:190:ex3:words:1:pos":"verb","grammar:190:ex3:points:0":"長い間：for a long time (idiomatic).","grammar:190:ex3:points:1":"待つ→待ちました。","grammar:190:ex4:trans":"I told a long story.","grammar:190:ex4:structure":"長い話をしました","grammar:190:ex4:words:0:zh":"long","grammar:190:ex4:words:0:note":"ながい","grammar:190:ex4:words:0:pos":"adjective","grammar:190:ex4:words:1:zh":"story / talk","grammar:190:ex4:words:1:note":"はなし","grammar:190:ex4:words:1:pos":"noun","grammar:190:ex4:words:2:zh":"(object marker)","grammar:190:ex4:words:2:pos":"particle","grammar:190:ex4:words:3:zh":"did","grammar:190:ex4:words:3:pos":"verb","grammar:190:ex4:points:0":"長い話：a long story / a lengthy talk.","grammar:190:ex4:points:1":"話をする: to talk, to tell a story.","grammar:190:ex5:trans":"It takes a long time.","grammar:190:ex5:structure":"長い時間かかります","grammar:190:ex5:words:0:zh":"long","grammar:190:ex5:words:0:note":"ながい","grammar:190:ex5:words:0:pos":"adjective","grammar:190:ex5:words:1:zh":"time","grammar:190:ex5:words:1:note":"じかん","grammar:190:ex5:words:1:pos":"noun","grammar:190:ex5:words:2:zh":"to take (time)","grammar:190:ex5:words:2:pos":"verb","grammar:190:ex5:points:0":"時間がかかる: to take time (the が is omitted here).","grammar:190:ex5:points:1":"長い時間: a long time.","exam:190:zh":"This string is a full five meters long, so it's longer than a one-meter string.","exam:190:why":"Meters measure length, so five meters is 「長い」 than one meter. 「太い」 means thick, which you can't judge from the length."},"191":{"example:191:exzh":"I've been waiting the whole time.","example:191:exzh2":"I'll stay here the whole time.","example:191:exzh3":"I've always loved her.","example:191:exzh4":"I've been thinking about it the whole time.","example:191:exzh5":"We kept talking the whole time.","grammar:191:ex:trans":"I've been waiting the whole time.","grammar:191:ex:structure":"ずっと〜ています","grammar:191:ex:explain":"This sentence uses the adverb 「ずっと」 with 「ている」. 「ずっと」 means all along, continuously, and emphasizes that an action or state goes on without a break for a long time. The verb 「待つ」 in its te-form 「待って」 plus 「います」 — 「〜ている」 expresses ongoing continuation — and adding 「ずっと」 makes the ongoing sense of waiting even stronger: 「ずっと待っています」 = waiting all along. The whole sentence 「ずっと待っています」 = I've been waiting the whole time. 「ずっと」 can also mean far away or much more in terms of space or degree, so judge from context.","grammar:191:ex:words:0:zh":"all along","grammar:191:ex:words:0:pos":"adverb","grammar:191:ex:words:1:zh":"waiting","grammar:191:ex:words:1:note":"まっています","grammar:191:ex:words:1:pos":"verb","grammar:191:ex:points:0":"ずっと: all along, continuously.","grammar:191:ex:points:1":"〜ている: ongoing continuation.","grammar:191:ex2:trans":"I'll be here the whole time.","grammar:191:ex2:structure":"ずっと〜にいます","grammar:191:ex2:words:0:zh":"all along","grammar:191:ex2:words:0:pos":"adverb","grammar:191:ex2:words:1:zh":"here","grammar:191:ex2:words:1:pos":"pronoun","grammar:191:ex2:words:2:zh":"(location of existence)","grammar:191:ex2:words:2:pos":"particle","grammar:191:ex2:words:3:zh":"exist","grammar:191:ex2:words:3:pos":"verb","grammar:191:ex2:points:0":"ずっと: the whole time.","grammar:191:ex2:points:1":"ここにいる: to be here.","grammar:191:ex3:trans":"I've loved her all along.","grammar:191:ex3:structure":"〜をずっと〜ています","grammar:191:ex3:words:0:zh":"she","grammar:191:ex3:words:0:note":"かのじょ","grammar:191:ex3:words:0:pos":"pronoun","grammar:191:ex3:words:1:zh":"(object marker)","grammar:191:ex3:words:1:pos":"particle","grammar:191:ex3:words:2:zh":"all along","grammar:191:ex3:words:2:pos":"adverb","grammar:191:ex3:words:3:zh":"loving","grammar:191:ex3:words:3:note":"あいしています","grammar:191:ex3:words:3:pos":"verb","grammar:191:ex3:points:0":"❓The object of 愛する takes を (人を愛する).","grammar:191:ex3:points:1":"〜ている：a continuing state.","grammar:191:ex4:trans":"I've been thinking about it.","grammar:191:ex4:structure":"ずっと〜ています","grammar:191:ex4:words:0:zh":"all along","grammar:191:ex4:words:0:pos":"adverb","grammar:191:ex4:words:1:zh":"thinking about","grammar:191:ex4:words:1:note":"かんがえています","grammar:191:ex4:words:1:pos":"verb","grammar:191:ex4:points:0":"ずっと考えている: to keep thinking about it.","grammar:191:ex4:points:1":"〜ている: continuing.","grammar:191:ex5:trans":"were chatting the whole time.","grammar:191:ex5:structure":"ずっと〜ていました","grammar:191:ex5:words:0:zh":"all along","grammar:191:ex5:words:0:pos":"adverb","grammar:191:ex5:words:1:zh":"(past) was talking","grammar:191:ex5:words:1:note":"はなしていました","grammar:191:ex5:words:1:pos":"verb","grammar:191:ex5:points:0":"〜ていました: was …ing continuously over a period in the past.","grammar:191:ex5:points:1":"話す→話して＋いました。"},"192":{"example:192:exzh":"Let's do it one more time.","example:192:exzh2":"I practiced three times.","example:192:exzh3":"The next one will be interesting.","example:192:exzh4":"The number of times is high.","example:192:exzh5":"He has repeated it many times.","grammar:192:ex:trans":"Let's do it one more time.","grammar:192:ex:structure":"もう一回〜ましょう","grammar:192:ex:explain":"This sentence uses 「もう一回」＋「〜ましょう」 to suggest doing something again. 「もう一回」 is made up of 「もう」 (again) and 「一回」 (one time); 「回」 is the counter for occurrences, so 「もう一回」 = one more time, the same meaning as 「もう一度」. The verb 「やる」 becomes its volitional form 「やりましょう」, meaning let's (do it together). The whole sentence 「もう一回やりましょう」 = Let's do it one more time. 「やる」 is a casual synonym of 「する」, so the tone is more relaxed and suits people you're close to.","grammar:192:ex:words:0:zh":"one more time","grammar:192:ex:words:0:note":"もういっかい","grammar:192:ex:words:0:pos":"adverb","grammar:192:ex:words:1:zh":"let's do","grammar:192:ex:words:1:note":"やりましょう","grammar:192:ex:words:1:pos":"verb","grammar:192:ex:points:0":"もう一回: one more time (回 = counter for occurrences).","grammar:192:ex:points:1":"やる→やりましょう: a suggestion.","grammar:192:ex2:trans":"practiced three times.","grammar:192:ex2:structure":"〜回〜しました","grammar:192:ex2:words:0:zh":"three times","grammar:192:ex2:words:0:note":"さんかい","grammar:192:ex2:words:0:pos":"noun","grammar:192:ex2:words:1:zh":"practiced","grammar:192:ex2:words:1:note":"れんしゅうしました","grammar:192:ex2:words:1:pos":"verb","grammar:192:ex2:points:0":"〜回: …times (counter for occurrences).","grammar:192:ex2:points:1":"練習する→練習しました。","grammar:192:ex3:trans":"The next one will be interesting.","grammar:192:ex3:structure":"次の回は〜です","grammar:192:ex3:words:0:zh":"next","grammar:192:ex3:words:0:note":"つぎ","grammar:192:ex3:words:0:pos":"noun","grammar:192:ex3:words:1:zh":"'s","grammar:192:ex3:words:1:pos":"particle","grammar:192:ex3:words:2:zh":"return","grammar:192:ex3:words:2:note":"かい","grammar:192:ex3:words:2:pos":"noun","grammar:192:ex3:words:3:zh":"(topic)","grammar:192:ex3:words:3:pos":"particle","grammar:192:ex3:words:4:zh":"interesting","grammar:192:ex3:words:4:note":"おもしろい","grammar:192:ex3:words:4:pos":"adjective","grammar:192:ex3:words:5:zh":"(polite form)","grammar:192:ex3:words:5:pos":"copula","grammar:192:ex3:points:0":"次の回: the next one / next time.","grammar:192:ex3:points:1":"回（かい）: time, occurrence.","grammar:192:ex4:trans":"The number of times is high.","grammar:192:ex4:structure":"〜が多いです","grammar:192:ex4:words:0:zh":"number of times","grammar:192:ex4:words:0:note":"かいすう","grammar:192:ex4:words:0:pos":"noun","grammar:192:ex4:words:1:zh":"(nominative)","grammar:192:ex4:words:1:pos":"particle","grammar:192:ex4:words:2:zh":"many","grammar:192:ex4:words:2:note":"おおい","grammar:192:ex4:words:2:pos":"adjective","grammar:192:ex4:words:3:zh":"(polite form)","grammar:192:ex4:words:3:pos":"copula","grammar:192:ex4:points:0":"回数（かいすう）: number of times.","grammar:192:ex4:points:1":"多い: many (i-adjective).","grammar:192:ex5:trans":"He has done it many times over.","grammar:192:ex5:structure":"回を重ねています","grammar:192:ex5:words:0:zh":"he","grammar:192:ex5:words:0:note":"かれ","grammar:192:ex5:words:0:pos":"pronoun","grammar:192:ex5:words:1:zh":"(topic)","grammar:192:ex5:words:1:pos":"particle","grammar:192:ex5:words:2:zh":"number of times","grammar:192:ex5:words:2:note":"かい","grammar:192:ex5:words:2:pos":"noun","grammar:192:ex5:words:3:zh":"(object marker)","grammar:192:ex5:words:3:pos":"particle","grammar:192:ex5:words:4:zh":"accumulating","grammar:192:ex5:words:4:note":"かさねています","grammar:192:ex5:words:4:pos":"verb","grammar:192:ex5:points:0":"回を重ねる: to pile one time on top of another (idiomatic).","grammar:192:ex5:points:1":"重ねる: to layer, to accumulate.","exam:192:zh":"I watched the same movie once, and then watched it again the next day.","exam:192:why":"You use 「回」 to count the number of times you watch. 「枚」 counts thin, flat things like sheets of paper, so it can't count how many times you watch a movie."},"193":{"example:193:exzh":"The room is clean.","example:193:exzh2":"A friend is in the room.","example:193:exzh3":"His room is small.","example:193:exzh4":"I cleaned the room.","example:193:exzh5":"I put flowers in the room.","grammar:193:ex:trans":"The room is clean.","grammar:193:ex:structure":"部屋がきれいです","grammar:193:ex:explain":"This sentence uses 「〜がきれいです」 to describe a state. 「部屋（へや）」 means room, and the subject is marked with 「が」. 「きれい」 is a na-adjective meaning clean, pretty, and it attaches directly to 「です」. The whole sentence 「部屋がきれいです」 = The room is clean. Note that although 「きれい」 ends in 「い」, it is a na-adjective (add な when modifying a noun, as in きれいな部屋), so don't mistake it for an i-adjective conjugation. This is a common trap word for beginners.","grammar:193:ex:words:0:zh":"room","grammar:193:ex:words:0:note":"へや","grammar:193:ex:words:0:pos":"noun","grammar:193:ex:words:1:zh":"(nominative)","grammar:193:ex:words:1:pos":"particle","grammar:193:ex:words:2:zh":"clean","grammar:193:ex:words:2:pos":"na-adjective","grammar:193:ex:words:3:zh":"(polite form)","grammar:193:ex:words:3:pos":"copula","grammar:193:ex:points:0":"部屋（へや）: room.","grammar:193:ex:points:1":"きれい: clean / pretty (na-adjective; the subject takes が).","grammar:193:ex2:trans":"There's a friend in the room.","grammar:193:ex2:structure":"〜に〜がいます","grammar:193:ex2:words:0:zh":"room","grammar:193:ex2:words:0:note":"へや","grammar:193:ex2:words:0:pos":"noun","grammar:193:ex2:words:1:zh":"(location of existence)","grammar:193:ex2:words:1:pos":"particle","grammar:193:ex2:words:2:zh":"friend","grammar:193:ex2:words:2:note":"ともだち","grammar:193:ex2:words:2:pos":"noun","grammar:193:ex2:words:3:zh":"(nominative)","grammar:193:ex2:words:3:pos":"particle","grammar:193:ex2:words:4:zh":"there is / are","grammar:193:ex2:words:4:pos":"verb","grammar:193:ex2:points:0":"に＋がいます: there is (a person) in a place.","grammar:193:ex2:points:1":"部屋に: in the room.","grammar:193:ex3:trans":"His room is small.","grammar:193:ex3:structure":"〜の部屋は〜です","grammar:193:ex3:words:0:zh":"he","grammar:193:ex3:words:0:note":"かれ","grammar:193:ex3:words:0:pos":"pronoun","grammar:193:ex3:words:1:zh":"'s","grammar:193:ex3:words:1:pos":"particle","grammar:193:ex3:words:2:zh":"room","grammar:193:ex3:words:2:note":"へや","grammar:193:ex3:words:2:pos":"noun","grammar:193:ex3:words:3:zh":"(topic)","grammar:193:ex3:words:3:pos":"particle","grammar:193:ex3:words:4:zh":"cramped","grammar:193:ex3:words:4:note":"せまい","grammar:193:ex3:words:4:pos":"adjective","grammar:193:ex3:words:5:zh":"(polite form)","grammar:193:ex3:words:5:pos":"copula","grammar:193:ex3:points:0":"狭い: cramped, narrow (i-adjective).","grammar:193:ex3:points:1":"彼の部屋: his room.","grammar:193:ex4:trans":"cleaned the room.","grammar:193:ex4:structure":"〜を掃除しました","grammar:193:ex4:words:0:zh":"room","grammar:193:ex4:words:0:note":"へや","grammar:193:ex4:words:0:pos":"noun","grammar:193:ex4:words:1:zh":"(object marker)","grammar:193:ex4:words:1:pos":"particle","grammar:193:ex4:words:2:zh":"cleaned","grammar:193:ex4:words:2:note":"そうじしました","grammar:193:ex4:words:2:pos":"verb","grammar:193:ex4:points:0":"部屋を掃除する: to clean a room.","grammar:193:ex4:points:1":"掃除する→掃除しました。","grammar:193:ex5:trans":"Placed flowers in the room.","grammar:193:ex5:structure":"〜に〜を飾った","grammar:193:ex5:words:0:zh":"room","grammar:193:ex5:words:0:note":"へや","grammar:193:ex5:words:0:pos":"noun","grammar:193:ex5:words:1:zh":"(the destination point)","grammar:193:ex5:words:1:pos":"particle","grammar:193:ex5:words:2:zh":"flowers","grammar:193:ex5:words:2:note":"はな","grammar:193:ex5:words:2:pos":"noun","grammar:193:ex5:words:3:zh":"(object marker)","grammar:193:ex5:words:3:pos":"particle","grammar:193:ex5:words:4:zh":"decorated","grammar:193:ex5:words:4:note":"かざった","grammar:193:ex5:words:4:pos":"verb","grammar:193:ex5:points:0":"〜に〜を飾る: to place / decorate … in ….","grammar:193:ex5:points:1":"飾る→飾った (past plain form).","exam:193:zh":"This hotel has ten rooms with two beds.","exam:193:why":"A space in a hotel with beds for guests to stay in is a 「部屋」. 「台所」 is a kitchen, not a space where beds for guests are placed."}};